  const naamLbl = document.getElementById("naamHKLabel");
  if (naamLbl)
    naamLbl.textContent = isBn ? "হরে কৃষ্ণ মহামন্ত্র" : "हरे कृष्ण महामंत्र";
  // 2. Settings language toggle label
  const langLbl = document.getElementById("hkLangLabel");
