    dtLbl.textContent = isBn
      ? "🪷 হরে কৃষ্ণ মহামন্ত্র Targets"
      : "🪷 हरे कृष्ण महामंत्र Targets";
  // 5. Stats card lotus title
  const statsLotus = document.getElementById("hkcTitleLotus");
