// ── Radha Vallabh Sampraday: mala-complete name display (5 seconds) ──
// Reuses the app's existing glowing mala-complete flash (#mf, the one that used to
// read "Radha Vallabh / Sri Harivansh" in English) and swaps its text for the four
// holy names. Sound + deity-image glow come from malaOk(). App.ht() ignores taps
// for the duration via window._rvNamesLock — no overlay/curtain is drawn.
const RV_MALA_NAMES_BN = ["রাধাবল্লভ", "শ্রী হরিবংশ", "শ্রী বৃন্দাবন", "শ্রীবনচংদ"];
const RV_MALA_NAMES_SA = ["राधावल्लभ", "श्री हरिवंश", "श्री वृन्दावन", "श्रीवनचंद"];
const RV_MALA_NAMES_MS = 5000;
let _rvNamesTimer = null;
let _rvNamesRestore = null;

function showRVSampradayMalaNames() {
  // If a previous display is somehow still up, restore it first
  clearTimeout(_rvNamesTimer);
  if (_rvNamesRestore) { _rvNamesRestore(); _rvNamesRestore = null; }

  // The app's .mf flash animation (keyframes "mc") is 3s/4s; add a 5s variant
  if (!document.getElementById("rvMalaNamesCSS")) {
    const st = document.createElement("style");
    st.id = "rvMalaNamesCSS";
    st.textContent = ".mf.show-rv{animation:mc " + (RV_MALA_NAMES_MS / 1000) + "s ease-in-out forwards;}";
    document.head.appendChild(st);
  }

  window._rvNamesLock = true;
  const isBn = App.S && App.S.naamLang === "bn";
  const names = isBn ? RV_MALA_NAMES_BN : RV_MALA_NAMES_SA;
  const mf = document.getElementById("mf");

  if (mf) {
    const l1e = mf.querySelector(".mf-line1");
    const l2e = mf.querySelector(".mf-line2");
    const o1 = l1e ? l1e.textContent : "";
    const o2 = l2e ? l2e.textContent : "";
    const ff = isBn
      ? "'Hind Siliguri','Tiro Devanagari Hindi',serif"
      : "'Tiro Devanagari Hindi','Hind Siliguri',serif";
    const goldGlow = "0 0 20px rgba(255,215,0,0.9),0 0 40px rgba(255,215,0,0.5)";
    const styleName = (el) => {
      el.style.fontFamily = ff;
      el.style.color = "var(--gold)";
      el.style.textShadow = goldGlow;
      el.style.letterSpacing = "1px";
      el.style.lineHeight = "1.35";
      el.style.fontSize = "clamp(30px,8.4vw,44px)"; // same size for all 4 lines
    };
    const extras = [];
    if (l1e) {
      l1e.textContent = names[0];
      l1e.style.fontFamily = ff;
      l1e.style.lineHeight = "1.35";
      l1e.style.letterSpacing = "1px";
      l1e.style.fontSize = "clamp(30px,8.4vw,44px)";
    }
    if (l2e) {
      l2e.textContent = names[1];
      styleName(l2e);
      l2e.style.marginTop = "0";
      let prev = l2e;
      [names[2], names[3]].forEach((n) => {
        const c = document.createElement("div");
        c.className = "mf-line2";
        c.textContent = n;
        styleName(c);
        c.style.marginTop = "0";
        prev.parentNode.insertBefore(c, prev.nextSibling);
        extras.push(c);
        prev = c;
      });
    }
    // Restart the CSS animation cleanly, then run the 5s variant
    mf.classList.remove("show", "show-long", "show-rv");
    void mf.offsetWidth;
    mf.classList.add("show-rv");
    _rvNamesRestore = function () {
      mf.classList.remove("show-rv");
      extras.forEach((c) => c.remove());
      if (l1e) { l1e.textContent = o1; ["fontFamily","lineHeight","letterSpacing","fontSize"].forEach((k) => { l1e.style[k] = ""; }); }
      if (l2e) {
        l2e.textContent = o2;
        ["fontFamily","color","textShadow","letterSpacing","lineHeight","fontSize","marginTop"]
          .forEach((k) => { l2e.style[k] = ""; });
      }
    };
  }

  _rvNamesTimer = setTimeout(() => {
    window._rvNamesLock = false;
    if (_rvNamesRestore) { _rvNamesRestore(); _rvNamesRestore = null; }
  }, RV_MALA_NAMES_MS);
}

// Prevent double-tap zoom
let lt2 = 0;
document.addEventListener(
  "touchend",
  (e) => {
    // Only skip the guard inside the scrollable lyric text itself — repeated
    // flick-scrolls there can land within 300ms of each other, and cancelling
    // that touchend interrupts native momentum scrolling (feels stuck/shaky).
    // Everywhere else inside the lyrics modal — importantly the Prev/Next
    // buttons — must keep this guard. Without it, a quick double-tap on
    // "Next" was both (a) triggering Android's native double-tap-zoom
    // gesture (a visual flicker that looked like a "ghost"/duplicate of the
    // button during the zoom animation) and (b) letting two click events
    // reach verseNav() almost simultaneously, which skipped an extra verse
    // (the "unpredictable jump" to next/previous).
    if (e.target && e.target.closest && e.target.closest(".lm-card-inner"))
      return;
    const n = Date.now();
    if (n - lt2 < 300) e.preventDefault();
    lt2 = n;
  },
  { passive: false },
);

// Stats timer tick
setInterval(() => {
  App.updateTimerToday();
}, 1000);

// 28 Names stats panel live tick — refreshes time while timer is running
setInterval(() => {
  if (App._n28TimerInterval) refresh28StatsIfOpen();
}, 2000);

// ── Midnight date-rollover check ──
// Fixes mala log not resetting when app stays open past midnight
setInterval(() => {
  const newTk = App.getTk();
  if (newTk !== App.S.tk) {
    App.S.tk = newTk;
    App.S.malaLog = [];
    App.S.malaLogRV = [];
    App.S.malaLogHK = [];
    App.S.malaLogKV = [];
    App.S.malaLogSS = [];
    App.S.malaLogRam = [];
    // ── Fix: discard any incomplete in-progress mala at midnight ──
    // Partial beads (< full mala) must not bleed into the new day or
    // create a ghost mala entry. Completed mala data is already saved
    // in history[previousTk] and is completely untouched.
    App.S.ms = 0;
    App.malaWallStart = 0;
    App._currentMalaStartTs = null;
    App.currentMalaSeconds = 0;
    App.S.malaStartTk = "";
    App.S.malaStartMode = "";
    try {
      localStorage.removeItem("rjap_currentMalaStartTs");
      localStorage.setItem("rjap_malaWallStart", "0");
      localStorage.setItem("rjap_currentMalaSeconds", "0");
      localStorage.removeItem("rjap_malaStartTk");
    } catch(_) {}
    if (!App.S.history[App.S.tk]) App.S.history[App.S.tk] = 0;
    if (!App.S.h28[App.S.tk]) App.S.h28[App.S.tk] = 0;
    if (!App.S.timerHistory[App.S.tk]) App.S.timerHistory[App.S.tk] = 0;
    if (!App.S.timer28History[App.S.tk]) App.S.timer28History[App.S.tk] = 0;
    if (!App.S.historyRV) App.S.historyRV = {};
    if (!App.S.historyRV[App.S.tk]) App.S.historyRV[App.S.tk] = 0;
    if (!App.S.timerHistoryRV) App.S.timerHistoryRV = {};
    if (!App.S.timerHistoryRV[App.S.tk]) App.S.timerHistoryRV[App.S.tk] = 0;
    if (!App.S.historyHK) App.S.historyHK = {};
    if (!App.S.historyHK[App.S.tk]) App.S.historyHK[App.S.tk] = 0;
    if (!App.S.timerHistoryHK) App.S.timerHistoryHK = {};
    if (!App.S.timerHistoryHK[App.S.tk]) App.S.timerHistoryHK[App.S.tk] = 0;
    App.lmc = 0;
    App.lmcRV = 0;
    App.lmcHK = 0;
    App.save();
    fbDebouncedPush();
    // Push leaderboard immediately on date rollover so "Today" tab resets to 0 for all viewers
    if (typeof pushLeaderboard === 'function') {
      pushLeaderboard().then(() => {
        localStorage.setItem('rjap_lastLbPushDate', newTk);
      }).catch(() => {});
    }
    App.ua();
    uStats();
  }
}, 60000);

// ── Get canonical app URL (strips index.html, query, hash) ──
// Canonical public URLs for sharing. window.location.href is NOT safe to
// use for this — inside the installed Android app it points at the
// WebView's internal address (localhost/asset path), not a real public
// link. Always use these fixed URLs instead, in both native and web
// contexts, so Share always produces something the recipient can open.
const RJAP_PWA_URL = "https://radharadharadha.vercel.app/";
// Direct download link for the installable Android APK — a Google Drive
// folder that gets manually updated with the latest built app-*.apk each
// time a new version is released. Update this constant if the Drive folder
// URL itself ever changes (e.g. moved to a different Drive account/folder).
const RJAP_APK_URL = "https://drive.google.com/drive/folders/1f5LsU7nL0KycW1_KkTu6lWivrEnd8l48";

// Fallback direct-download link for the "Manual APK Link" card, used
// whenever no developer-set link has been loaded from Firestore yet —
// most notably for signed-out visitors, since Firestore reads require
// auth and we can't fetch config/manualApkLink for them. This keeps the
// card always tappable instead of dead-ending on "sign in first". Once
// the developer saves a link (see saveManualApkLink below), that link
// takes over as soon as it's loaded (i.e. once the user signs in).
const RJAP_APK_FALLBACK_URL = "https://drive.google.com/file/d/1FfS0LR_a9NiKErFtwuYJlbpkgTSc2D63/view?usp=drivesdk";

function _getAppUrl() {
  return RJAP_PWA_URL;
}

// Native Android (Capacitor WebView) does not implement the Web Share API —
// navigator.share is simply undefined there, so these used to always fall
// straight through to "copy the link" with no share sheet at all. Try the
// Capacitor Share plugin first (real Android share sheet: WhatsApp,
// Messenger, Telegram, etc.), then navigator.share for the PWA/browser,
// then copy as the final fallback.
async function _lcShareText(shareText) {
  if (_lcIsNative() && window.Capacitor.Plugins && window.Capacitor.Plugins.Share) {
    try {
      await window.Capacitor.Plugins.Share.share({ text: shareText });
      toast("Shared! \uD83D\uDE4F Jai Radhe!");
      return;
    } catch (err) {
      // User cancelled the share sheet — not a real error, do nothing.
      if (err && err.message && /cancel/i.test(err.message)) return;
      _copyAppUrl(shareText);
      return;
    }
  }
  if (navigator.share) {
    navigator
      .share({ text: shareText })
      .then(() => toast("Shared! \uD83D\uDE4F Jai Radhe!"))
      .catch((err) => {
        if (err.name !== "AbortError") _copyAppUrl(shareText);
      });
  } else {
    _copyAppUrl(shareText);
  }
}

// ── Share App (PWA link) ──
// ── Open an external link (community/social) in the system/in-app browser ──
async function openExternalLink(url) {
  try {
    if (
      window.Capacitor &&
      typeof window.Capacitor.isNativePlatform === "function" &&
      window.Capacitor.isNativePlatform() &&
      window.Capacitor.Plugins &&
      window.Capacitor.Plugins.Browser
    ) {
      await window.Capacitor.Plugins.Browser.open({ url });
      return;
    }
  } catch (_e) {}
  try { window.open(url, "_blank"); } catch (_e) {}
}

// ── First-tap tutorial hint ──────────────────────────────────────
// Shown once, inline above the tap zone, the first time the person
// ever taps the Jap counter. Same tutorial link as the Settings ›
// "App Tutorial Video" row. Never blocks counting; dismissible via
// either the bar itself (watch) or the ✕ (dismiss) — either one
// marks it seen for good.
const FIRST_TAP_HINT_SEEN_KEY = "firstTapTutorialSeen";
const APP_TUTORIAL_VIDEO_URL = "https://youtu.be/IsrueqcsHL4?si=Nqn9io_MJCsrNi4Z";

function _maybeShowFirstTapHint() {
  try {
    if (localStorage.getItem(FIRST_TAP_HINT_SEEN_KEY)) return;
  } catch (_e) {}
  const el = document.getElementById("firstTapTutorialHint");
  if (el) el.style.display = "flex";
}

function _markFirstTapHintSeen() {
  const el = document.getElementById("firstTapTutorialHint");
  if (el) el.style.display = "none";
  try { localStorage.setItem(FIRST_TAP_HINT_SEEN_KEY, "1"); } catch (_e) {}
}

function _firstTapHintWatch() {
  _markFirstTapHintSeen();
  openExternalLink(APP_TUTORIAL_VIDEO_URL);
}

function _firstTapHintDismiss() {
  _markFirstTapHintSeen();
}

function shareApp() {
  const url = _getAppUrl();
  const shareText =
    "Radha Vallabh Sri Harivangsa \uD83D\uDE4F\n\n" +
    "Boost your Naam Jap experience with this little app —\n" +
    "track Brahmacharya daily Jap & lots of statistics \u2728 \uD83E\uDEB7\n\n" +
    "\uD83D\uDC49 " +
    url;
  _lcShareText(shareText);
}

// ── Manual APK link (developer-provided, stored in Firestore under
// config/manualApkLink so a new link reaches every user immediately with
// no code deploy needed). Regular users get a plain tap-to-download row;
// isDeveloper() sees an editable input + Save button instead. ──
let _manualApkLinkCache = null; // last-known link string, or null if none set yet

async function _loadManualApkLink() {
  // No signed-in user yet — Firestore rules require auth, so fall back to
  // whatever we last cached locally (works offline / before sign-in resolves).
  if (!fbUser || !fbDb) {
    try {
      _manualApkLinkCache = localStorage.getItem("manualApkLinkCache") || null;
    } catch (_e) {}
    _renderManualApkCard();
    return;
  }
  try {
    const snap = await fbDb.collection("config").doc("manualApkLink").get();
    _manualApkLinkCache = (snap.exists && snap.data().url) || null;
    try {
      if (_manualApkLinkCache) localStorage.setItem("manualApkLinkCache", _manualApkLinkCache);
    } catch (_e) {}
  } catch (e) {
    console.warn("Could not load manual APK link (using local cache):", e);
    try {
      _manualApkLinkCache = _manualApkLinkCache || localStorage.getItem("manualApkLinkCache") || null;
    } catch (_e) {}
  }
  _renderManualApkCard();
}

// Effective link the card should download from: the developer's
// Firestore-saved link if one has been loaded, otherwise the hardcoded
// fallback — so there is always something to tap, signed in or not.
function _effectiveManualApkUrl() {
  return _manualApkLinkCache || RJAP_APK_FALLBACK_URL;
}

function _renderManualApkCard() {
  const titleEl = document.getElementById("manualApkTitle");
  const statusEl = document.getElementById("manualApkStatus");
  const rowEl = document.getElementById("manualApkRow");
  const editWrap = document.getElementById("manualApkEditWrap");
  const editIconEl = document.getElementById("manualApkEditIcon");
  const chevronEl = document.getElementById("manualApkChevron");
  if (!titleEl || !statusEl) return;

  // Size / benefit heads-up (everyone sees it; follows the app language).
  const noteEl = document.getElementById("manualApkNote");
  if (noteEl) {
    const _l = (App && App.S && App.S.stotramLang) || "bn";
    noteEl.textContent = _l === "hi"
      ? "\uD83D\uDCE6 \u0932\u0917\u092D\u0917 500 MB \u2014 \u0921\u093E\u0909\u0928\u0932\u094B\u0921 \u092E\u0947\u0902 \u0915\u0941\u091B \u0938\u092E\u092F \u0932\u0917 \u0938\u0915\u0924\u093E \u0939\u0948\u0964 \u0930\u093F\u092E\u093E\u0907\u0902\u0921\u0930 \u0914\u0930 \u0911\u092B\u093C\u0932\u093E\u0907\u0928 \u0909\u092A\u092F\u094B\u0917 \u0915\u0947 \u0932\u093F\u090F \u092F\u0939 \u090F\u092A \u092C\u0939\u0941\u0924 \u0938\u0941\u0935\u093F\u0927\u093E\u091C\u0928\u0915 \u0939\u0948\u0964"
      : "\uD83D\uDCE6 \u09AA\u09CD\u09B0\u09BE\u09DF \u09EB\u09E6\u09E6 MB \u2014 \u09A1\u09BE\u0989\u09A8\u09B2\u09CB\u09A1 \u09B9\u09A4\u09C7 \u0995\u09BF\u099B\u09C1\u099F\u09BE \u09B8\u09AE\u09DF \u09B2\u09BE\u0997\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u0964 \u09B0\u09BF\u09AE\u09BE\u0987\u09A8\u09CD\u09A1\u09BE\u09B0 \u0993 \u0985\u09AB\u09B2\u09BE\u0987\u09A8\u09C7 \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u098F\u099F\u09BF \u0996\u09C1\u09AC\u0987 \u09B8\u09C1\u09AC\u09BF\u09A7\u09BE\u099C\u09A8\u0995\u0964";
  }

  const effectiveUrl = _effectiveManualApkUrl();

  if (isDeveloper()) {
    // The row itself now always downloads, same as for regular users —
    // the pencil icon is the only thing that opens the paste-a-link
    // editor, so developers don't lose the ability to just grab the APK.
    const isOpen = !!window._manualApkEditOpen;
    titleEl.textContent = "Download APK file";
    statusEl.textContent = _manualApkLinkCache
      ? "Tap to download. Tap ✏️ to replace the link."
      : "Tap to download (default link). Tap ✏️ to set your own.";
    if (editIconEl) editIconEl.style.display = "flex";
    if (editWrap) editWrap.style.display = isOpen ? "block" : "none";
    if (chevronEl) chevronEl.style.transform = isOpen ? "rotate(90deg)" : "rotate(0deg)";
    const input = document.getElementById("manualApkInput");
    if (input && !input.value) input.value = _manualApkLinkCache || "";
    if (rowEl) rowEl.onclick = () => openExternalLink(effectiveUrl);
  } else {
    if (editIconEl) editIconEl.style.display = "none";
    if (editWrap) editWrap.style.display = "none";
    titleEl.textContent = "Download APK file";
    if (!fbUser) {
      // Not signed in — Firestore reads require auth, so we can't fetch
      // the developer's link yet. Give the fallback link instead of
      // dead-ending on "sign in first"; signing in will swap in the
      // developer's own link automatically once it loads.
      statusEl.textContent = "Tap to download the APK";
    } else if (_manualApkLinkCache) {
      statusEl.textContent = "Tap to download the APK from a developer-shared link";
    } else {
      statusEl.textContent = "Tap to download the APK";
    }
    if (rowEl) rowEl.onclick = () => openExternalLink(effectiveUrl);
  }
}

// Developer-only: toggles the paste-a-link editor open/closed. Wired to
// the pencil icon in index.html (manualApkEditIcon), kept separate from
// the row's own onclick so tapping the row always downloads instead.
function toggleManualApkEdit() {
  window._manualApkEditOpen = !window._manualApkEditOpen;
  _renderManualApkCard();
}

async function saveManualApkLink() {
  if (!isDeveloper()) return;
  const input = document.getElementById("manualApkInput");
  const url = input && input.value.trim();
  if (!url) {
    toast("Paste a link first.");
    return;
  }
  try {
    await fbDb.collection("config").doc("manualApkLink").set(
      { url, updatedAt: firebase.firestore.FieldValue.serverTimestamp(), updatedBy: fbUser.email },
      { merge: true }
    );
    _manualApkLinkCache = url;
    try {
      localStorage.setItem("manualApkLinkCache", url);
    } catch (_e) {}
    toast("✅ Saved! All users will now see this link.");
    _renderManualApkCard();
  } catch (e) {
    console.error("Failed to save manual APK link:", e);
    toast("Could not save — check connection.");
  }
}

