window._msLang = "bn";
// N&M language is now a persisted per-section override (see secLang()).
function setMsLang(lang) { setSecLang("nm", lang); }
function _msApplyLang(explicit) {
  const lang = secLang("nm");
  window._msLang = lang;
  secLangSyncButtons();
  renderMilestonesTab();
  // Auto-sync Mahamantra language toggle only when the user explicitly
  // picks a language in N&M (not on Settings-language / reset changes).
  if (!explicit) return;
  if (lang === "bn" && App && App.S && App.S.hkLang !== "bn") {
    App.S.hkLang = "bn";
    const tgH = document.getElementById("tgHkLang");
    if (tgH) tgH.classList.add("on");
    const lblH = document.getElementById("hkLangLabel");
    if (lblH) lblH.textContent = "Bangla";
    const hkEl = document.getElementById("hkPersist");
    if (hkEl && hkEl.classList.contains("hk-visible")) {
      hkEl.innerHTML = HK_TEXT_BN.split("\n")
        .map((l) => "<div>" + l + "</div>")
        .join("");
    }
    if (App.S.japMode === "hk") switchJapMode("hk");
    App.save();
  } else if (lang === "hi" && App && App.S && App.S.hkLang !== "hi") {
    App.S.hkLang = "hi";
    const tgH = document.getElementById("tgHkLang");
    if (tgH) tgH.classList.remove("on");
    const lblH = document.getElementById("hkLangLabel");
    if (lblH) lblH.textContent = "Hindi";
    const hkEl = document.getElementById("hkPersist");
    if (hkEl && hkEl.classList.contains("hk-visible")) {
      hkEl.innerHTML = HK_TEXT.split("\n")
        .map((l) => "<div>" + l + "</div>")
        .join("");
    }
    if (App.S.japMode === "hk") switchJapMode("hk");
    App.save();
  }
}

// ═════════════════════════════════════════════════════════════════
// PER-SECTION LANGUAGE + FIRST-LOGIN ONBOARDING
// App.S.stotramLang  = global language (Settings pills / first-login choice)
// App.S.secLang      = { sv, bc, nm } overrides ("hi"|"bn"); absent = follow global
//   sv = Stotram & Videos, bc = Brahmacharya & Calendar,
//   nm = Naam Jap Mahima & Milestones ("hi" shows Hinglish there).
// Jap text language stays separate (App.S.hkLang / App.S.naamLang).
// ═════════════════════════════════════════════════════════════════
const GPS_HELP_TEXT = "Kindly turn on the GPS location to get Brahma Muhurta, Sunrise, Sandhyakal, Sunset and other time related data according to your location. 📍";

function secLang(k) {
  const o = App && App.S && App.S.secLang && App.S.secLang[k];
  if (o === "hi" || o === "bn") return o;
  return (App && App.S && App.S.stotramLang) === "hi" ? "hi" : "bn";
}
function secLangPersistLocal() {
  try {
    localStorage.setItem("rjap_lang_pref", (App.S && App.S.stotramLang) === "hi" ? "hi" : "bn");
    localStorage.setItem("rjap_sec_lang", JSON.stringify((App.S && App.S.secLang) || {}));
  } catch (_e) {}
}
// lang: "hi" | "bn" sets the override; null/"" clears it (follow Settings)
function setSecLang(k, lang) {
  if (!App || !App.S) return;
  if (!App.S.secLang || typeof App.S.secLang !== "object") App.S.secLang = {};
  const explicit = lang === "hi" || lang === "bn";
  if (explicit) App.S.secLang[k] = lang; else delete App.S.secLang[k];
  App.save();
  secLangPersistLocal();
  secLangSyncButtons();
  if (k === "sv") {
    try { renderSt(); } catch (_e) {}
    try { _lcRefreshOpenLyrics(); } catch (_e) {}
  } else if (k === "bc") {
    try { syncRkkOccLangButtons(); } catch (_e) {}
    try { renderRkkOccList(); } catch (_e) {}
    try { renderCal(); } catch (_e) {}
  } else if (k === "nm") {
    try { _msApplyLang(explicit); } catch (_e) {}
  }
}
function secLangSyncButtons() {
  if (!App || !App.S) return;
  document.querySelectorAll(".sec-lang-bar[data-sec]").forEach((bar) => {
    const k = bar.getAttribute("data-sec");
    const cur = secLang(k);
    const ovr = !!(App.S.secLang && App.S.secLang[k]);
    bar.querySelectorAll("button[data-l]").forEach((b) => {
      const l = b.getAttribute("data-l");
      if (l === "") b.style.display = ovr ? "" : "none";
      else b.classList.toggle("active", l === cur);
    });
  });
  const nmHi = document.getElementById("msLangHi"), nmBn = document.getElementById("msLangBn");
  if (nmHi) nmHi.classList.toggle("active", secLang("nm") === "hi");
  if (nmBn) nmBn.classList.toggle("active", secLang("nm") === "bn");
}
// Settings language changed: sections WITHOUT an override follow it.
function secLangOnGlobalChange() {
  secLangSyncButtons();
  try { _renderManualApkCard(); } catch (_e) {}
  try { sync28ScriptBtn(); u28(); } catch (_e) {}
  if (!(App.S.secLang && App.S.secLang.nm)) {
    try { _msApplyLang(false); } catch (_e) {}
  }
}

// ── First-launch language gate: blocks the app on a fresh install until the
// user picks Hindi or Bangla. Skipped for existing users and for anyone who
// has already chosen. Sign-in is NOT required for this step. ──
function _lcIsExistingInstall() {
  try {
    if (App.S && App.S.langOnboarded) return true;
    if (localStorage.getItem("rjap_lang_asked") === "1" || localStorage.getItem("rjap_lang_pref")) return true;
    const S = App.S || {};
    if ((S.lt || 0) > 0 || (S.dt || 0) > 0) return true;
    if (S.history && Object.keys(S.history).length) return true;
    if (S.historyHK && Object.keys(S.historyHK).length) return true;
    const keys = ["rjap_push_asked", "rjap_gps_enabled", "rjap_gps_asked", "rjap_reminder_time", "rjap_push_enabled"];
    for (const k of keys) if (localStorage.getItem(k)) return true;
  } catch (_e) {}
  return false;
}
async function lcLangGate() {
  if (_lcIsExistingInstall()) return;
  const pick = await new Promise((resolve) => {
    const ov = document.createElement("div");
    ov.id = "lcLangGate";
    ov.style.cssText = "position:fixed;inset:0;z-index:100001;background:linear-gradient(160deg,#0d1535,#050818);display:flex;align-items:center;justify-content:center;padding:26px;";
    ov.innerHTML = '<div style="max-width:380px;width:100%;text-align:center;">' +
      '<div style="font-size:42px;line-height:1;margin-bottom:12px;">🙏</div>' +
      '<div style="font-size:19px;font-weight:700;color:#FFD700;margin-bottom:6px;">भाषा चुनें</div>' +
      '<div style="font-size:19px;font-weight:700;color:#FFD700;margin-bottom:14px;">ভাষা নির্বাচন করুন</div>' +
      '<div style="font-size:12px;color:rgba(255,255,255,.65);line-height:1.5;margin-bottom:22px;">Choose your language to continue.<br>You can change it later in Settings.</div>' +
      '<div style="display:flex;flex-direction:column;gap:12px;">' +
      '<button type="button" data-l="hi" style="padding:15px;border-radius:14px;border:1px solid rgba(255,215,0,.6);background:linear-gradient(135deg,#FFD700,#E5A800);color:#201400;font-size:17px;font-weight:700;cursor:pointer;">हिंदी</button>' +
      '<button type="button" data-l="bn" style="padding:15px;border-radius:14px;border:1px solid rgba(255,215,0,.6);background:linear-gradient(135deg,#FFD700,#E5A800);color:#201400;font-size:17px;font-weight:700;cursor:pointer;">বাংলা</button>' +
      '</div></div>';
    ov.querySelectorAll("button[data-l]").forEach((b) => {
      b.onclick = () => { ov.remove(); resolve(b.getAttribute("data-l")); };
    });
    document.body.appendChild(ov);
  });
  // Set state directly (the UI has not been initialised yet); init picks it up.
  try { localStorage.setItem("rjap_lang_asked", "1"); } catch (_e) {}
  App.S.stotramLang = pick;
  App.S.langOnboarded = true;
  // Hindi = Sanskrit script for jap text; Bangla = Bangla, until the user
  // picks a jap text language themselves.
  if (pick === "bn" && !App.S.japLangChosen) {
    App.S.hkLang = "bn";
    App.S.naamLang = "bn";
    try { localStorage.setItem("rjap_jap_default", "bn"); } catch (_e) {}
  } else {
    try { localStorage.removeItem("rjap_jap_default"); } catch (_e) {}
  }
  secLangPersistLocal();
  try { App.save(); } catch (_e) {}
  try { localStorage.removeItem("rjap_n28_script"); } catch (_e) {}
  _n28ScriptHindi = null;
  try { sync28ScriptBtn(); u28(); } catch (_e) {}
}

// ── First-login onboarding modals ──
function _lcOnbModal(o) {
  return new Promise((resolve) => {
    const ov = document.createElement("div");
    ov.style.cssText = "position:fixed;inset:0;z-index:100000;background:rgba(3,6,20,.82);display:flex;align-items:center;justify-content:center;padding:22px;";
    const box = document.createElement("div");
    box.style.cssText = "max-width:380px;width:100%;background:linear-gradient(160deg,#0d1535,#080c23);border:1px solid rgba(255,215,0,.35);border-radius:18px;padding:22px 20px;text-align:center;box-shadow:0 10px 40px rgba(0,0,0,.6);";
    box.innerHTML = '<div style="font-size:34px;line-height:1;margin-bottom:10px;">' + o.icon + '</div>' +
      '<div style="font-size:16px;font-weight:700;color:#FFD700;margin-bottom:10px;">' + o.title + '</div>' +
      '<div style="font-size:13px;color:rgba(255,255,255,.82);line-height:1.55;margin-bottom:16px;">' + o.body + '</div>';
    const row = document.createElement("div");
    row.style.cssText = "display:flex;flex-direction:column;gap:9px;";
    o.buttons.forEach((b) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.textContent = b.label;
      btn.style.cssText = b.primary
        ? "padding:12px;border-radius:12px;border:1px solid rgba(255,215,0,.6);background:linear-gradient(135deg,#FFD700,#E5A800);color:#201400;font-size:14px;font-weight:700;cursor:pointer;"
        : "padding:10px;border-radius:12px;border:1px solid rgba(255,255,255,.2);background:rgba(255,255,255,.06);color:rgba(255,255,255,.75);font-size:12px;cursor:pointer;";
      btn.onclick = () => { ov.remove(); resolve(b.value); };
      row.appendChild(btn);
    });
    box.appendChild(row);
    ov.appendChild(box);
    document.body.appendChild(ov);
  });
}

// Popup language → jap text language (Hindi = Sanskrit script, Bangla = Bangla),
// only while the user has not chosen a jap text language themselves AND both
// jap languages are still at their defaults (so an existing choice is never overwritten).
function lcApplyJapLangDefaults(pick) {
  if (!App || !App.S || App.S.japLangChosen) return;
  if ((App.S.hkLang || "hi") !== "hi" || (App.S.naamLang || "sa") !== "sa") return;
  if (pick !== "bn") return;  // Hindi/Sanskrit are already the defaults
  try { setHKLangDirect("bn"); } catch (_e) {}
  try { setNaamLangDirect("bn"); } catch (_e) {}
  App.S.japLangChosen = false;  // this was automatic, not the user's own jap choice
  App.save();
}

async function lcOnbEnableGps() {
  try {
    const pos = await lcGetPosition({ timeout: 15000, maximumAge: 0 });
    const lat = pos.coords.latitude, lng = pos.coords.longitude;
    window._appLat = lat; window._appLng = lng;
    if (App.S) { App.S.lastLat = lat; App.S.lastLng = lng; App.save(); }
    try {
      localStorage.setItem("rjap_gps_enabled", "1");
      localStorage.setItem("rjap_lastLat", String(lat));
      localStorage.setItem("rjap_lastLng", String(lng));
    } catch (_e) {}
    try { updateSunInfo(lat, lng); } catch (_e) {}
    const tg = document.getElementById("tgGpsLocation");
    if (tg) tg.classList.add("on");
    const st = document.getElementById("gpsLocationStatus");
    if (st) st.textContent = "✅ Location detected · " + lat.toFixed(3) + ", " + lng.toFixed(3);
    toast("📍 GPS location saved! Brahma Muhurta times updated 🙏");
    try { renderCal(); } catch (_e) {}
    return true;
  } catch (err) {
    try { toast(_lcGpsErrorMessage(err)); } catch (_e) {}
    return false;
  }
}

let _lcOnbRunning = false;
async function lcOnboardingRun(user) {
  if (_lcOnbRunning) return;
  _lcOnbRunning = true;
  try {
    // 1) Notification — the system prompt was already triggered by the
    //    sign-in handler; wait for it to be answered before the next step.
    if (window._lcPushAskPromise) { try { await window._lcPushAskPromise; } catch (_e) {} window._lcPushAskPromise = null; }
    // Let cloud data for this user finish loading so saved choices are known.
    await new Promise((r) => setTimeout(r, 1800));
    if (!user || (App._uid && App._uid !== user.uid)) return;

    // 2) GPS location
    let gpsOn = false, gpsAsked = false;
    try { gpsOn = localStorage.getItem("rjap_gps_enabled") === "1"; } catch (_e) {}
    try { gpsAsked = localStorage.getItem("rjap_gps_asked") === "1"; } catch (_e) {}
    if (!gpsOn && !gpsAsked && !(App.S && App.S.lastLat != null)) {
      try { localStorage.setItem("rjap_gps_asked", "1"); } catch (_e) {}
      const go = await _lcOnbModal({
        icon: "📍",
        title: "Turn on GPS location",
        body: GPS_HELP_TEXT,
        buttons: [
          { label: "📍 Turn on GPS", primary: true, value: true },
          { label: "Not now", value: false },
        ],
      });
      if (go) await lcOnbEnableGps();
    }

    // 3) Language was already chosen on the first-launch screen. A brand-new
    //    account (no saved language yet) adopts that choice; an account that
    //    already has saved language settings keeps its own.
    let pref = ""; try { pref = localStorage.getItem("rjap_lang_pref") || ""; } catch (_e) {}
    if (App.S && !App.S.langOnboarded && (pref === "hi" || pref === "bn")) {
      App.S.langOnboarded = true;
      if (App.S.stotramLang !== pref) setStotramLang(pref); else { App.save(); secLangOnGlobalChange(); }
      lcApplyJapLangDefaults(pref);
    }
  } catch (e) {
    console.error("onboarding failed:", e);
  } finally {
    _lcOnbRunning = false;
  }
}

// ── Stotram list language toggle (Hindi/Devanagari vs Bangla) ──
// Controls: (1) which script the Settings-header toggle shows as active,
// (2) which STLIST name/sub fields render in the Stotram folder cards,
// (3) which title shows atop the lyrics-reader modal.
// Falls back to the Bangla fields whenever a Hindi field is missing on a
// given STLIST/customSt entry, so nothing goes blank mid-rollout.
function setStotramLang(lang) {
  if (!App || !App.S || App.S.stotramLang === lang) return;
  App.S.stotramLang = lang;
  const btnHi = document.getElementById("setLangHi");
  const btnBn = document.getElementById("setLangBn");
  if (btnHi) btnHi.classList.toggle("active", lang === "hi");
  if (btnBn) btnBn.classList.toggle("active", lang === "bn");
  App.save();
  try { secLangPersistLocal(); secLangOnGlobalChange(); } catch (_e) {}
  try { renderSt(); } catch (_e) {}
  try { if (typeof syncRkkOccLangButtons === "function") syncRkkOccLangButtons(); } catch (_e) {}
  try { if (typeof renderRkkOccList === "function") renderRkkOccList(); } catch (_e) {}
  try { if (typeof renderCal === "function") renderCal(); } catch (_e) {}
  _lcRefreshOpenLyrics();
}
// If the lyrics-reader modal is currently open, refresh it for the S&V language.
function _lcRefreshOpenLyrics() {
  const lang = secLang("sv");
  try {
    const lmo = document.getElementById("lmo");
    const lmTitle = document.getElementById("lmTitle");
    if (lmo && lmo.classList.contains("show") && lmTitle && _currentStotramId) {
      if (_currentStotramId === "hcj" && lang === "hi" && !_hcjHindiLyrics) {
        loadHcjHindiLyrics()
          .then(() => showLyrics("hcj"))
          .catch(() => toast("हिंदी चौरासी पाठ लोड नहीं हो पाया 🙏"));
        return;
      }
      if (_currentStotramId === "rsn" && lang === "hi" && !_rsnHindiLyrics) {
        loadRsnHindiLyrics()
          .then(() => showLyrics("rsn"))
          .catch(() => toast("हिंदी राधा सुधा निधि पाठ लोड नहीं हो पाया 🙏"));
        return;
      }
      if (_currentStotramId === "hcj") {
        showLyrics("hcj");
        return;
      }
      if (_currentStotramId === "rsn") {
        showLyrics("rsn");
        return;
      }
      if (_isLiveStId(_currentStotramId) || (typeof LYRICS_HI !== "undefined" && LYRICS_HI[_currentStotramId])) {
        showLyrics(_currentStotramId);
        return;
      }
      const allSt = [...STLIST, ...(App.S.customSt || [])];
      const nm = allSt.find((x) => x.id === _currentStotramId);
      if (nm) {
        lmTitle.textContent = (lang === "hi" && nm.nameHi) ? nm.nameHi : nm.name;
      }
    }
  } catch (_e) {}
}

// Hindi श्री हित चौरासी is kept in a small companion text file so the
// existing Bangla stotram bundle does not become unnecessarily larger.
// The source contains one blank-line-separated block per पद (all 84).
// Hindi text is bundled in stotrams.js (LYRICS_HI.hcj, 84 pads), so no separate .txt file is fetched any more.
let _hcjHindiLyrics = (typeof LYRICS_HI !== "undefined" && LYRICS_HI.hcj) || "";
let _hcjHindiLoadPromise = null;
const HCJ_HINDI_DATA_URLS = [
  "./Hit_Caturashi_Ji_clean_lyrics.txt",
  "../Hit_Caturashi_Ji_clean_lyrics.txt",
  "./attached_assets/Hit_Caturashi_Ji_clean_lyrics.txt",
];

function _cleanHcjHindiSource(source) {
  const lines = source
    .replace(/\r/g, "")
    .split("\n");
  const colophonIndex = lines.findIndex((line) =>
    line.trim().startsWith("॥ जय जय श्रीगोस्वामी")
  );
  return lines
    .slice(0, colophonIndex === -1 ? lines.length : colophonIndex)
    .filter((line) => {
      const trimmed = line.trim();
      return (
        trimmed !== "श्री हित चतुरासी जी" &&
        !/^पद\s+\d+[-–]\d+$/.test(trimmed)
      );
    })
    .join("\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function loadHcjHindiLyrics() {
  if (_hcjHindiLyrics) return Promise.resolve(_hcjHindiLyrics);
  if (_hcjHindiLoadPromise) return _hcjHindiLoadPromise;

  _hcjHindiLoadPromise = HCJ_HINDI_DATA_URLS.reduce(
    (promise, url) =>
      promise.catch(() =>
        fetch(url).then((response) => {
          if (!response.ok) throw new Error("Hindi HCJ data request failed");
          return response.text();
        })
      ),
    Promise.reject(new Error("Hindi HCJ data not attempted"))
  )
    .then((source) => {
      const lyrics = _cleanHcjHindiSource(source);
      const verseCount = lyrics
        .split(/\n{2,}/)
        .filter((verse) => verse.trim().length > 0).length;
      if (verseCount !== 84) {
        throw new Error("Hindi HCJ contains " + verseCount + " verses");
      }
      _hcjHindiLyrics = lyrics;
      return lyrics;
    })
    .catch((error) => {
      _hcjHindiLoadPromise = null;
      throw error;
    });

  return _hcjHindiLoadPromise;
}

// Hindi श्री राधा सुधा निधि is kept in its own companion file because it
// includes the complete Devanagari text plus the Hindi व्याख्या for all
// 270 shlokas. It is loaded only when the user selects Hindi and opens it.
// Hindi text is bundled in stotrams.js (LYRICS_HI.rsn, 271 blocks), so no separate .txt file is fetched any more.
let _rsnHindiLyrics = (typeof LYRICS_HI !== "undefined" && LYRICS_HI.rsn) || "";
let _rsnHindiLoadPromise = null;
const RSN_HINDI_DATA_URLS = [
  "./Radha_Sudha_Nidhi_Hindi.txt",
  "../Radha_Sudha_Nidhi_Hindi.txt",
  "./attached_assets/Radha_Sudha_Nidhi_Hindi.txt",
];

function _cleanRsnHindiSource(source) {
  return source
    .replace(/\r/g, "")
    .split("\n")
    .filter((line) => line.trim() !== "श्री राधा सुधा निधि")
    .join("\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function loadRsnHindiLyrics() {
  if (_rsnHindiLyrics) return Promise.resolve(_rsnHindiLyrics);
  if (_rsnHindiLoadPromise) return _rsnHindiLoadPromise;

  _rsnHindiLoadPromise = RSN_HINDI_DATA_URLS.reduce(
    (promise, url) =>
      promise.catch(() =>
        fetch(url).then((response) => {
          if (!response.ok) throw new Error("Hindi RSN data request failed");
          return response.text();
        })
      ),
    Promise.reject(new Error("Hindi RSN data not attempted"))
  )
    .then((source) => {
      const lyrics = _cleanRsnHindiSource(source);
      const verseCount = lyrics
        .split(/\n{2,}/)
        .filter((verse) => verse.trim().length > 0).length;
      if (verseCount !== 271) {
        throw new Error("Hindi RSN contains " + verseCount + " blocks");
      }
      _rsnHindiLyrics = lyrics;
      return lyrics;
    })
    .catch((error) => {
      _rsnHindiLoadPromise = null;
      throw error;
    });

  return _rsnHindiLoadPromise;
}

// Small helper: pick the language-appropriate name/sub for a STLIST/customSt
