            syncBaselineTimerRV: {},
            historyHK: {},
            timerHistoryHK: {},
            dtHK: 0,
            malaLogHK: [],
            syncBaselineHK: {},
            syncBaselineTimerHK: {},
            nameJapDeductHK: 0,
