  if (d.dtKV !== undefined) App.S.dtKV = d.dtKV;
  if (d.ltKV !== undefined) App.S.ltKV = d.ltKV;
  if (d.nameJapDeductKV !== undefined)
    App.S.nameJapDeductKV = d.nameJapDeductKV;
  // Kaam Vijay fields
