// ─────────────────────────────────────────────────────────
// FAVOURITE VIDEOS (4th-level folder inside Stotram section)
// Three sources:
//  - GitHub-hosted videos (Motivation / Naam Jap Mahima / Law of Karma):
//    dev uploads an .mp4 straight into the matching /videos/<slug>/ repo
//    folder — that's the ONLY step. A GitHub Action
//    (.github/workflows/video-manifest.yml) watches that folder and
//    auto-regenerates videos/manifest.json with whatever's actually
//    there; the app just fetches that one small JSON file (a plain
//    static file, not a live GitHub API directory listing, so no
//    rate limit) and lists whatever it says. The video itself still
//    streams from raw.githubusercontent.com only when a user taps it,
//    and is never bundled into the APK/PWA build (setup-www.sh's
//    rsync into www/ never touches /videos/).
//  - Links (YouTube / Instagram / Telegram): developer-only, added via
//    an in-app form, stored in Firestore /config/favouriteVideoLinks
//    (reuses the existing "config" collection — read: any signed-in
//    user, write: isDeveloper() only — see firestore.rules, no rule
//    change needed).
// ─────────────────────────────────────────────────────────
const FAVVID_GH_OWNER = 'drakthephenomenal';
const FAVVID_GH_REPO = 'Lalu-Chotopushu';
const FAVVID_GH_BRANCH = 'main';
const FAVVID_MANIFEST_URL = 'https://raw.githubusercontent.com/' + FAVVID_GH_OWNER + '/' + FAVVID_GH_REPO + '/' + FAVVID_GH_BRANCH + '/videos/manifest.json';

const VIDEO_SUBFOLDERS = [
  { key: 'motivation', title: 'Motivation',     icon: '🔥', type: 'github', path: 'videos/motivation' },
  { key: 'naamjap',    title: 'Naam Jap Mahima', icon: '📿', type: 'github', path: 'videos/naam-jap-mahima' },
  { key: 'karma',      title: 'Law of Karma',    icon: '⚖️', type: 'github', path: 'videos/law-of-karma' },
  { key: 'links',      title: 'Random Links',     icon: '🔗', type: 'links' },
];

// "Why-Karma-Never-Forgets.mp4" -> "Why Karma Never Forgets"
function favvidTitleFromFilename(name) {
  return name.replace(/\.[a-zA-Z0-9]+$/, '').replace(/[-_]+/g, ' ').trim();
}

// Fetches videos/manifest.json once per 5 minutes (cached in between so
// re-opening a subfolder doesn't re-fetch every time). The manifest is
// keyed by the repo folder name (e.g. "motivation",
// "naam-jap-mahima") — see the workflow file for how it's built.
let _favvidManifestCache = null;
let _favvidManifestFetchedAt = 0;
async function fetchFavVideoManifest(force) {
  const fresh = _favvidManifestCache && (Date.now() - _favvidManifestFetchedAt) < 5 * 60 * 1000;
  if (fresh && !force) return _favvidManifestCache;
  try {
    const res = await fetch(FAVVID_MANIFEST_URL, { cache: 'no-store' });
    if (!res.ok) {
      if (res.status === 404) { _favvidManifestCache = {}; _favvidManifestFetchedAt = Date.now(); return {}; }
      throw new Error('manifest fetch error ' + res.status);
    }
    _favvidManifestCache = await res.json();
    _favvidManifestFetchedAt = Date.now();
    return _favvidManifestCache;
  } catch (e) {
    if (_favvidManifestCache) return _favvidManifestCache; // stale-but-usable on a transient network error
    throw e;
  }
}

// Builds the video list for one subfolder from the fetched manifest.
async function getFavVideoFiles(sub) {
  const folderSlug = sub.path.split('/').pop(); // "videos/naam-jap-mahima" -> "naam-jap-mahima"
  const manifest = await fetchFavVideoManifest();
  const names = manifest[folderSlug] || [];
  return names.map((name) => ({
    name: name,
    key: name,
    title: favvidTitleFromFilename(name),
    url: 'https://raw.githubusercontent.com/' + FAVVID_GH_OWNER + '/' + FAVVID_GH_REPO + '/' + FAVVID_GH_BRANCH + '/' + sub.path + '/' + encodeURIComponent(name),
  }));
}

// Firestore-backed link list (YouTube / Instagram / Telegram).
let _favvidLinksCache = null;
async function loadFavVideoLinks(force) {
  if (_favvidLinksCache && !force) return _favvidLinksCache;
  try {
    const snap = await fbDb.collection('config').doc('favouriteVideoLinks').get();
    const data = snap.exists ? snap.data() : {};
    _favvidLinksCache = Array.isArray(data.items) ? data.items : [];
  } catch (e) {
    _favvidLinksCache = _favvidLinksCache || [];
  }
  return _favvidLinksCache;
}
async function saveFavVideoLinks(items) {
  await fbDb.collection('config').doc('favouriteVideoLinks').set({ items: items, updatedAt: Date.now() });
  _favvidLinksCache = items;
}

// ── Link folders (developer-only) ──
// Links can optionally be grouped into folders the developer creates.
// A link with no folderId (or one whose folder was deleted) shows in
// the "orphan" section instead of inside any folder.
let _favvidLinkFoldersCache = null;
async function loadFavVideoLinkFolders(force) {
  if (_favvidLinkFoldersCache && !force) return _favvidLinkFoldersCache;
  try {
    const snap = await fbDb.collection('config').doc('favouriteVideoLinkFolders').get();
    const data = snap.exists ? snap.data() : {};
    _favvidLinkFoldersCache = Array.isArray(data.folders) ? data.folders : [];
  } catch (e) {
    _favvidLinkFoldersCache = _favvidLinkFoldersCache || [];
  }
  return _favvidLinkFoldersCache;
}
async function saveFavVideoLinkFolders(folders) {
  await fbDb.collection('config').doc('favouriteVideoLinkFolders').set({ folders: folders, updatedAt: Date.now() });
  _favvidLinkFoldersCache = folders;
}

// ── Manual ordering (developer-only) ──
// One Firestore doc holds the developer's chosen order for each
// subfolder — keyed by filename for GitHub videos, by link id for
// Links. Anything not yet in the order list keeps its natural order,
// appended after the explicitly-ordered items. Reuses the existing
// "config" collection (read: any signed-in user, write: isDeveloper()
// only) — no rules change needed.
let _favvidOrderCache = null;
async function loadFavVideoOrder(force) {
  if (_favvidOrderCache && !force) return _favvidOrderCache;
  try {
    const snap = await fbDb.collection('config').doc('favouriteVideoOrder').get();
    _favvidOrderCache = snap.exists ? (snap.data() || {}) : {};
  } catch (e) {
    _favvidOrderCache = _favvidOrderCache || {};
  }
  return _favvidOrderCache;
}
async function saveFavVideoOrderFor(bucketKey, orderArr) {
  const cur = Object.assign({}, await loadFavVideoOrder(true));
  cur[bucketKey] = orderArr;
  await fbDb.collection('config').doc('favouriteVideoOrder').set(cur);
  _favvidOrderCache = cur;
}
// Sorts `items` (each must have a `.key` string) by orderArr; anything
// missing from orderArr keeps its original relative order at the end.
function favvidApplyOrder(items, orderArr) {
  if (!orderArr || !orderArr.length) return items.slice();
  const pos = {};
  orderArr.forEach((k, i) => { pos[k] = i; });
  return items.slice().sort((a, b) => {
    const pa = pos.hasOwnProperty(a.key) ? pos[a.key] : Infinity;
    const pb = pos.hasOwnProperty(b.key) ? pos[b.key] : Infinity;
    if (pa !== pb) return pa - pb;
    return 0; // stable: keeps original relative order for ties
  });
}
// Swaps the item identified by `key` with its neighbor within the FULL
// (unfiltered) `items` array — looked up by key rather than a display
// position, so this stays correct even when the visible list is
// currently narrowed by a search filter. Persists the new order for
// bucketKey, then re-renders. Used by the developer-only ↑/↓ buttons.
async function favvidReorder(bucketKey, items, key, dir) {
  const i = items.findIndex((x) => x.key === key);
  if (i === -1) return;
  const j = i + dir;
  if (j < 0 || j >= items.length) return;
  const copy = items.slice();
  const tmp = copy[i];
  copy[i] = copy[j];
  copy[j] = tmp;
  await saveFavVideoOrderFor(bucketKey, copy.map((x) => x.key));
  renderSt();
}

// ── "New/unseen" tracking (per device, not synced) ──
// A video or link stays marked unseen — and shows a small badge — until
// the user actually opens it once on this device.
function favvidSeenSet() {
  try {
    return JSON.parse(localStorage.getItem('favVidSeen') || '{}');
  } catch (e) {
    return {};
  }
}
function favvidIsSeen(key) {
  return !!favvidSeenSet()[key];
}
function favvidMarkSeen(key) {
  try {
    const seen = favvidSeenSet();
    if (seen[key]) return;
    seen[key] = true;
    localStorage.setItem('favVidSeen', JSON.stringify(seen));
  } catch (e) { /* storage unavailable — badge just won't persist, harmless */ }
}

// ── Shared search-bar harness ──
// Renders a text input plus a cards container below it, and re-filters
// on every keystroke by matching each item's .title (case-insensitive,
// substring match). Only the cards container is rebuilt on input — the
// search input itself is never re-rendered, so it keeps focus and
// cursor position while typing. opts: { placeholder, allItems,
// renderCards(filteredItems, container) }.
function favvidSearchableSection(list, opts) {
  const searchWrap = document.createElement('div');
  searchWrap.innerHTML = '<input type="text" placeholder="' + escHtml(opts.placeholder) + '" style="width:100%;margin-bottom:10px;background:rgba(0,0,0,0.35);border:1px solid rgba(255,215,0,0.25);border-radius:10px;padding:9px 12px;color:var(--tl);font-size:14px;box-sizing:border-box;font-family:Inter,sans-serif">';
  list.appendChild(searchWrap);
  const input = searchWrap.querySelector('input');

  const cardsDiv = document.createElement('div');
  list.appendChild(cardsDiv);

  function renderFiltered() {
    const q = input.value.trim().toLowerCase();
    const filtered = q ? opts.allItems.filter((v) => v.title.toLowerCase().indexOf(q) !== -1) : opts.allItems;
    cardsDiv.innerHTML = '';
    if (!filtered.length) {
      const empty = document.createElement('div');
      empty.className = 'st-folder-empty';
      empty.textContent = q ? 'কিছু পাওয়া যায়নি' : 'শীঘ্রই আসছে 🙏';
      cardsDiv.appendChild(empty);
      return;
    }
    opts.renderCards(filtered, cardsDiv);
  }
  input.addEventListener('input', renderFiltered);
  renderFiltered();
}
function favvidDetectPlatform(url) {
  const u = (url || '').toLowerCase();
  if (u.indexOf('youtube.com') !== -1 || u.indexOf('youtu.be') !== -1) return 'youtube';
  if (u.indexOf('instagram.com') !== -1) return 'instagram';
  if (u.indexOf('t.me') !== -1 || u.indexOf('telegram.me') !== -1) return 'telegram';
  // Drive share links come in several shapes depending on how they were
  // copied: drive.google.com/file/d/..., drive.google.com/open?id=...,
  // drive.usercontent.google.com/download?id=..., and the older
  // docs.google.com/file/d/... form.
  if (u.indexOf('drive.google.com') !== -1 || u.indexOf('drive.usercontent.google.com') !== -1 || u.indexOf('docs.google.com/file') !== -1) return 'drive';
  if (u.indexOf('facebook.com') !== -1 || u.indexOf('fb.watch') !== -1) return 'facebook';
  return 'other';
}
function favvidYoutubeId(url) {
  const m = url.match(/(?:youtu\.be\/|v=|\/embed\/|\/shorts\/)([A-Za-z0-9_-]{6,})/);
  return m ? m[1] : null;
}
function favvidTelegramEmbed(url) {
  const m = url.match(/t\.me\/([^/?]+)\/(\d+)/);
  if (!m) return null;
  return 'https://t.me/' + m[1] + '/' + m[2] + '?embed=1';
}
// Google Drive: works only if the file's sharing is set to "Anyone with
// the link" — Drive's own /preview page shows a "request access" screen
// otherwise, which we can't detect from a cross-origin iframe.
// Drive links open externally (see the click handler below) rather than
// embedding inline — two attempts at inline playback (an iframe /preview,
// then a direct-content <video> URL) both proved unreliable, since Drive
// has no officially-supported anonymous video-streaming endpoint.
// Facebook and Drive links open externally (see click handlers below)
// rather than embedding inline — both platforms' inline-embed options
// proved unreliable in practice (Drive has no official anonymous
// streaming endpoint; Facebook's plugin only works for Page-published
// videos, not personal posts or Reels).

// Inline modal player. kind: 'file' (GitHub mp4, native <video>),
// 'youtube' (iframe embed), 'telegram' (official public-post iframe
// embed), 'instagram' (official embed.js widget with a fallback
// "open externally" link if it fails to render within a few seconds).
function openFavVideoPlayer(title, kind, urlOrId, originalUrl) {
  var old = document.getElementById('favVidOverlay');
  if (old) old.remove();
  var overlay = document.createElement('div');
  overlay.id = 'favVidOverlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.88);z-index:9999;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:14px;box-sizing:border-box';

  var mediaHtml = '';
  if (kind === 'file') {
    mediaHtml = '<video src="' + urlOrId + '" controls autoplay playsinline style="width:100%;max-width:640px;max-height:70vh;border-radius:10px;background:#000"></video>';
  } else if (kind === 'youtube') {
    mediaHtml = '<iframe src="https://www.youtube.com/embed/' + urlOrId + '?autoplay=1&playsinline=1" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen style="width:100%;max-width:640px;aspect-ratio:16/9;border:none;border-radius:10px"></iframe>';
  } else if (kind === 'telegram') {
    mediaHtml = '<iframe src="' + urlOrId + '" allow="autoplay" style="width:100%;max-width:420px;height:70vh;border:none;border-radius:10px;background:#000"></iframe>';
  } else if (kind === 'instagram') {
    mediaHtml =
      '<blockquote class="instagram-media" data-instgrm-permalink="' + urlOrId + '" data-instgrm-version="14" style="width:100%;max-width:420px;margin:0;border-radius:10px;overflow:hidden;background:#000"></blockquote>' +
      '<div id="favVidIgFallback" style="display:none;margin-top:10px;text-align:center">' +
        '<div style="color:rgba(255,215,0,0.7);font-size:13px;margin-bottom:8px">এই ভিডিওটি এখানে দেখানো যাচ্ছে না</div>' +
        '<a href="' + urlOrId + '" target="_blank" rel="noopener" style="display:inline-block;padding:10px 18px;border-radius:10px;background:rgba(255,215,0,0.12);border:1px solid rgba(255,215,0,0.35);color:#ffd700;text-decoration:none;font-family:Inter,sans-serif;font-size:13px">Instagram-এ খুলুন ↗</a>' +
      '</div>';
  }

  overlay.innerHTML =
    '<div style="width:100%;max-width:640px;display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">' +
      '<div style="color:#ffd700;font-family:\'Hind Siliguri\',serif;font-size:15px;font-weight:600;flex:1;margin-right:10px">' + escHtml(title) + '</div>' +
      '<button id="favVidCloseBtn" style="width:38px;height:38px;border-radius:10px;border:1px solid rgba(255,215,0,0.3);background:rgba(255,215,0,0.08);color:#ffd700;font-size:18px;cursor:pointer;flex-shrink:0">✕</button>' +
    '</div>' +
    mediaHtml;

  document.body.appendChild(overlay);
  overlay.querySelector('#favVidCloseBtn').addEventListener('click', function () { overlay.remove(); });
  overlay.addEventListener('click', function (e) { if (e.target === overlay) overlay.remove(); });

  if (kind === 'instagram') {
    var processIg = function () {
      if (window.instgrm && window.instgrm.Embeds) window.instgrm.Embeds.process();
    };
    if (window.instgrm) {
      processIg();
    } else if (!document.getElementById('favVidIgScript')) {
      var s = document.createElement('script');
      s.id = 'favVidIgScript';
      s.async = true;
      s.src = 'https://www.instagram.com/embed.js';
      s.onload = processIg;
      document.body.appendChild(s);
    }
    setTimeout(function () {
      var bq = overlay.querySelector('blockquote.instagram-media');
      var fb = document.getElementById('favVidIgFallback');
      if (bq && !bq.querySelector('iframe') && fb) fb.style.display = 'block';
    }, 4000);
  }
}

function renderFavVideoFolder(list) {
  const backRow = document.createElement('div');
  backRow.className = 'st-back-row';
  const subKey = window._stActiveVideoFolder || null;

  if (!subKey) {
    backRow.innerHTML =
      '<button class="st-back-btn">← ফোল্ডার তালিকা</button>' +
      '<span class="st-back-title">Favourite Videos</span>';
    backRow.querySelector('.st-back-btn').addEventListener('click', () => {
      window._stActiveFolder = null;
      window._stActiveVideoFolder = null;
      window._stActiveLinkFolder = null;
      renderSt();
    });
    list.appendChild(backRow);

    VIDEO_SUBFOLDERS.forEach((sub) => {
      const tile = document.createElement('div');
      tile.className = 'st-folder-tile';
      tile.innerHTML =
        '<span class="st-folder-tile-icon">' + sub.icon + '</span>' +
        '<span class="st-folder-tile-title">' + escHtml(sub.title) + '</span>' +
        '<span class="st-folder-tile-arrow">›</span>';
      tile.addEventListener('click', () => {
        window._stActiveVideoFolder = sub.key;
        window._stActiveLinkFolder = null;
        renderSt();
      });
      list.appendChild(tile);
    });
    return;
  }

  // Inside a specific folder (created within any of the 4 subfolders) —
  // it builds its own back row (needs the folder's name, which is only
  // known after an async fetch) rather than the generic one below.
  if (window._stActiveLinkFolder) {
    renderFavVideoLinksFolderView(list, window._stActiveLinkFolder, subKey);
    return;
  }

  const sub = VIDEO_SUBFOLDERS.find((s) => s.key === subKey);
  backRow.innerHTML =
    '<button class="st-back-btn">←</button>' +
    '<span class="st-back-title">' + escHtml(sub ? sub.title : '') + '</span>';
  backRow.querySelector('.st-back-btn').addEventListener('click', () => {
    window._stActiveVideoFolder = null;
    window._stActiveLinkFolder = null;
    renderSt();
  });
  list.appendChild(backRow);

  if (!sub) { window._stActiveVideoFolder = null; renderSt(); return; }

  if (sub.type === 'github') {
    renderGithubVideoList(list, sub);
  } else if (sub.type === 'links') {
    renderFavVideoLinksTop(list, sub.key);
  }
}

function favvidNewBadgeHtml(key) {
  return favvidIsSeen(key) ? '' : '<span class="favvid-new-badge" style="background:#ff4d4d;color:#fff;font-size:9px;font-weight:700;padding:2px 6px;border-radius:8px;margin-left:6px;letter-spacing:0.5px;flex-shrink:0">NEW</span>';
}
function favvidReorderButtonsHtml() {
  return (
    '<div class="favvid-reorder" style="display:flex;flex-direction:column;gap:2px;margin-left:6px;flex-shrink:0">' +
      '<button class="favvid-up" style="width:26px;height:22px;border-radius:6px;border:1px solid rgba(255,215,0,0.25);background:rgba(255,215,0,0.06);color:#ffd700;font-size:11px;cursor:pointer;line-height:1;padding:0">▲</button>' +
      '<button class="favvid-down" style="width:26px;height:22px;border-radius:6px;border:1px solid rgba(255,215,0,0.25);background:rgba(255,215,0,0.06);color:#ffd700;font-size:11px;cursor:pointer;line-height:1;padding:0">▼</button>' +
    '</div>'
  );
}

// Top-level entry for a GitHub-backed subfolder (Motivation/Naam Jap
// Mahima/Law of Karma): the auto-listed repo files, then — below —
// the same folders/links system as Random Links, scoped to this
// subfolder. Two containers appended up front (in order) so the file
// list and the links section each render into a fixed slot regardless
// of which async fetch resolves first.
function renderGithubVideoList(list, sub) {
  const fileSectionContainer = document.createElement('div');
  list.appendChild(fileSectionContainer);
  renderGithubFileSection(fileSectionContainer, sub);

  const linksSectionContainer = document.createElement('div');
  list.appendChild(linksSectionContainer);
  renderFavVideoLinksTop(linksSectionContainer, sub.key);
}

function renderGithubFileSection(list, sub) {
  const loading = document.createElement('div');
  loading.className = 'st-folder-empty';
  loading.textContent = 'লোড হচ্ছে…';
  list.appendChild(loading);

  Promise.all([getFavVideoFiles(sub), loadFavVideoOrder()]).then(([rawItems, orderDoc]) => {
    if (window._stActiveFolder !== 'videos' || window._stActiveVideoFolder !== sub.key) return; // navigated away meanwhile
    loading.remove();
    const items = favvidApplyOrder(rawItems, orderDoc[sub.key]);
    if (!items.length) {
      const empty = document.createElement('div');
      empty.className = 'st-folder-empty';
      empty.textContent = 'শীঘ্রই আসছে 🙏';
      list.appendChild(empty);
      return;
    }
    favvidSearchableSection(list, {
      placeholder: 'ভিডিও খুঁজুন…',
      allItems: items,
      renderCards: (filtered, container) => {
        filtered.forEach((v) => {
          const seenKey = 'video:' + sub.key + ':' + v.key;
          const card = document.createElement('div');
          card.className = 'st-card';
          card.innerHTML =
            '<div style="display:flex;align-items:center;justify-content:space-between;gap:8px">' +
              '<div class="favvid-open" style="display:flex;align-items:center;gap:10px;flex:1;min-width:0;cursor:pointer">' +
                '<span style="font-size:22px">▶️</span>' +
                '<div class="st-name" style="font-size:15px">' + escHtml(v.title) + '</div>' +
                favvidNewBadgeHtml(seenKey) +
              '</div>' +
              (isDeveloper() ? favvidReorderButtonsHtml() : '') +
            '</div>';
          card.querySelector('.favvid-open').addEventListener('click', () => {
            favvidMarkSeen(seenKey);
            const badge = card.querySelector('.favvid-new-badge');
            if (badge) badge.remove();
            openFavVideoPlayer(v.title, 'file', v.url);
          });
          if (isDeveloper()) {
            card.querySelector('.favvid-up').addEventListener('click', (e) => { e.stopPropagation(); favvidReorder(sub.key, items, v.key, -1); });
            card.querySelector('.favvid-down').addEventListener('click', (e) => { e.stopPropagation(); favvidReorder(sub.key, items, v.key, 1); });
          }
          container.appendChild(card);
        });
      },
    });
  }).catch(() => {
    if (window._stActiveFolder !== 'videos' || window._stActiveVideoFolder !== sub.key) return;
    loading.textContent = 'ভিডিও তালিকা লোড করা যায়নি — ইন্টারনেট সংযোগ পরীক্ষা করুন';
  });
}

// Real brand icons via Simple Icons' free CDN (cdn.simpleicons.org) —
// CC0-licensed SVG recreations made specifically for this kind of use,
// not the platforms' own proprietary app-icon artwork. Falls back to an
// emoji if the icon fails to load (e.g. no internet yet).
function favvidIconFallback(img) {
  const span = document.createElement('span');
  span.style.fontSize = '22px';
  span.textContent = img.getAttribute('data-fallback') || '🔗';
  img.replaceWith(span);
}
function favvidPlatformIconHtml(platform) {
  const map = {
    youtube: ['youtube', '▶️'],
    instagram: ['instagram', '📷'],
    telegram: ['telegram', '✈️'],
    drive: ['googledrive', '📁'],
    facebook: ['facebook', '📘'],
  };
  const entry = map[platform];
  if (!entry) return '<span style="font-size:22px">🔗</span>';
  return '<img src="https://cdn.simpleicons.org/' + entry[0] + '" alt="" width="22" height="22" data-fallback="' + entry[1] + '" onerror="favvidIconFallback(this)" style="display:block;border-radius:5px;flex-shrink:0">';
}

// Builds one link card (icon, title, NEW badge, dev-only edit/reorder/
// delete) and wires up its click-to-play routing. `items` must be the
// FULL (unfiltered) array for this bucket, so reorder stays correct
// even under an active search filter.
function favvidRenderLinkCard(v, items, bucketKey, container) {
  const seenKey = 'link:' + v.id;
  const platform = favvidDetectPlatform(v.url); // re-detect live so a detection fix auto-heals older saved links
  const card = document.createElement('div');
  card.className = 'st-card';

  function renderDisplayMode() {
    const platformIconHtml = favvidPlatformIconHtml(platform);
    let headerRight = '';
    if (isDeveloper()) {
      headerRight =
        '<button class="st-edit-btn favvid-edit" style="margin-right:4px">✎</button>' +
        favvidReorderButtonsHtml() +
        '<button class="st-edit-btn favvid-del" style="border-color:rgba(255,80,80,0.35);color:#ff8888;background:rgba(255,80,80,0.08);margin-left:4px">✕</button>';
    }
    card.innerHTML =
      '<div style="display:flex;align-items:center;justify-content:space-between;gap:8px">' +
        '<div class="favvid-open" style="display:flex;align-items:center;gap:10px;flex:1;min-width:0;cursor:pointer">' +
          platformIconHtml +
          '<div class="st-name" style="font-size:15px">' + escHtml(v.title) + '</div>' +
          favvidNewBadgeHtml(seenKey) +
        '</div>' +
        headerRight +
      '</div>';
    card.querySelector('.favvid-open').addEventListener('click', () => {
      favvidMarkSeen(seenKey);
      const badge = card.querySelector('.favvid-new-badge');
      if (badge) badge.remove();
      if (platform === 'youtube') {
        const id = favvidYoutubeId(v.url);
        if (id) openFavVideoPlayer(v.title, 'youtube', id); else openExternalLink(v.url);
      } else if (platform === 'telegram') {
        const embed = favvidTelegramEmbed(v.url);
        if (embed) openFavVideoPlayer(v.title, 'telegram', embed); else openExternalLink(v.url);
      } else if (platform === 'instagram') {
        openFavVideoPlayer(v.title, 'instagram', v.url);
      } else {
        // drive/facebook/other: open externally — see the fixed platforms'
        // history above for why inline embedding was dropped for these.
        openExternalLink(v.url);
      }
    });
    if (isDeveloper()) {
      card.querySelector('.favvid-edit').addEventListener('click', (e) => { e.stopPropagation(); renderEditMode(); });
      card.querySelector('.favvid-up').addEventListener('click', (e) => { e.stopPropagation(); favvidReorder(bucketKey, items, v.key, -1); });
      card.querySelector('.favvid-down').addEventListener('click', (e) => { e.stopPropagation(); favvidReorder(bucketKey, items, v.key, 1); });
      card.querySelector('.favvid-del').addEventListener('click', async (e) => {
        e.stopPropagation();
        const cur = (await loadFavVideoLinks(true)).filter((x) => x.id !== v.id);
        await saveFavVideoLinks(cur);
        renderSt();
      });
    }
  }

  function renderEditMode() {
    card.innerHTML =
      '<div style="font-size:11px;color:rgba(255,215,0,0.8);margin-bottom:6px;letter-spacing:1px">✎ Edit Link</div>' +
      '<input class="favvid-edit-title" value="' + escHtml(v.title) + '" style="width:100%;margin-bottom:8px;background:rgba(0,0,0,0.40);border:1px solid rgba(255,215,0,0.25);border-radius:10px;padding:9px 12px;color:var(--tl);font-size:14px;box-sizing:border-box;font-family:Inter,sans-serif">' +
      '<input class="favvid-edit-url" value="' + escHtml(v.url) + '" style="width:100%;margin-bottom:8px;background:rgba(0,0,0,0.40);border:1px solid rgba(255,215,0,0.25);border-radius:10px;padding:9px 12px;color:var(--tl);font-size:14px;box-sizing:border-box;font-family:Inter,sans-serif">' +
      '<div style="display:flex;gap:8px">' +
        '<button class="favvid-edit-save" style="padding:9px 18px;border-radius:10px;background:rgba(255,215,0,0.12);color:#ffd700;font-size:13px;font-weight:600;cursor:pointer;font-family:Inter,sans-serif;border:1px solid rgba(255,215,0,0.30)">💾 Save</button>' +
        '<button class="favvid-edit-cancel" style="padding:9px 18px;border-radius:10px;background:rgba(255,255,255,0.06);color:var(--tl);font-size:13px;cursor:pointer;font-family:Inter,sans-serif;border:1px solid rgba(255,255,255,0.15)">Cancel</button>' +
      '</div>';
    card.querySelector('.favvid-edit-cancel').addEventListener('click', () => renderSt());
    card.querySelector('.favvid-edit-save').addEventListener('click', async () => {
      const newTitle = card.querySelector('.favvid-edit-title').value.trim();
      const newUrl = card.querySelector('.favvid-edit-url').value.trim();
      if (!newTitle || !newUrl) return;
      const cur = (await loadFavVideoLinks(true)).map((x) =>
        x.id === v.id ? Object.assign({}, x, { title: newTitle, url: newUrl, platform: favvidDetectPlatform(newUrl) }) : x
      );
      await saveFavVideoLinks(cur);
      renderSt();
    });
  }

  renderDisplayMode();
  container.appendChild(card);
}

// Top-level Links view: add-link form (with a folder picker), a
// new-folder form, the folder tiles themselves, and — below those — an
// "orphan" section (search + list) for links not filed into any folder.
function renderFavVideoLinksTop(list, subfolderKey) {
  // Links live in Firestore behind an auth-required read, so a casual
  // visitor who hasn't signed in yet would otherwise always get an
  // empty list back and see the generic "coming soon" empty state —
  // even when the developer has already added links. Tell them to
  // sign in instead of implying nothing's there.
  if (!fbUser) {
    const signInMsg = document.createElement('div');
    signInMsg.className = 'st-folder-empty';
    signInMsg.textContent = 'Sign in to get links 🙏';
    list.appendChild(signInMsg);
    return;
  }

  const loading = document.createElement('div');
  loading.className = 'st-folder-empty';
  loading.textContent = 'লোড হচ্ছে…';
  list.appendChild(loading);

  Promise.all([loadFavVideoLinks(true), loadFavVideoLinkFolders(true), loadFavVideoOrder()]).then(([rawLinksAll, foldersAll, orderDoc]) => {
    if (window._stActiveFolder !== 'videos' || window._stActiveVideoFolder !== subfolderKey || window._stActiveLinkFolder) return;
    loading.remove();

    // Pre-existing links/folders saved before this feature had a
    // subfolder field default to 'links' (the original Random Links
    // folder), so nothing already saved disappears.
    const rawLinks = rawLinksAll.filter((l) => (l.subfolder || 'links') === subfolderKey);
    const folders = foldersAll.filter((f) => (f.subfolder || 'links') === subfolderKey);

    // ── Search bar, first thing shown ── filters folder names AND
    // orphan link titles together, live.
    const searchWrap = document.createElement('div');
    searchWrap.innerHTML = '<input type="text" placeholder="ফোল্ডার বা লিংক খুঁজুন…" style="width:100%;margin-bottom:10px;background:rgba(0,0,0,0.35);border:1px solid rgba(255,215,0,0.25);border-radius:10px;padding:9px 12px;color:var(--tl);font-size:14px;box-sizing:border-box;font-family:Inter,sans-serif">';
    list.appendChild(searchWrap);
    const searchInput = searchWrap.querySelector('input');

    if (isDeveloper()) {
      // ── Add Video Link — collapsed by default, tap header to expand.
      // window._favVidShowForm is keyed per subfolder so each of the
      // 4 folders remembers its own open/closed state independently,
      // and doesn't re-collapse after every add within a session.
      const addFormKey = 'add:' + subfolderKey;
      const folderOptionsHtml = '<option value="">(কোনো ফোল্ডার নয়)</option>' +
        folders.map((f) => '<option value="' + f.id + '">' + escHtml(f.name) + '</option>').join('');
      const form = document.createElement('div');
      form.className = 'st-card';
      form.innerHTML =
        '<div id="favVidAddFormHeader" style="display:flex;align-items:center;justify-content:space-between;cursor:pointer">' +
          '<div style="color:rgba(255,215,0,0.85);font-size:13px;font-weight:600;letter-spacing:0.5px">➕ Add Video Link</div>' +
          '<span id="favVidAddFormChevron" style="color:#ffd700;font-size:13px">' + (window._favVidShowForm && window._favVidShowForm[addFormKey] ? '▾' : '▸') + '</span>' +
        '</div>' +
        '<div id="favVidAddFormBody" style="display:' + (window._favVidShowForm && window._favVidShowForm[addFormKey] ? 'block' : 'none') + ';margin-top:10px">' +
          '<input id="favVidNewTitle" placeholder="Title" style="width:100%;margin-bottom:8px;background:rgba(0,0,0,0.40);border:1px solid rgba(255,215,0,0.25);border-radius:10px;padding:9px 12px;color:var(--tl);font-size:14px;box-sizing:border-box;font-family:Inter,sans-serif">' +
          '<input id="favVidNewUrl" placeholder="YouTube / Instagram / Telegram / Google Drive / Facebook link" style="width:100%;margin-bottom:8px;background:rgba(0,0,0,0.40);border:1px solid rgba(255,215,0,0.25);border-radius:10px;padding:9px 12px;color:var(--tl);font-size:14px;box-sizing:border-box;font-family:Inter,sans-serif">' +
          '<select id="favVidNewFolder" style="width:100%;margin-bottom:8px;background:rgba(0,0,0,0.40);border:1px solid rgba(255,215,0,0.25);border-radius:10px;padding:9px 12px;color:var(--tl);font-size:14px;box-sizing:border-box;font-family:Inter,sans-serif">' + folderOptionsHtml + '</select>' +
          '<button id="favVidAddBtn" style="padding:9px 20px;border-radius:10px;background:rgba(255,215,0,0.12);color:#ffd700;font-size:13px;font-weight:600;cursor:pointer;font-family:Inter,sans-serif;border:1px solid rgba(255,215,0,0.30)">💾 Save</button>' +
        '</div>';
      list.appendChild(form);
      form.querySelector('#favVidAddFormHeader').addEventListener('click', () => {
        window._favVidShowForm = window._favVidShowForm || {};
        window._favVidShowForm[addFormKey] = !window._favVidShowForm[addFormKey];
        form.querySelector('#favVidAddFormBody').style.display = window._favVidShowForm[addFormKey] ? 'block' : 'none';
        form.querySelector('#favVidAddFormChevron').textContent = window._favVidShowForm[addFormKey] ? '▾' : '▸';
      });
      form.querySelector('#favVidAddBtn').addEventListener('click', async () => {
        const title = form.querySelector('#favVidNewTitle').value.trim();
        const url = form.querySelector('#favVidNewUrl').value.trim();
        const folderId = form.querySelector('#favVidNewFolder').value || null;
        if (!title || !url) return;
        const platform = favvidDetectPlatform(url);
        const items = (await loadFavVideoLinks(true)).slice();
        items.push({ id: 'v' + Date.now(), title: title, url: url, platform: platform, folderId: folderId, subfolder: subfolderKey, addedAt: Date.now() });
        await saveFavVideoLinks(items);
        renderSt();
      });

      // ── New Folder — same collapsed-by-default pattern.
      const folderFormKey = 'folder:' + subfolderKey;
      const folderForm = document.createElement('div');
      folderForm.className = 'st-card';
      folderForm.innerHTML =
        '<div id="favVidNewFolderHeader" style="display:flex;align-items:center;justify-content:space-between;cursor:pointer">' +
          '<div style="color:rgba(255,215,0,0.85);font-size:13px;font-weight:600;letter-spacing:0.5px">📁 New Folder</div>' +
          '<span id="favVidNewFolderChevron" style="color:#ffd700;font-size:13px">' + (window._favVidShowForm && window._favVidShowForm[folderFormKey] ? '▾' : '▸') + '</span>' +
        '</div>' +
        '<div id="favVidNewFolderBody" style="display:' + (window._favVidShowForm && window._favVidShowForm[folderFormKey] ? 'flex' : 'none') + ';gap:8px;margin-top:10px">' +
          '<input id="favVidNewFolderName" placeholder="Folder name" style="flex:1;min-width:0;background:rgba(0,0,0,0.40);border:1px solid rgba(255,215,0,0.25);border-radius:10px;padding:9px 12px;color:var(--tl);font-size:14px;box-sizing:border-box;font-family:Inter,sans-serif">' +
          '<button id="favVidAddFolderBtn" style="padding:9px 16px;border-radius:10px;background:rgba(255,215,0,0.12);color:#ffd700;font-size:13px;font-weight:600;cursor:pointer;font-family:Inter,sans-serif;border:1px solid rgba(255,215,0,0.30);white-space:nowrap;flex-shrink:0">+ Create</button>' +
        '</div>';
      list.appendChild(folderForm);
      folderForm.querySelector('#favVidNewFolderHeader').addEventListener('click', () => {
        window._favVidShowForm = window._favVidShowForm || {};
        window._favVidShowForm[folderFormKey] = !window._favVidShowForm[folderFormKey];
        folderForm.querySelector('#favVidNewFolderBody').style.display = window._favVidShowForm[folderFormKey] ? 'flex' : 'none';
        folderForm.querySelector('#favVidNewFolderChevron').textContent = window._favVidShowForm[folderFormKey] ? '▾' : '▸';
      });
      folderForm.querySelector('#favVidAddFolderBtn').addEventListener('click', async () => {
        const name = folderForm.querySelector('#favVidNewFolderName').value.trim();
        if (!name) return;
        const cur = (await loadFavVideoLinkFolders(true)).slice();
        cur.push({ id: 'lf' + Date.now(), name: name, subfolder: subfolderKey });
        await saveFavVideoLinkFolders(cur);
        renderSt();
      });
    }

    // ── Folders, then orphan links below — both filtered live by the
    // search bar above.
    const bodyContainer = document.createElement('div');
    list.appendChild(bodyContainer);

    const orphanItemsFull = favvidApplyOrder(
      rawLinks.filter((l) => !l.folderId).map((l) => Object.assign({}, l, { key: l.id })),
      orderDoc[subfolderKey + ':_orphan']
    );

    function renderBody() {
      const q = searchInput.value.trim().toLowerCase();
      bodyContainer.innerHTML = '';
      const filteredFolders = q ? folders.filter((f) => f.name.toLowerCase().indexOf(q) !== -1) : folders;
      const filteredOrphans = q ? orphanItemsFull.filter((v) => v.title.toLowerCase().indexOf(q) !== -1) : orphanItemsFull;

      filteredFolders.forEach((f) => {
        const count = rawLinks.filter((l) => l.folderId === f.id).length;
        const tile = document.createElement('div');
        tile.className = 'st-folder-tile';

        function renderTileDisplay() {
          tile.innerHTML =
            '<span class="st-folder-tile-icon">📁</span>' +
            '<span class="st-folder-tile-title">' + escHtml(f.name) + '</span>' +
            '<span class="st-folder-tile-count">' + count + '</span>' +
            (isDeveloper() ? '<button class="favvid-folder-edit" style="margin-left:8px;width:26px;height:26px;border-radius:8px;border:1px solid rgba(255,215,0,0.3);color:#ffd700;background:rgba(255,215,0,0.08);font-size:13px;cursor:pointer;flex-shrink:0">✎</button><button class="favvid-folder-del" style="margin-left:6px;width:26px;height:26px;border-radius:8px;border:1px solid rgba(255,80,80,0.35);color:#ff8888;background:rgba(255,80,80,0.08);font-size:13px;cursor:pointer;flex-shrink:0">✕</button>' : '') +
            '<span class="st-folder-tile-arrow">›</span>';
          tile.onclick = (e) => {
            if (e.target.closest('.favvid-folder-del') || e.target.closest('.favvid-folder-edit')) return;
            window._stActiveLinkFolder = f.id;
            renderSt();
          };
          const editBtn = tile.querySelector('.favvid-folder-edit');
          if (editBtn) editBtn.addEventListener('click', (e) => { e.stopPropagation(); renderTileEdit(); });
          const delBtn = tile.querySelector('.favvid-folder-del');
          if (delBtn) {
            delBtn.addEventListener('click', async (e) => {
              e.stopPropagation();
              // Deleting a folder only un-files its links (back to orphan) —
              // never deletes the links themselves.
              const links = (await loadFavVideoLinks(true)).map((l) => (l.folderId === f.id ? Object.assign({}, l, { folderId: null }) : l));
              await saveFavVideoLinks(links);
              const remaining = (await loadFavVideoLinkFolders(true)).filter((x) => x.id !== f.id);
              await saveFavVideoLinkFolders(remaining);
              renderSt();
            });
          }
        }

        function renderTileEdit() {
          tile.innerHTML =
            '<input class="favvid-folder-edit-name" value="' + escHtml(f.name) + '" style="flex:1;min-width:0;background:rgba(0,0,0,0.40);border:1px solid rgba(255,215,0,0.25);border-radius:10px;padding:8px 10px;color:var(--tl);font-size:14px;box-sizing:border-box;font-family:Inter,sans-serif;margin-right:8px">' +
            '<button class="favvid-folder-edit-save" style="padding:8px 14px;border-radius:8px;background:rgba(255,215,0,0.12);color:#ffd700;font-size:12px;font-weight:600;cursor:pointer;font-family:Inter,sans-serif;border:1px solid rgba(255,215,0,0.30);white-space:nowrap;margin-right:6px">💾</button>' +
            '<button class="favvid-folder-edit-cancel" style="padding:8px 14px;border-radius:8px;background:rgba(255,255,255,0.06);color:var(--tl);font-size:12px;cursor:pointer;font-family:Inter,sans-serif;border:1px solid rgba(255,255,255,0.15);white-space:nowrap">✕</button>';
          tile.onclick = null;
          tile.querySelector('.favvid-folder-edit-cancel').addEventListener('click', (e) => { e.stopPropagation(); renderSt(); });
          tile.querySelector('.favvid-folder-edit-save').addEventListener('click', async (e) => {
            e.stopPropagation();
            const newName = tile.querySelector('.favvid-folder-edit-name').value.trim();
            if (!newName) return;
            const cur = (await loadFavVideoLinkFolders(true)).map((x) => (x.id === f.id ? Object.assign({}, x, { name: newName }) : x));
            await saveFavVideoLinkFolders(cur);
            renderSt();
          });
        }

        renderTileDisplay();
        bodyContainer.appendChild(tile);
      });

      if (folders.length) {
        const header = document.createElement('div');
        header.style.cssText = 'margin:14px 0 8px;color:rgba(255,215,0,0.55);font-size:12px;letter-spacing:1px';
        header.textContent = '— অন্যান্য লিংক (কোনো ফোল্ডারে নেই) —';
        bodyContainer.appendChild(header);
      }

      if (!filteredOrphans.length) {
        const empty = document.createElement('div');
        empty.className = 'st-folder-empty';
        empty.textContent = q ? 'কিছু পাওয়া যায়নি' : 'শীঘ্রই আসছে 🙏';
        bodyContainer.appendChild(empty);
      } else {
        filteredOrphans.forEach((v) => favvidRenderLinkCard(v, orphanItemsFull, subfolderKey + ':_orphan', bodyContainer));
      }
    }
    searchInput.addEventListener('input', renderBody);
    renderBody();
  });
}

// Inside one specific link folder — its own back row (needs the
// folder's name, only known after the fetch resolves) plus a search bar
// scoped to just this folder's links.
function renderFavVideoLinksFolderView(list, folderId, subfolderKey) {
  if (!fbUser) {
    const signInMsg = document.createElement('div');
    signInMsg.className = 'st-folder-empty';
    signInMsg.textContent = 'Sign in to get links 🙏';
    list.appendChild(signInMsg);
    return;
  }

  const loading = document.createElement('div');
  loading.className = 'st-folder-empty';
  loading.textContent = 'লোড হচ্ছে…';
  list.appendChild(loading);

  Promise.all([loadFavVideoLinks(true), loadFavVideoLinkFolders(true), loadFavVideoOrder()]).then(([rawLinks, folders, orderDoc]) => {
    if (window._stActiveFolder !== 'videos' || window._stActiveVideoFolder !== subfolderKey || window._stActiveLinkFolder !== folderId) return;
    loading.remove();

    const folder = folders.find((f) => f.id === folderId);
    const parentSub = VIDEO_SUBFOLDERS.find((s) => s.key === subfolderKey);

    const backRow = document.createElement('div');
    backRow.className = 'st-back-row';
    backRow.innerHTML =
      '<button class="st-back-btn">← ' + escHtml(parentSub ? parentSub.title : '') + '</button>' +
      '<span class="st-back-title">' + escHtml(folder ? folder.name : '') + '</span>';
    backRow.querySelector('.st-back-btn').addEventListener('click', () => {
      window._stActiveLinkFolder = null;
      renderSt();
    });
    list.appendChild(backRow);

    if (!folder) { window._stActiveLinkFolder = null; renderSt(); return; }

    if (isDeveloper()) {
      const form = document.createElement('div');
      form.className = 'st-card';
      form.innerHTML =
        '<div style="font-size:11px;color:rgba(255,215,0,0.8);margin-bottom:6px;letter-spacing:1px">➕ Add Video Link to "' + escHtml(folder.name) + '"</div>' +
        '<input id="favVidNewTitle" placeholder="Title" style="width:100%;margin-bottom:8px;background:rgba(0,0,0,0.40);border:1px solid rgba(255,215,0,0.25);border-radius:10px;padding:9px 12px;color:var(--tl);font-size:14px;box-sizing:border-box;font-family:Inter,sans-serif">' +
        '<input id="favVidNewUrl" placeholder="YouTube / Instagram / Telegram / Google Drive / Facebook link" style="width:100%;margin-bottom:8px;background:rgba(0,0,0,0.40);border:1px solid rgba(255,215,0,0.25);border-radius:10px;padding:9px 12px;color:var(--tl);font-size:14px;box-sizing:border-box;font-family:Inter,sans-serif">' +
        '<button id="favVidAddBtn" style="padding:9px 20px;border-radius:10px;background:rgba(255,215,0,0.12);color:#ffd700;font-size:13px;font-weight:600;cursor:pointer;font-family:Inter,sans-serif;border:1px solid rgba(255,215,0,0.30)">💾 Save</button>';
      list.appendChild(form);
      form.querySelector('#favVidAddBtn').addEventListener('click', async () => {
        const title = form.querySelector('#favVidNewTitle').value.trim();
        const url = form.querySelector('#favVidNewUrl').value.trim();
        if (!title || !url) return;
        const platform = favvidDetectPlatform(url);
        const items2 = (await loadFavVideoLinks(true)).slice();
        items2.push({ id: 'v' + Date.now(), title: title, url: url, platform: platform, folderId: folderId, subfolder: subfolderKey, addedAt: Date.now() });
        await saveFavVideoLinks(items2);
        renderSt();
      });
    }

    const items = favvidApplyOrder(
      rawLinks.filter((l) => l.folderId === folderId).map((l) => Object.assign({}, l, { key: l.id })),
      orderDoc['folder:' + folderId]
    );
    favvidSearchableSection(list, {
      placeholder: 'লিংক খুঁজুন…',
      allItems: items,
      renderCards: (filtered, container) => {
        filtered.forEach((v) => favvidRenderLinkCard(v, items, 'folder:' + folderId, container));
      },
    });
  });
}


function renderSt() {
  const list = document.getElementById("stList");
  try { if (window.prefetchGita) window.prefetchGita(); } catch (_e) {}   // Gita text is downloaded on demand: start it as soon as S&V is shown
  // Pick up stotrams newly added to the repo (throttled; redraws only if changed).
  if (!window._liveStCacheLoaded) { window._liveStCacheLoaded = true; _liveStLoadCache(); }
  liveStRefresh(false);
  // First render: pull uploaded custom-stotram audio state, then redraw once.
  if (!_stAudioLoaded && !window._stAudioLoading && (App.S.customSt || []).length) {
    window._stAudioLoading = true;
    stAudioLoadAll().then(() => { window._stAudioLoading = false; renderSt(); });
  }
  // The "Add Your Stotram" box may have been moved under the Stotrams headline
  // (folder menu) — put it back above the list before clearing so it isn't destroyed.
  const _af = document.getElementById('stAddForm');
  if (_af && _af.parentNode === list) list.parentNode.insertBefore(_af, list);
  list.innerHTML = "";

  // "Stotram Tracker" title + "Add Your Stotram" box don't apply inside
  // Favourite Videos — hide them there, restore for every other folder.
  const trackerTitle = document.getElementById('stTrackerTitle');
  const addForm = document.getElementById('stAddForm');
  const inVideos = window._stActiveFolder === 'videos';
  // Ashtayam Seva Paddhati (inside the Radha Vallabh folder) is a reading
  // view too — no jap-counter tracker / add-stotram box there either.
  const inSeva = window._stActiveFolder === 'rv' && !!window._stSevaOpen;
  const inVed = window._stActiveFolder === 'rv' && !!window._stVedOpen;
  if (trackerTitle) trackerTitle.style.display = (inVideos || inSeva || inVed) ? 'none' : '';
  if (addForm) addForm.style.display = (inVideos || inSeva || inVed) ? 'none' : '';

  // Inject premium glow animations once
  if (!document.getElementById('st-card-styles')) {
    const styleEl = document.createElement('style');
    styleEl.id = 'st-card-styles';
    styleEl.textContent = [
      '@keyframes stCardGlow{0%,100%{box-shadow:0 0 7px 1px var(--sgc,#ffd700),0 2px 18px rgba(0,0,0,0.55);border-color:rgba(255,215,0,0.30)}50%{box-shadow:0 0 22px 5px var(--sgc,#ffd700),0 2px 24px rgba(0,0,0,0.65);border-color:rgba(255,215,0,0.72)}}',
      '@keyframes stColorCycle{0%{--sgc:#ffd700}20%{--sgc:#ff9d00}40%{--sgc:#ff6bff}60%{--sgc:#00e5ff}80%{--sgc:#7dff6b}100%{--sgc:#ffd700}}',
      '@keyframes stNameShimmer{0%,100%{background-position:-200% center}100%{background-position:200% center}}',
      '@keyframes stFadeUp{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:translateY(0)}}',
      '@keyframes stCountPop{0%{transform:scale(1)}40%{transform:scale(1.22);color:#fff}100%{transform:scale(1)}}',
      '.st-card{animation:stCardGlow var(--spd,3.2s) ease-in-out infinite,stColorCycle var(--scd,10s) ease-in-out infinite,stFadeUp 0.45s ease both;animation-delay:var(--sad,0s),var(--sod,0s),var(--sfd,0s);background:rgba(0,0,0,0.48);border:1px solid rgba(255,215,0,0.30);border-radius:16px;padding:16px 16px 14px;margin-bottom:12px;box-sizing:border-box;transition:transform 0.15s;-webkit-tap-highlight-color:transparent}',
      '.st-card:active{transform:scale(0.985)}',
      '.st-name{background:linear-gradient(90deg,#ffd700 0%,#fff8dc 30%,#ffaa00 50%,#fff8dc 70%,#ffd700 100%);background-size:200% auto;-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;animation:stNameShimmer 3.5s linear infinite;font-family:"Hind Siliguri",serif;font-size:17px;font-weight:700;line-height:1.3}',
      '.st-sub{font-family:"Hind Siliguri",serif;font-size:12px;color:rgba(255,215,0,0.45);margin-top:3px;letter-spacing:0.3px}',
      '.st-count{font-size:40px;font-weight:700;color:#ffd700;line-height:1;font-family:"Inter",sans-serif;text-shadow:0 0 12px rgba(255,215,0,0.5)}',
      '.st-count.pop{animation:stCountPop 0.3s ease}',
      '.st-meta{font-size:11px;color:rgba(255,215,0,0.42);margin-top:4px;letter-spacing:0.3px}',
      '.st-meta strong{color:rgba(255,215,0,0.80)}',
      '.st-row{display:flex;align-items:center;justify-content:space-between;margin-top:12px;gap:8px}',
      '.st-btns{display:flex;gap:8px}',
      '.st-btn{width:44px;height:44px;border-radius:12px;border:1px solid rgba(255,215,0,0.30);background:rgba(255,215,0,0.08);color:#ffd700;font-size:20px;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:background 0.15s,box-shadow 0.15s;-webkit-tap-highlight-color:transparent}',
      '.st-btn:active{background:rgba(255,215,0,0.22);box-shadow:0 0 10px 2px rgba(255,215,0,0.4)}',
      '.st-btn.read{font-size:18px}',
      '.st-btns{align-items:flex-end;gap:12px}',
      '.st-btn.st-mini{width:32px;height:32px;border-radius:9px;font-size:17px}',
      '.st-pm{display:flex;flex-direction:column;align-items:center;gap:4px}',
      '.st-pm-lab{font-size:10px;color:rgba(255,215,0,0.55);letter-spacing:0.3px}',
      '.st-pm-row{display:flex;gap:8px}',
      '.st-pm-col{display:flex;flex-direction:column;align-items:center;gap:2px}',
      '.st-pm-cap{font-size:9px;color:rgba(255,215,0,0.45)}',
      '.st-open-btn{height:40px;padding:0 20px;border:none;border-radius:12px;background:linear-gradient(135deg,#ffe27a 0%,#ffc107 45%,#e69500 100%);color:#2a1a00;font-weight:700;font-size:15px;font-family:"Hind Siliguri",sans-serif;cursor:pointer;box-shadow:0 0 12px rgba(255,200,0,0.45),inset 0 1px 0 rgba(255,255,255,0.5);-webkit-tap-highlight-color:transparent}',
      '.st-open-btn:active{transform:scale(0.96);box-shadow:0 0 18px rgba(255,200,0,0.7)}',
      '.st-edit-btn{font-size:13px;width:32px;height:32px;border-radius:8px;border:1px solid rgba(74,144,226,0.35);background:rgba(74,144,226,0.10);color:#7ab8ff;cursor:pointer;display:flex;align-items:center;justify-content:center}',
    ].join('');
    document.head.appendChild(styleEl);
  }

  // S&V stotram folders, in display order. Sampraday folders sit just below Radha Vallabh;
  // Krishna / Gita / Shiv follow as before. To re-sort, just re-order the lines below.
  const FOLDERS = [
    { key: 'videos',  title: 'Favourite Videos', titleHi: 'पसंदीदा वीडियो', icon: '🎬' },
    { key: 'rv',      title: 'রাধা বল্লভ সম্প্রদায়', titleHi: 'राधावल्लभ सम्प्रदाय', icon: '🪷', img: ST_FOLDER_ICON_IMG.rv },
    { key: 'hd',      title: 'হরিদাসী সম্প্রদায়', titleHi: 'हरिदासी सम्प्रदाय', icon: '🪕', img: 'sampraday/tilaks/haridashi.png' },
    { key: 'najrul', title: 'Kazi Najrul Islam is a real modern-day Saint Poet', titleHi: 'Kazi Najrul Islam is a real modern-day Saint Poet', icon: '🌙', img: NAJRUL_ICON_IMG, imgRound: true },
    { key: 'fav',     title: 'প্রিয় স্তোত্র ও পদসমূহ', titleHi: 'प्रिय स्तोत्र एवं पदसमूह', icon: '⭐' },
    { key: 'nb',      title: 'নিম্বার্ক (কুমার / হংস) সম্প্রদায়', titleHi: 'निम्बार्क (कुमार / हंस) सम्प्रदाय', icon: '🎶', img: 'sampraday/tilaks/nimbark.png' },
    { key: 'vl',      title: 'বল্লভ / রুদ্র সম্প্রদায় (পুষ্টিমার্গ)', titleHi: 'वल्लभ / रुद्र सम्प्रदाय (पुष्टिमार्ग)', icon: '🪈', img: 'sampraday/tilaks/vallabh.png' },
    { key: 'rm',      title: 'শ্রী সম্প্রদায় (রামানন্দী পরম্পরা)', titleHi: 'श्री सम्प्रदाय (रामानन्दी परम्परा)', icon: '🚩', img: 'sampraday/tilaks/sri.png' },
    { key: 'ru',      title: 'শ্রী সম্প্রদায় (রামানুজ পরম্পরা)', titleHi: 'श्री सम्प्रदाय (रामानुज परम्परा)', icon: '🪷', img: 'sampraday/tilaks/sri.png' },
    { key: 'bmg',     title: 'ব্রাহ্ম মাধ্ব গৌড়ীয় সম্প্রদায়', titleHi: 'ब्रह्म माध्व गौड़ीय सम्प्रदाय', icon: '🕉️', img: ST_FOLDER_ICON_IMG.bmg },
    { key: 'sk',      title: 'শঙ্করাচার্য (অদ্বৈত / স্মার্ত) পরম্পরা', titleHi: 'शंकराचार्य (अद्वैत / स्मार्त) परम्परा', icon: '🕉️' },
    { key: 'krishna', title: 'শ্রীকৃষ্ণ', titleHi: 'श्रीकृष्ण', icon: '🦚' },
    { key: 'shiv',    title: 'ভগবান শিব', titleHi: 'भगवान शिव', icon: '🔱', img: ST_FOLDER_ICON_IMG.shiv },
    { key: 'rjbj', title: 'রসিক, বৈষ্ণব ও অন্যান্য ভক্ত এবং সন্তজন দর্শন ও পরিচিতি', titleHi: 'रसिक, वैष्णव एवं अन्य भक्त तथा संतजन दर्शन एवं परिचय', icon: '🙏' },
    { key: 'dd', title: 'দিব্য দর্শন — বৃন্দাবনের শ্রীবিগ্রহ', titleHi: 'दिव्य दर्शन — वृन्दावन के श्रीविग्रह', icon: '🛕' },
  ];
  // Pick the language-appropriate folder title, falling back to the
  // Bangla (default) one whenever a Hindi title isn't set (e.g. custom
  // group added later).
  const folderTitle = (f) => (secLang('sv') === 'hi' && f.titleHi) ? f.titleHi : f.title;

  const customItems = (App.S.customSt || []).map((x) => ({ ...x, custom: true }));
  const groups = FOLDERS.map((f) => ({
    ...f,
    items: _stFolderItems(f.key),
  }));
  if (customItems.length) {
    groups.push({ key: '__custom', title: 'আমার স্তোত্র', titleHi: 'मेरे स्तोत्र', icon: '📝', items: customItems });
  }

  const activeKey = window._stActiveFolder || null;

  // ── Level 1: folder menu (no active folder selected) ──
  if (!activeKey) {
    // S&V order: 1) Rasik/Vaishnav/Bhakta & Sant Darshan  2) Divya Darshan
    // 3) Favourite Videos  — then a "Stotrams" headline with all stotram folders under it.
    const TOP_ORDER = ['rjbj', 'dd', 'videos'];
    const topGroups = TOP_ORDER.map((k) => groups.find((g) => g.key === k)).filter(Boolean);
    const stotramGroups = groups.filter((g) => TOP_ORDER.indexOf(g.key) === -1);
    const _svHi = secLang('sv') === 'hi';
    const addHead = (txt) => {
      const h = document.createElement('div');
      h.className = 'st-section-head';
      h.style.cssText = 'margin:18px 4px 10px;padding:0 0 6px;font-size:13px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:var(--gold,#ffd700);border-bottom:1px solid rgba(245,209,122,0.28);font-family:"Hind Siliguri",serif;';
      h.textContent = txt;
      list.appendChild(h);
    };
    const addTile = (group) => {
      const tile = document.createElement('div');
      tile.className = 'st-folder-tile';
      // Sampraday-sign image (rv/shiv/bmg) when we have one, else the emoji.
      const iconHtml = group.img
        ? '<img class="st-folder-tile-icon-img" src="' + group.img + '" alt="" draggable="false" loading="lazy"' + (group.imgRound ? ' style="border-radius:50%;object-fit:cover;border:1px solid rgba(255,215,0,0.55);"' : '') + '>'
        : '<span class="st-folder-tile-icon">' + group.icon + '</span>';
      tile.innerHTML =
        iconHtml +
        '<span class="st-folder-tile-title">' + escHtml(folderTitle(group)) + '</span>' +
        (group.key === 'videos' || group.key === 'rjbj' || group.key === 'dd' || !group.items.length ? '' : '<span class="st-folder-tile-count">' + group.items.length + '</span>') +
        '<span class="st-folder-tile-arrow">›</span>';
      tile.addEventListener('click', () => {
        window._stActiveFolder = group.key;
        window._stActiveVideoFolder = null;
        window._stSevaOpen = false; window._stVedOpen = false; window._stRvFavOpen = false;
        window._stRvSub = null;
        window._stSevaSection = null;
        window._ddSel = null;
        renderSt();
      });
      list.appendChild(tile);
    };
    try { _hcjWarmSet([]); } catch (_e) {}
    topGroups.forEach(addTile);
    addHead(_svHi ? '🪔 स्तोत्र' : '🪔 স্তোত্র');
    if (_af) list.appendChild(_af);   // "Add Your Stotram" lives under the Stotrams headline
    stotramGroups.forEach(addTile);
    return;
  }

  // ── Level 2: inside a folder — back button + its stotrams ──
  const group = groups.find((g) => g.key === activeKey);
  try { _hcjWarmForFolder(activeKey); } catch (_e) {}
  if (!group) {
    // Folder no longer exists (shouldn't happen) — bail back to menu.
    window._stActiveFolder = null;
    renderSt();
    return;
  }

  // Radha Vallabh: main list = ved4/asp + the 8 granths; "Favourite Stotra, Pads"
  // (items flagged fav:true, Radha Kripa Kataksha first … Radha Chalisa last) is
  // its own sub-list opened from a tile at the bottom.
  if (activeKey === 'rv') {
    const _rvFavOn = !!window._stRvFavOpen;
    // Favourite Stotra, Pads are shown open in the same list (not a collapsed folder).
    window._stRvFavOpen = false;
  }

  // Favourite Videos is a different kind of folder (video subfolders,
  // not jap-counter stotram cards) — hand off to its own renderer.
  if (activeKey === 'videos') {
    renderFavVideoFolder(list);
    return;
  }

  // Ashtayam Seva Paddhati: its 9 section folders / reader (Radha Vallabh).
  if (activeKey === 'rv' && window._stVedOpen) {
    renderVed4(list);
    return;
  }

  if (activeKey === 'rv' && window._stSevaOpen) {
    renderSevaPaddhati(list);
    return;
  }

  // Divine Darshan of Vrindavan Deities: photos + aavirbhav katha + bhajan.
  if (activeKey === 'dd') {
    renderDeityDarshan(list);
    return;
  }

  // Rasik Jan o Bhakta Jan: standalone auto-advancing photo carousel.
  if (activeKey === 'rjbj') {
    renderRashikJan(list);
    return;
  }

  const backRow = document.createElement('div');
  backRow.className = 'st-back-row';
  backRow.innerHTML =
    '<button class="st-back-btn">← ' + (secLang('sv') === 'hi' ? 'फ़ोल्डर सूची' : 'ফোল্ডার তালিকা') + '</button>' +
    '<span class="st-back-title">' + escHtml((activeKey === 'rv' && window._stRvSub && window._stRvSubTitle) ? (secLang('sv') === 'hi' ? window._stRvSubTitle.hi : window._stRvSubTitle.bn) : (activeKey === 'rv' && window._stRvFavOpen) ? _favPadLabel() : folderTitle(group)) + '</span>';
  backRow.querySelector('.st-back-btn').addEventListener('click', () => {
    if (window._stRvFavOpen) { window._stRvFavOpen = false; renderSt(); return; }
    if (activeKey === 'rv' && window._stRvSub) { window._stRvSub = null; renderSt(); return; }
    window._stActiveFolder = null;
    window._stSevaOpen = false; window._stVedOpen = false;
    window._stSevaSection = null;
    renderSt();
  });
  list.appendChild(backRow);

  if (!group.items.length) {
    const empty = document.createElement('div');
    empty.className = 'st-folder-empty';
    empty.textContent = secLang('sv') === 'hi' ? 'जल्द ही आ रहा है 🙏' : 'শীঘ্রই আসছে 🙏';
    list.appendChild(empty);
    return;
  }

  const glowColors = ['#ffd700','#ffaa00','#ff6bff','#00e5ff','#7dff6b','#ff6b6b','#b388ff','#00ffcc','#ffd700','#ff9d00'];

  let idx = 0;
  let _favHeadDone = false;
  // ── Radha Vallabh folder layout ──
  // Top level: plain cards + sub-folder tiles. Each {folder:…} entry becomes a folder
  // tile that opens its own list (with a back button). Inside a folder, {h:2} is a
  // small sub-heading. Any rv stotram NOT named below is appended at the top level
  // under an "Others" folder, so nothing ever disappears. Re-arrange by moving ids.
  const _RV_LAYOUT = [
    ['ved4', 'asp', 'hcj', 'rsn'],
    { folder: 'sev', poet: 'sv', bn: 'সেবক বাণী', hi: 'सेवक वाणी',
      subBn: 'সেবক জীর পরিচয়, সেবক বাণী ও হিত মঙ্গল গান', subHi: 'सेवक जी का परिचय, सेवक वाणी एवं हित मंगल गान',
      reqBn: '★ অবশ্য পাঠ্য — প্রতিদিন ৫টি পদ (অর্থ সহ)', reqHi: '★ अनिवार्य — प्रतिदिन ५ पद (अर्थ सहित)',
      items: ['svi', 'svb', 'hmg'] },
    ['rmm', 'pdv'],
    { folder: 'hh', poet: 'hh', subBn: 'স্ফুট বাণী, যমুনাষ্টক, অষ্টাদশ সিদ্ধান্ত, ইষ্টারাধন প্রকরণ ও পত্র', subHi: 'स्फुट वाणी, यमुनाष्टक, अष्टादश सिद्धान्त, इष्टाराधन प्रकरण एवं पत्र', bn: 'শ্রী হিত হরিবংশ মহাপ্রভুর অন্যান্য', hi: 'श्री हित हरिवंश महाप्रभु की अन्य रचनाएँ',
      items: ['sfv', 'yms', 'asd', 'ipr', 'ptr'] },
    { folder: 'dhv', poet: 'dh', subBn: 'পরিচয়, লীলানুক্রমণিকা, বাণী প্রসংশা, নামাবলী ও পদ্যাবলী', subHi: 'परिचय, लीलानुक्रमणिका, वाणी प्रसंशा, नामावली एवं पद्यावली', bn: 'বয়ালীস লীলা ও ধ্রুবদাস জীর অন্যান্য', hi: 'बयालीस लीला एवं ध्रुवदास जी की अन्य रचनाएँ',
      items: ['dhi', 'bla', 'blv', 'bvp', 'nmb', 'bln', 'blp'] },
    { folder: 'vnn', icon: '🙏', subBn: 'বন্দনা ও নামাবলীর সংগ্রহ', subHi: 'वन्दना एवं नामावली संग्रह', bn: 'বন্দনা ও নামাবলী', hi: 'वन्दना एवं नामावली',
      items: ['rkn',
        { h: 2, bn: 'আচার্য · ইষ্ট · গুরু বন্দনা', hi: 'आचार्य · इष्ट · गुरु वन्दना' },
        'acv', 'ist', 'isv', 'gvn', 'svk',
        { h: 2, bn: 'রসিক ও ভক্ত নামাবলী', hi: 'रसिक एवं भक्त नामावली' },
        'rnm', 'bnm', 'bkt', 'vnm'] },
    { folder: 'utv', subBn: 'ব্যাহুলা, ঝুলন, বধাই, পালনা, ছঠী ও দসূঠন', subHi: 'व्याहुला, झूलन, बधाई, पालना, छठी एवं दसूठन', bn: 'উৎসব ও বধাই', hi: 'उत्सव एवं बधाई',
      items: ['vyh', 'jhp', 'jbp', 'ljb', 'sjb', 'ljp', 'sjp', 'ljc', 'sjc', 'ljd', 'sjd'] },
    ['kjk', 'pkp'],
  ];
  let _listItems = group.items;
  if (activeKey === 'rv') {
    const byId = {}; group.items.forEach((x) => { byId[x.id] = x; });
    const used = {};
    const take = (id) => { if (byId[id] && !used[id]) { used[id] = 1; return byId[id]; } return null; };
    const folders = {};
    const top = [];
    _RV_LAYOUT.forEach((e) => {
      if (Array.isArray(e)) { e.forEach((id) => { const x = take(id); if (x) top.push(x); }); return; }
      const inner = [];
      e.items.forEach((it) => {
        if (typeof it === 'string') { const x = take(it); if (x) inner.push(x); }
        else inner.push({ __head: it });
      });
      const n = inner.filter((x) => !x.__head).length;
      if (!n) return;
      folders[e.folder] = { def: e, inner };
      top.push({ __folder: Object.assign({ count: n }, e) });
    });
    const rest = group.items.filter((x) => !used[x.id]);
    if (rest.length) {
      const def = { folder: 'oth', icon: '📚', bn: 'অন্যান্য', hi: 'अन्य' };
      folders.oth = { def, inner: rest };
      top.push({ __folder: Object.assign({ count: rest.length }, def) });
    }
    const sub = window._stRvSub && folders[window._stRvSub];
    if (window._stRvSub && !sub) window._stRvSub = null;
    _listItems = sub ? sub.inner : top;
  }
  let _lastGrp = null;
  _listItems.forEach((st) => {
    if (st.__folder) {
      // Folder shown as a full-size stotram-style card (optional round photo / emoji icon,
      // name, sub-line, optional "must read" badge, and an Open button).
      const fd = st.__folder;
      const _hiF = secLang('sv') === 'hi';
      const gcF = glowColors[idx % glowColors.length];
      const fc = document.createElement('div');
      fc.className = 'st-card';
      fc.style.cssText = '--sgc:' + gcF + ';--spd:' + (2.8 + (idx % 5) * 0.45).toFixed(1) + 's;--scd:' + (9 + (idx % 4) * 1.5).toFixed(1) + 's;--sad:' + (idx * 0.055).toFixed(2) + 's;--sod:-' + (idx * 0.7).toFixed(1) + 's;--sfd:' + (idx * 0.055).toFixed(2) + 's;cursor:pointer;';
      let iconF = '';
      if (fd.poet && RV_POET_IMG[fd.poet]) {
        iconF = '<img src="' + RV_POET_IMG[fd.poet] + '" alt="" draggable="false" style="width:42px;height:42px;border-radius:50%;object-fit:cover;flex-shrink:0;border:1px solid rgba(255,215,0,0.55);box-shadow:0 0 8px rgba(255,215,0,0.25)">';
      } else if (fd.icon) {
        iconF = '<span style="width:42px;height:42px;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:30px;line-height:1">' + fd.icon + '</span>';
      }
      const reqF = _hiF ? fd.reqHi : fd.reqBn;
      const badgeF = reqF
        ? '<div class="st-req" style="display:inline-block;margin-top:7px;padding:3px 11px;border-radius:999px;font-size:11px;font-weight:700;letter-spacing:0.2px;font-family:\'Hind Siliguri\',sans-serif;background:linear-gradient(135deg,#ffe27a 0%,#ffc107 55%,#e69500 100%);color:#2a1a00;box-shadow:0 0 9px rgba(255,200,0,0.45)">' + escHtml(reqF) + '</div>'
        : '';
      const subF = _hiF ? fd.subHi : fd.subBn;
      fc.innerHTML =
        '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px">' +
          iconF +
          '<div style="flex:1;min-width:0">' +
            '<div class="st-name">' + escHtml(_hiF ? fd.hi : fd.bn) + '</div>' +
            (subF ? '<div class="st-sub">' + escHtml(subF) + '</div>' : '') +
            badgeF +
          '</div>' +
        '</div>' +
        '<div class="st-row" style="justify-content:flex-end"><button class="st-open-btn">' + (_hiF ? 'खोलें' : 'খুলুন') + '</button></div>';
      fc.addEventListener('click', () => {
        window._stRvSub = fd.folder;
        window._stRvSubTitle = { bn: fd.bn, hi: fd.hi };
        renderSt();
      });
      list.appendChild(fc);
      idx++;
      return;
    }
    if (st.__head) {
      const hd = st.__head;
      const gh = document.createElement('div');
      gh.className = 'st-section-head';
      gh.style.cssText = hd.h === 1
        ? 'margin:18px 4px 10px;padding:0 0 6px;font-size:13px;font-weight:700;letter-spacing:0;color:var(--gold,#ffd700);border-bottom:1px solid rgba(255,215,0,0.25)'
        : 'margin:14px 4px 8px;padding:0 0 0 8px;font-size:12px;font-weight:600;letter-spacing:0;color:rgba(255,215,0,0.78);border-left:2px solid rgba(255,215,0,0.35)';
      gh.textContent = (secLang('sv') === 'hi') ? hd.hi : hd.bn;
      list.appendChild(gh);
      return;
    }
    if (activeKey === 'rv' && st.fav && !_favHeadDone) {
      _favHeadDone = true;
      const fh = document.createElement('div');
      fh.className = 'st-section-head';
      fh.style.cssText = 'margin:18px 4px 10px;padding:0 0 6px;font-size:13px;font-weight:700;letter-spacing:0;color:var(--gold,#ffd700);border-bottom:1px solid rgba(255,215,0,0.25)';
      fh.textContent = _favPadLabel();
      list.appendChild(fh);
    }
    // Ashtayam Seva Paddhati: a folder-style card (no jap counter) that
    // opens the 9 section folders.
    if (st.vedFolder) {
      const tile = document.createElement('div');
      tile.className = 'st-folder-tile';
      tile.innerHTML =
        '<span class="st-folder-tile-icon">🪔</span>' +
        '<span class="st-folder-tile-title">' + escHtml(stName(st)) +
          (stSub(st) ? '<span class="asp-sub">' + escHtml(stSub(st)) + '</span>' : '') +
        '</span>' +
        '<span class="st-folder-tile-count">4</span>' +
        '<span class="st-folder-tile-arrow">›</span>';
      tile.addEventListener('click', () => {
        window._stVedOpen = true;
        window._stSevaSection = null;
        renderSt();
      });
      list.appendChild(tile);
      return;
    }
    if (st.sevaFolder) {
      const tile = document.createElement('div');
      tile.className = 'st-folder-tile';
      tile.innerHTML =
        '<span class="st-folder-tile-icon">🪔</span>' +
        '<span class="st-folder-tile-title">' + escHtml(stName(st)) +
          (stSub(st) ? '<span class="asp-sub">' + escHtml(stSub(st)) + '</span>' : '') +
        '</span>' +
        '<span class="st-folder-tile-count">9</span>' +
        '<span class="st-folder-tile-arrow">›</span>';
      tile.addEventListener('click', () => {
        window._stSevaOpen = true;
        window._stSevaSection = null;
        renderSt();
      });
      list.appendChild(tile);
      return;
    }
    const tc = 0, tot = 0; // counters removed — see _stReadBtnHtml for the daily pad tracker
    const effLyrics = getEffectiveLyrics(st.id);
    const hasLyrics = !!(effLyrics && effLyrics.trim().length > 0) || !!st.live;

    const gc = glowColors[idx % glowColors.length];
    const pulseDur = (2.8 + (idx % 5) * 0.45).toFixed(1) + 's';
    const colorDur = (9 + (idx % 4) * 1.5).toFixed(1) + 's';
    const fadeDelay = (idx * 0.055).toFixed(2) + 's';
    const colorOff = '-' + (idx * 0.7).toFixed(1) + 's';

    const c = document.createElement("div");
    c.className = "st-card";
    c.style.cssText = '--sgc:' + gc + ';--spd:' + pulseDur + ';--scd:' + colorDur + ';--sad:' + fadeDelay + ';--sod:' + colorOff + ';--sfd:' + fadeDelay + ';';

    const globalTag = st.global
      ? '<span style="font-size:9px;color:#ffd700;border:1px solid rgba(255,215,0,0.35);border-radius:4px;padding:1px 6px;margin-left:6px;vertical-align:middle;letter-spacing:0.5px">🌍 GLOBAL</span>'
      : '';

    let headerRight = '';
    if (st.custom) {
      headerRight = '<div style="display:flex;gap:5px;flex-shrink:0">' +
        '<button class="st-edit-btn" title="Upload audio" aria-label="Upload audio" onclick="stPickAudio(\'' + st.id + '\')">' + (window._stAudioUrls[st.id] ? '🎵✓' : '🎵') + '</button>' +
        (window._stAudioUrls[st.id] ? '<button class="st-edit-btn" title="Remove audio" aria-label="Remove audio" onclick="stRemoveAudio(\'' + st.id + '\')">🔇</button>' : '') +
        '<button class="st-edit-btn" onclick="toggleStEdit(\'' + st.id + '\')">✏</button>' +
        '<button class="st-edit-btn" style="border-color:rgba(255,80,80,0.35);color:#ff8888;background:rgba(255,80,80,0.08)" onclick="delSt(\'' + st.id + '\')">✕</button>' +
        '</div>';
    }

    const _stHi = secLang('sv') === 'hi';
    // No pāṭh counter / +− buttons in any stotram folder — just Open (+ a daily ✅ on badged items).
    const _noCount = true;
    const _reqTxt = _stHi ? st.reqHi : st.reqBn;
    const _reqBadge = _reqTxt
      ? '<div class="st-req" style="display:inline-block;margin-top:7px;padding:3px 11px;border-radius:999px;font-size:11px;font-weight:700;letter-spacing:0.2px;font-family:\'Hind Siliguri\',sans-serif;background:linear-gradient(135deg,#ffe27a 0%,#ffc107 55%,#e69500 100%);color:#2a1a00;box-shadow:0 0 9px rgba(255,200,0,0.45)">' + escHtml(_reqTxt) + '</div>'
      : '';
    let inner =
      '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px">' +
        (RV_POET_ICON[st.id] ? '<img src="' + RV_POET_IMG[RV_POET_ICON[st.id]] + '" alt="" draggable="false" style="width:42px;height:42px;border-radius:50%;object-fit:cover;flex-shrink:0;border:1px solid rgba(255,215,0,0.55);box-shadow:0 0 8px rgba(255,215,0,0.25)">' : '') +
        '<div style="flex:1;min-width:0">' +
          '<div class="st-name">' + escHtml(stName(st)) + globalTag + '</div>' +
          (stSub(st) ? '<div class="st-sub">' + escHtml(stSub(st)) + '</div>' : '') +
          _reqBadge +
        '</div>' +
        headerRight +
      '</div>' +
      (_noCount
        ? '<div class="st-row" style="justify-content:' + (_reqTxt ? 'space-between' : 'flex-end') + '">' + (RV_PAD_REQ[st.id] ? _stReadBtnHtml(st.id, _stHi) : '') + (hasLyrics ? '<button class="st-open-btn" onclick="showLyrics(\'' + st.id + '\')">' + (_stHi ? 'खोलें' : 'খুলুন') + '</button>' : '') + '</div>'
        : (
      '<div class="st-row">' +
        '<div>' +
          '<div class="st-count" id="sc' + st.id + '">' + tc + '</div>' +
          '<div class="st-meta">' + (_stHi ? 'आज · कुल: ' : 'আজ · মোট: ') + '<strong>' + tot + '</strong></div>' +
        '</div>' +
        '<div class="st-btns">' +
          '<div class="st-pm">' +
            '<div class="st-pm-lab">' + (_stHi ? 'पाठ गणना' : 'পাঠ গণনা') + '</div>' +
            '<div class="st-pm-row">' +
              '<div class="st-pm-col"><button class="st-btn st-mini" title="' + (_stHi ? 'एक पाठ घटाएँ' : 'একটি পাঠ কমান') + '" aria-label="' + (_stHi ? 'एक पाठ घटाएँ' : 'একটি পাঠ কমান') + '" onclick="adjSt(\'' + st.id + '\',-1)">\u2212</button><span class="st-pm-cap">' + (_stHi ? 'घटाएँ' : 'কমান') + '</span></div>' +
              '<div class="st-pm-col"><button class="st-btn st-mini" title="' + (_stHi ? 'एक पाठ जोड़ें' : 'একটি পাঠ যোগ করুন') + '" aria-label="' + (_stHi ? 'एक पाठ जोड़ें' : 'একটি পাঠ যোগ করুন') + '" onclick="adjSt(\'' + st.id + '\',1)">+</button><span class="st-pm-cap">' + (_stHi ? 'जोड़ें' : 'যোগ') + '</span></div>' +
            '</div>' +
          '</div>' +
          (hasLyrics ? '<button class="st-open-btn" onclick="showLyrics(\'' + st.id + '\')">' + (_stHi ? 'खोलें' : 'খুলুন') + '</button>' : '') +
        '</div>' +
      '</div>'
        ));

    if (st.custom) {
      inner +=
        '<div id="slePanel-' + st.id + '" style="display:none;margin-top:12px">' +
        '<div style="font-size:11px;color:rgba(74,144,226,0.8);margin-bottom:6px;letter-spacing:1px">✏ Edit Lyrics</div>' +
        '<textarea id="sle-' + st.id + '" rows="8" style="width:100%;background:rgba(0,0,0,0.40);border:1px solid rgba(74,144,226,0.25);border-radius:10px;padding:10px 12px;color:var(--tl);font-size:14px;font-family:Hind Siliguri,serif;resize:vertical;line-height:1.8;box-sizing:border-box" placeholder="Paste full lyrics here…"></textarea>' +
        '<button onclick="editStLyrics(\'' + st.id + '\')" style="margin-top:8px;padding:9px 20px;border-radius:10px;border:none;background:rgba(255,215,0,0.12);color:#ffd700;font-size:13px;font-weight:600;cursor:pointer;font-family:Inter,sans-serif;border:1px solid rgba(255,215,0,0.30)">💾 Save Lyrics</button>' +
        '</div>';
    }

    c.innerHTML = inner;

    // Pop animation on count change
    c.querySelectorAll('.st-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const cntEl = c.querySelector('.st-count');
        if (cntEl) { cntEl.classList.remove('pop'); void cntEl.offsetWidth; cntEl.classList.add('pop'); }
      });
    });

    list.appendChild(c);
    idx++;
  });

  // Radha Vallabh: "Favourite Stotra, Pads" folder tile below the 8 granths.
  if (false) {
    const _favN = STLIST.filter((x) => x.cat === 'rv' && x.fav).length;
    const favTile = document.createElement('div');
    favTile.className = 'st-folder-tile';
    favTile.innerHTML =
      '<span class="st-folder-tile-icon">⭐</span>' +
      '<span class="st-folder-tile-title">' + escHtml(_favPadLabel()) + '</span>' +
      '<span class="st-folder-tile-count">' + _favN + '</span>' +
      '<span class="st-folder-tile-arrow">›</span>';
    favTile.addEventListener('click', () => { window._stRvFavOpen = true; renderSt(); });
    list.appendChild(favTile);
  }
}

// ─────────────────────────────────────────────────────────
// ASHTAYAM SEVA PADDHATI (Radha Vallabh Sampraday › first item, before
// Sri Hit Chaurasi Ji). 9 sections, one folder each:
//   ./ashtayam_seva_hi.html   (Hindi, all 9 sections)
//   ./ashtayam_seva_bn.html   (Bangla, all 9 sections)
// The language follows Settings (App.S.stotramLang: "hi" | "bn"), same as
// the rest of the Stotram section; switching it re-renders via renderSt().
// Each file is a set of <section data-n="N"> HTML fragments (h2/h3/p +
// .video-link blocks), fetched on demand and cached in memory. Each .video-link becomes an inline audio player.
// ─────────────────────────────────────────────────────────
const SEVA_SECTIONS = [
  { n: 1, hi: 'भूमिका',                        bn: 'ভূমিকা' },
  { n: 2, hi: 'मंगला सेवा',                    bn: 'মঙ্গলা সেবা' },
  { n: 3, hi: 'प्रातःकालीन वन विहार सेवा',     bn: 'প্রাতঃকালীন বনবিহার সেবা' },
  { n: 4, hi: 'श्रृंगार सेवा',                  bn: 'শৃঙ্গার সেবা' },
  { n: 5, hi: 'राजभोग सेवा',                   bn: 'রাজভোগ সেবা' },
  { n: 6, hi: 'उत्थापन सेवा',                  bn: 'উত্থাপন সেবা' },
  { n: 7, hi: 'संध्या भोग एवं आरती सेवा',      bn: 'সন্ধ্যা ভোগ ও আরতি সেবা' },
  { n: 8, hi: 'संध्या पश्चात् रास के पद',       bn: 'সন্ধ্যার পর রাসের পদ' },
  { n: 9, hi: 'शयन सेवा',                      bn: 'শয়ন সেবা' },
];
const _sevaCache = {};      // "<lang><n>" -> section html
const _sevaFilePromise = {}; // lang -> in-flight/finished fetch of the whole file

function _sevaNum(n, hi) {
  const d = hi ? '०१२३४५६७८९' : '০১২৩৪৫৬৭৮৯';
  return String(n).split('').map((c) => d[+c]).join('');
}

// One file per language (./ashtayam_seva_hi.html / ./ashtayam_seva_bn.html),
// holding all 9 sections as <section data-n="1..9"> blocks. Fetched once,
// split, and cached per section.
function loadSevaSection(n, lang) {
  const key = lang + n;
  if (_sevaCache[key]) return Promise.resolve(_sevaCache[key]);
  if (!_sevaFilePromise[lang]) {
    _sevaFilePromise[lang] = fetch('./ashtayam_seva_' + lang + '.html')
      .then((r) => {
        if (!r.ok) throw new Error('Seva file request failed: ' + r.status);
        return r.text();
      })
      .then((txt) => {
        const re = /<section data-n="(\d)">([\s\S]*?)<\/section>/g;
        let m, count = 0;
        while ((m = re.exec(txt))) {
          _sevaCache[lang + m[1]] = m[2].trim();
          count++;
        }
        if (!count) throw new Error('Seva file has no sections');
      })
      .catch((e) => { delete _sevaFilePromise[lang]; throw e; });
  }
  return _sevaFilePromise[lang].then(() => {
    if (!_sevaCache[key]) throw new Error('Seva section missing: ' + key);
    return _sevaCache[key];
  });
}

const VED_BN_HTML = "<p>প্রতিটি সাধকের জন্য শ্রী হিত হরিবংশ মহাপ্রভু রচিত এই ৪টি সিদ্ধান্ত পদ প্রতিদিন পাঠ করা একান্ত আবশ্যক।</p><h3>রসিকদের চার বেদ</h3><p>রসিক সন্তরা এই ৪টি পদকে কেবল সাধারণ পদ বা কবিতা হিসেবে দেখেন না; তাঁরা একে রসিক সাধকদের \"চার বেদ\" বলে গণ্য করেন।</p><h3>প্রকৃত শরণাগত হওয়ার শর্ত</h3><p>যে সাধক এই চার বেদের উপদেশ নিজের মনে ধারণ করেন এবং এই ৪টি পদের ভাব অনুযায়ী নিজের জীবন পরিচালনা করেন, তিনিই পরম পূজ্য হিত জী মহারাজের প্রকৃত শরণাগত (আশ্রয়প্রাপ্ত) ভক্ত।</p><h2>শ্রী হিত হরিবংশ মহাপ্রভু রচিত ৪টি সিদ্ধান্ত</h2><h3>১. প্রথম পদ</h3><p class=\"ved-lab\">বাংলা প্রতিবর্ণায়ন:</p><p class=\"verse\"><span class=\"vl\">রসনা কটো জো অনরঠো, নিরখি অন ফুটো নৈন।</span><span class=\"vl\">শ্রবণ ফুটো জো অন শুনো, বিনু রাধা-জসু বৈন॥</span></p><p class=\"ved-lab\">বাংলা অনুবাদ:</p><p>আমার জিহ্বা কেটে যাক যদি তা শ্রীরাধার নাম ব্যতিরেকে অন্য কিছু উচ্চারণ করে; আমার চোখ অন্ধ হয়ে যাক যদি তা শ্রীরাধার রূপ ছাড়া অন্য কিছু দর্শন করে; এবং আমার কান বধির হয়ে যাক যদি তা শ্রীরাধার নাম ও যশোগাথা ছাড়া অন্য কোনো কথা শ্রবণ করে।</p><audio class=\"ved-audio\" controls preload=\"none\" controlsList=\"nodownload\" src=\"./4veda/4veda_1.mp3\"></audio><h3>২. দ্বিতীয় পদ</h3><p class=\"ved-lab\">বাংলা প্রতিবর্ণায়ন:</p><p class=\"verse\"><span class=\"vl\">সবসো হিত নিষ্কাম মতি, শ্রী বৃন্দাবন বিশ্রাম।</span><span class=\"vl\">শ্রী রাধাবল্লভ লাল কো, হৃদয় ধ্যান মুখ নাম॥</span></p><p class=\"ved-lab\">বাংলা অনুবাদ:</p><p>সবার প্রতি নিষ্কাম ও হিতৈষী মনোভাব রাখা, শ্রী বৃন্দাবনে আশ্রয় গ্রহণ করা, হৃদয়ে শ্রী রাধাবল্লভ জীর রূপ ধ্যান করা এবং সর্বদা মুখে তাঁর পবিত্র নাম জপ করাই জীবনের পরম সাধন।</p><audio class=\"ved-audio\" controls preload=\"none\" controlsList=\"nodownload\" src=\"./4veda/4veda_2.mp3\"></audio><h3>৩. তৃতীয় পদ</h3><p class=\"ved-lab\">বাংলা প্রতিবর্ণায়ন:</p><p class=\"verse\"><span class=\"vl\">তান হি রাখ সৎসঙ্গ মেঁ, মনহ প্রেম রস ভেভ।</span><span class=\"vl\">সুখ চাহত হরিবংশ হিত, কৃষ্ণ কল্পতরু সেভ॥</span></p><p class=\"ved-lab\">বাংলা অনুবাদ:</p><p>শরীরকে সর্বদা সাধু ও ভক্তদের সৎসঙ্গে যুক্ত রাখুন এবং মনকে রাধা-কৃষ্ণের প্রেমরসে নিমগ্ন রাখুন। শ্রী হরিবংশ মহাপ্রভু বলছেন—যদি প্রকৃত সুখ লাভ করতে চান, তবে কল্পতরু স্বরূপ শ্রীকৃষ্ণের সেবা ও ভজনায় নিজেকে নিয়োজিত করুন।</p><audio class=\"ved-audio\" controls preload=\"none\" controlsList=\"nodownload\" src=\"./4veda/4veda_3.mp3\"></audio><h3>৪. চতুর্থ পদ</h3><p class=\"ved-lab\">বাংলা প্রতিবর্ণায়ন:</p><p class=\"verse\"><span class=\"vl\">নিকস কুঞ্জ ঠাঢ়ে ভয়, ভূজা পরস্পর অংস।</span><span class=\"vl\">শ্রী রাধাবল্লভ মুখ কমল, নিরখ নৈন হরিবংশ॥</span></p><p class=\"ved-lab\">বাংলা অনুবাদ:</p><p>শ্রী রাধা ও শ্রী কৃষ্ণ কুঞ্জ থেকে নিষ্ক্রান্ত হয়ে একে অপরের কাঁধে বাহু রেখে দাঁড়িয়ে আছেন। শ্রী হরিবংশ মহাপ্রভু অত্যন্ত আনন্দের সাথে তাঁদের শ্রীমুখ-কমলের অলৌকিক রূপ দর্শন করছেন।</p><p>সম্পূর্ণ পদগুলির কাব্যিক ভাবার্থ বুঝতে আপনি শ্রী হিত হরিবংশ স্ফুট বাণী বা ব্রজরস সাহিত্য অনুসন্ধান করতে পারেন।</p><audio class=\"ved-audio\" controls preload=\"none\" controlsList=\"nodownload\" src=\"./4veda/4veda_4.mp3\"></audio><h3>চিন্তন, মনন এবং জীবনযাত্রায় প্রতিফলন</h3><p>কেবল মুখে পাঠ করাই যথেষ্ট নয়—বক্তার নির্দেশ হলো:</p><p><strong>চিন্তন ও মনন:</strong> পদগুলির অন্তর্নিহিত ভাব প্রতিনিয়ত মনে গভীরভাবে উপলব্ধি ও চিন্তা করতে হবে।</p><p><strong>জীবনশৈলী:</strong> পদগুলির শিক্ষা ও ভাবধারাকে নিজের দৈনন্দিন জীবনযাত্রা, মানসিকতা ও আচরণের মধ্যে সম্পূর্ণরূপে প্রয়োগ করতে হবে।</p>";
const VED_HI_HTML = "<p>प्रत्येक साधक के लिए श्री हित हरिवंश महाप्रभु द्वारा रचित इन ४ सिद्धांत पदों का प्रतिदिन पाठ करना अत्यंत आवश्यक है।</p><h3>रसिकों के चार वेद</h3><p>रसिक संत इन ४ पदों को केवल साधारण पद या कविता के रूप में नहीं देखते; वे इन्हें रसिक साधकों के \"चार वेद\" मानते हैं।</p><h3>सच्चा शरणागत होने की शर्त</h3><p>जो साधक इन चार वेदों के उपदेश को अपने मन में धारण करता है और इन ४ पदों के भाव के अनुसार अपना जीवन व्यतीत करता है, वही परम पूज्य हित जी महाराज का सच्चा शरणागत (आश्रित) भक्त है।</p><h2>श्री हित हरिवंश महाप्रभु द्वारा रचित ४ सिद्धांत पद</h2><h3>१. पहला पद</h3><p class=\"ved-lab\">मूल पद (देवनागरी):</p><p class=\"verse\"><span class=\"vl\">रसना कटो जो अनरठो, निरखि अन फुटो नैन।</span><span class=\"vl\">श्रवण फुटो जो अन सुनो, बिनु राधा-जसु बैन॥</span></p><p class=\"ved-lab\">हिंदी अर्थ:</p><p>मेरी जीभ कट जाए यदि वह श्रीराधा के नाम के अलावा कुछ और बोले; मेरी आँखें फूट जाएँ (अंधी हो जाएँ) यदि वे श्रीराधा के रूप के अलावा कुछ और देखें; और मेरे कान बहरे हो जाएँ यदि वे श्रीराधा के नाम और यश के अलावा कोई अन्य बात सुनें।</p><audio class=\"ved-audio\" controls preload=\"none\" controlsList=\"nodownload\" src=\"./4veda/4veda_1.mp3\"></audio><h3>२. दूसरा पद</h3><p class=\"ved-lab\">मूल पद (देवनागरी):</p><p class=\"verse\"><span class=\"vl\">सबसो हित निष्काम मति, श्री वृंदावन विश्राम।</span><span class=\"vl\">श्री राधावल्लभ लाल को, हृदय ध्यान मुख नाम॥</span></p><p class=\"ved-lab\">हिंदी अर्थ:</p><p>सभी के प्रति निष्काम और हितैषी भाव रखना, श्री वृंदावन धाम में विश्राम (आश्रय) लेना, हृदय में श्री राधावल्लभ लाल जी के रूप का ध्यान करना और मुख से निरंतर उनके पवित्र नाम का जप करना ही जीवन का परम साधन है।</p><audio class=\"ved-audio\" controls preload=\"none\" controlsList=\"nodownload\" src=\"./4veda/4veda_2.mp3\"></audio><h3>३. तीसरा पद</h3><p class=\"ved-lab\">मूल पद (देवनागरी):</p><p class=\"verse\"><span class=\"vl\">तन ही राख सत्संग में, मनह प्रेम रस भेव।</span><span class=\"vl\">सुख चाहत हरिवंश हित, कृष्ण कल्पतरु सेव॥</span></p><p class=\"ved-lab\">हिंदी अर्थ:</p><p>शरीर को सदैव संतों और भक्तों के सत्संग में रखें और मन को राधा-कृष्ण के प्रेमरस में डुबोकर रखें। श्री हरिवंश महाप्रभु कहते हैं—यदि आप सच्चा सुख चाहते हैं, तो कल्पवृक्ष स्वरूप श्रीकृष्ण की सेवा और भक्ति में स्वयं को समर्पित करें।</p><audio class=\"ved-audio\" controls preload=\"none\" controlsList=\"nodownload\" src=\"./4veda/4veda_3.mp3\"></audio><h3>४. चौथा पद</h3><p class=\"ved-lab\">मूल पद (देवनागरी):</p><p class=\"verse\"><span class=\"vl\">निकस कुंज ठाड़े भय, भुजा परस्पर अंश।</span><span class=\"vl\">श्री राधावल्लभ मुख कमल, निरख नैन हरिवंश॥</span></p><p class=\"ved-lab\">हिंदी अर्थ:</p><p>श्री राधा और श्री कृष्ण कुंज से बाहर निकलकर एक-दूसरे के कंधे पर हाथ रखकर खड़े हैं। श्री हरिवंश महाप्रभु अत्यंत आनंद के साथ अपनी आँखों से उनके श्रीमुख-कमल के दिव्य रूप का दर्शन कर रहे हैं।</p><p>इन पदों के संपूर्ण काव्यात्मक भावार्थ को गहराई से समझने के लिए आप श्री हित हरिवंश स्फुट वाणी या ब्रजरस साहित्य का अध्ययन कर सकते हैं।</p><audio class=\"ved-audio\" controls preload=\"none\" controlsList=\"nodownload\" src=\"./4veda/4veda_4.mp3\"></audio><h3>चिंतन, मनन और जीवन शैली में उतारना</h3><p>केवल मुख से पाठ कर लेना ही पर्याप्त नहीं है—वक्ता का निर्देश है:</p><p><strong>चिंतन और मनन:</strong> इन पदों के गूढ़ भाव को निरंतर मन में गहराई से महसूस करना और उस पर विचार करना चाहिए।</p><p><strong>जीवन शैली:</strong> इन पदों की शिक्षाओं और भावधारा को अपनी दैनिक दिनचर्या, मानसिकता और व्यवहार में पूरी तरह से लागू करना चाहिए।</p>";
// ─────────────────────────────────────────────────────────
// 4 VEDA for Radha Vallabhi / Harivanshi (Radha Vallabh Sampraday, above
// Ashtayam Seva). A reading page: text
// (Bangla or Hindi per Settings) plus 4 audio clips at ./4veda/4veda_1..4.mp3.
// ─────────────────────────────────────────────────────────
function renderVed4(list) {
  const hi = secLang('sv') === 'hi';
  const ved = STLIST.find((s) => s.id === 'ved4');
  const vedName = ved ? stName(ved) : '৪ বেদ';
  const rvTitle = hi ? 'राधावल्लभ सम्प्रदाय' : 'রাধা বল্লভ সম্প্রদায়';
  const scrollTop = () => {
    try { list.scrollIntoView({ block: 'start' }); } catch (_e) {}
  };
  const mkBack = (label, title, onBack) => {
    const row = document.createElement('div');
    row.className = 'st-back-row';
    row.innerHTML =
      '<button class="st-back-btn">← ' + escHtml(label) + '</button>' +
      '<span class="st-back-title">' + escHtml(title) + '</span>';
    row.querySelector('.st-back-btn').addEventListener('click', onBack);
    return row;
  };

  list.appendChild(mkBack(rvTitle, vedName, () => {
    window._stVedOpen = false;
    renderSt();
    scrollTop();
  }));
  const body = document.createElement('div');
  body.className = 'asp-reader ' + (hi ? 'asp-hi' : 'asp-bn') + ' ved-reader';
  body.innerHTML = hi ? VED_HI_HTML : VED_BN_HTML;
  list.appendChild(body);
  if (typeof closeSevaAudioPlayer === 'function') { try { closeSevaAudioPlayer(); } catch (_e) {} }
  const audios = Array.from(body.querySelectorAll('audio.ved-audio'));
  audios.forEach((a) => a.addEventListener('play', () => audios.forEach((o) => { if (o !== a) o.pause(); })));
  // Autoplay: start pad 1 on open, then roll on to the next pad when one ends.
  audios.forEach((a, i) => a.addEventListener('ended', () => { const nx = audios[i + 1]; if (nx) { nx.currentTime = 0; nx.play().catch(() => {}); } }));
  if (audios[0]) { const p = audios[0].play(); if (p && p.catch) p.catch(() => {}); }
  // Stop playback when the person leaves this page (a detached <audio> keeps playing otherwise).
  const t = setInterval(() => {
    if (!body.isConnected) { audios.forEach((a) => { try { a.pause(); } catch (_e) {} }); clearInterval(t); }
  }, 500);
}

function renderSevaPaddhati(list) {
  const hi = secLang('sv') === 'hi';
  const lang = hi ? 'hi' : 'bn';
  const asp = STLIST.find((s) => s.id === 'asp');
  const sevaName = asp ? stName(asp) : (hi ? 'अष्टयाम सेवा पद्धति' : 'অষ্টযাম সেবা পদ্ধতি');
  const rvTitle = hi ? 'राधावल्लभ सम्प्रदाय' : 'রাধা বল্লভ সম্প্রদায়';
  const secN = window._stSevaSection || null;
  const sec = secN ? SEVA_SECTIONS.find((x) => x.n === secN) : null;

  const scrollTop = () => {
    try { list.scrollIntoView({ block: 'start' }); } catch (_e) {}
  };
  const mkBack = (label, title, onBack) => {
    const row = document.createElement('div');
    row.className = 'st-back-row';
    row.innerHTML =
      '<button class="st-back-btn">← ' + escHtml(label) + '</button>' +
      '<span class="st-back-title">' + escHtml(title) + '</span>';
    row.querySelector('.st-back-btn').addEventListener('click', onBack);
    return row;
  };

  // ── Level 3: the 9 section folders ──
  if (!sec) {
    list.appendChild(mkBack(rvTitle, sevaName, () => {
      window._stSevaOpen = false; window._stVedOpen = false;
      window._stSevaSection = null;
      renderSt();
      scrollTop();
    }));
    SEVA_SECTIONS.forEach((x) => {
      const tile = document.createElement('div');
      tile.className = 'st-folder-tile';
      tile.innerHTML =
        '<span class="asp-num">' + _sevaNum(x.n, hi) + '</span>' +
        '<span class="asp-tile-main">' +
          '<span class="st-folder-tile-title">' + escHtml(hi ? x.hi : x.bn) + '</span>' +
          (x.n >= 2 ? '<span class="asp-timer" data-n="' + x.n + '"></span>' : '') +
        '</span>' +
        '<span class="st-folder-tile-arrow">›</span>';
      tile.addEventListener('click', () => {
        window._stSevaSection = x.n;
        renderSt();
        scrollTop();
      });
      list.appendChild(tile);
    });
    // Live per-seva timers (starts at / starts in / time left) from GPS sun times.
    _sevaStartTimers(list, list.querySelector('.st-folder-tile'));
    return;
  }

  // ── Level 4: one section, in the Settings language ──
  list.appendChild(mkBack(hi ? 'अनुभाग सूची' : 'বিভাগ তালিকা', hi ? sec.hi : sec.bn, () => {
    window._stSevaSection = null;
    renderSt();
    scrollTop();
  }));

  const body = document.createElement('div');
  body.className = 'asp-reader ' + (hi ? 'asp-hi' : 'asp-bn');
  body.innerHTML = '<div class="asp-loading">' + (hi ? 'लोड हो रहा है… 🙏' : 'লোড হচ্ছে… 🙏') + '</div>';
  // Pads with a YouTube link get a permanent inline audio player under the
  // verse (see initSevaInlinePlayers). Any other link opens externally.
  body.addEventListener('click', (e) => {
    const a = e.target && e.target.closest ? e.target.closest('a[href]') : null;
    if (!a) return;
    e.preventDefault();
    openExternalLink(a.href);
  });
  list.appendChild(body);

  const nav = document.createElement('div');
  nav.className = 'asp-nav';
  const goTo = (n) => {
    window._stSevaSection = n;
    renderSt();
    scrollTop();
  };
  if (sec.n > 1) {
    const prev = SEVA_SECTIONS[sec.n - 2];
    const b = document.createElement('button');
    b.className = 'st-back-btn';
    b.textContent = '← ' + (hi ? prev.hi : prev.bn);
    b.addEventListener('click', () => goTo(prev.n));
    nav.appendChild(b);
  }
  if (sec.n < SEVA_SECTIONS.length) {
    const next = SEVA_SECTIONS[sec.n];
    const b = document.createElement('button');
    b.className = 'st-back-btn';
    b.textContent = (hi ? next.hi : next.bn) + ' →';
    b.addEventListener('click', () => goTo(next.n));
    nav.appendChild(b);
  }
  if (nav.childNodes.length) list.appendChild(nav);

  loadSevaSection(sec.n, lang)
    .then((html) => {
      // Ignore a late response if the person navigated / switched language.
      if (!body.isConnected || window._stSevaSection !== sec.n || (secLang('sv') === 'hi' ? 'hi' : 'bn') !== lang) return;
      body.innerHTML = html;
      initSevaInlinePlayers(body);
    })
    .catch(() => {
      if (!body.isConnected) return;
      body.innerHTML = '<div class="asp-loading">' + (hi ? 'पाठ लोड नहीं हो पाया 🙏' : 'পাঠ লোড করা যায়নি 🙏') + '</div>';
    });
}

// ─────────────────────────────────────────────────────────
// ASHTAYAM SEVA TIMERS & REMINDERS
// Each of the 8 sevas (section folders 2–9; 1 = introduction, no timer) starts
// at a time worked out from the SUNRISE / SUNSET of the person's saved GPS
// location (calcSunTimes — same engine as the Brahma Muhurta / Sandhya Kal
// cards) and runs until the next seva begins, so exactly one seva is "active"
// at any moment. Offsets are hours from sunrise (sr) or sunset (ss) and follow
// the timetable of bhajanmarg.com/ashtayam-seva-paddhati for a 6:00 / 18:00
// sun (Mangala ~5, Vana Vihar ~6:30, Shringar ~8, Rajbhog ~11, Utthapan ~3:30 pm,
// Sandhya bhog & aarti ~6, Sandhya Raas ~7, Shayan ~8:30). Edit here to tune.
// ─────────────────────────────────────────────────────────
const SEVA_SCHEDULE = [
  { n: 2, a: 'sr', off: -1.0 },   // Mangala
  { n: 3, a: 'sr', off:  0.5 },   // Vana Vihar
  { n: 4, a: 'sr', off:  2.0 },   // Shringar
  { n: 5, a: 'sr', off:  5.0 },   // Rajbhog
  { n: 6, a: 'sr', off:  9.5 },   // Utthapan
  { n: 7, a: 'ss', off: -0.4 },   // Sandhya bhog & aarti (starts with Sandhya Kal)
  { n: 8, a: 'ss', off:  1.0 },   // Sandhya Raas pads
  { n: 9, a: 'ss', off:  2.5 },   // Shayan (till next Mangala)
];
const SEVA_EN = {
  2: 'Mangala Seva', 3: 'Vana Vihar Seva', 4: 'Shringar Seva', 5: 'Rajbhog Seva',
  6: 'Utthapan Seva', 7: 'Sandhya Bhog & Aarti', 8: 'Sandhya Raas Pad', 9: 'Shayan Seva',
};

// Saved GPS coordinates (same sources the rest of the app uses). Falls back to
// the app's default point when GPS has never been switched on.
function _sevaCoords() {
  let lat = App.S && App.S.lastLat, lng = App.S && App.S.lastLng;
  if (lat == null || lng == null) {
    try { lat = parseFloat(localStorage.getItem('rjap_lastLat')); lng = parseFloat(localStorage.getItem('rjap_lastLng')); } catch (_e) {}
  }
  if (typeof lat !== 'number' || typeof lng !== 'number' || !isFinite(lat) || !isFinite(lng)) {
    return { lat: 23.8103, lng: 90.4125, gps: false };
  }
  return { lat: lat, lng: lng, gps: true };
}

// Every seva start from yesterday to +3 days, sorted by time.
function _sevaTimeline(now) {
  const c = _sevaCoords();
  const list = [];
  for (let d = -1; d <= 3; d++) {
    const base = new Date(now.getFullYear(), now.getMonth(), now.getDate() + d, 0, 0, 0, 0);
    const noon = new Date(base.getFullYear(), base.getMonth(), base.getDate(), 12, 0, 0, 0);
    let t = null;
    try { t = calcSunTimes(c.lat, c.lng, noon); } catch (_e) {}
    const sr = t ? t.sunriseH : 6, ss = t ? t.sunsetH : 18;
    SEVA_SCHEDULE.forEach((s) => {
      list.push({ n: s.n, t: base.getTime() + ((s.a === 'sr' ? sr : ss) + s.off) * 3600000 });
    });
  }
  list.sort((a, b) => a.t - b.t);
  return { list: list, gps: c.gps };
}

// { map: { n: {active, start, end?} }, gps }
function _sevaState(now) {
  const tl = _sevaTimeline(now);
  const ms = now.getTime();
  let i = -1;
  for (let k = 0; k < tl.list.length; k++) { if (tl.list[k].t <= ms) i = k; else break; }
  const map = {};
  if (i >= 0 && i + 1 < tl.list.length) map[tl.list[i].n] = { active: true, start: tl.list[i].t, end: tl.list[i + 1].t };
  for (let k = i + 1; k < tl.list.length; k++) {
    if (!map[tl.list[k].n]) map[tl.list[k].n] = { active: false, start: tl.list[k].t };
  }
  return { map: map, gps: tl.gps };
}

function _sevaClock(ms) {
  const d = new Date(ms);
  const h = d.getHours(), m = d.getMinutes();
  return String(h % 12 || 12).padStart(2, '0') + ':' + String(m).padStart(2, '0') + ' ' + (h >= 12 ? 'PM' : 'AM');
}
function _sevaHMS(ms) {
  const s = Math.max(0, Math.floor(ms / 1000));
  return String(Math.floor(s / 3600)).padStart(2, '0') + ':' +
    String(Math.floor((s % 3600) / 60)).padStart(2, '0') + ':' + String(s % 60).padStart(2, '0');
}

const _SEVA_TXT = {
  hi: { at: 'शुरू', since: 'शुरू हुई', inn: 'शुरू होने में', live: 'चल रही है', left: 'शेष समय', tomorrow: 'कल',
        gps: 'GPS बंद है — अनुमानित समय। सटीक समय के लिए सेटिंग्स में GPS लोकेशन चालू करें 📍' },
  bn: { at: 'শুরু', since: 'শুরু হয়েছে', inn: 'শুরু হতে বাকি', live: 'চলছে', left: 'বাকি সময়', tomorrow: 'আগামীকাল',
        gps: 'GPS বন্ধ — আনুমানিক সময়। সঠিক সময়ের জন্য সেটিংসে GPS লোকেশন চালু করুন 📍' },
};

function _sevaTick(list) {
  const T = _SEVA_TXT[secLang('sv') === 'hi' ? 'hi' : 'bn'];
  const now = new Date();
  const st = _sevaState(now);
  const today = now.toDateString();
  list.querySelectorAll('.asp-timer[data-n]').forEach((el) => {
    const s = st.map[+el.getAttribute('data-n')];
    const tile = el.closest('.st-folder-tile');
    if (!s) { el.innerHTML = ''; return; }
    const day = new Date(s.start).toDateString() === today ? '' : ' (' + T.tomorrow + ')';
    if (s.active) {
      el.innerHTML =
        '<span class="asp-tm-line">' + T.since + ': ' + _sevaClock(s.start) + '</span>' +
        '<span class="asp-tm-line asp-tm-live">● ' + T.live + ' · ' + T.left + ': <b>' + _sevaHMS(s.end - now.getTime()) + '</b></span>';
    } else {
      el.innerHTML =
        '<span class="asp-tm-line">' + T.at + ': ' + _sevaClock(s.start) + day + '</span>' +
        '<span class="asp-tm-line">' + T.inn + ': <b>' + _sevaHMS(s.start - now.getTime()) + '</b></span>';
    }
    if (tile) tile.classList.toggle('asp-tile-live', !!s.active);
  });
}

function _sevaStartTimers(list, noteBefore) {
  if (window._sevaTimerT) { clearInterval(window._sevaTimerT); window._sevaTimerT = null; }
  const T = _SEVA_TXT[secLang('sv') === 'hi' ? 'hi' : 'bn'];
  if (noteBefore && !_sevaCoords().gps) {
    const note = document.createElement('div');
    note.className = 'asp-gps-note';
    note.textContent = T.gps;
    list.insertBefore(note, noteBefore);
  }
  _sevaTick(list);
  window._sevaTimerT = setInterval(() => {
    if (!list.isConnected) { clearInterval(window._sevaTimerT); window._sevaTimerT = null; return; }
    _sevaTick(list);
  }, 1000);
}

// ── Reminders: one toggle per seva (Settings → Daily Reminder). Notifies 5 min
// before the seva starts, for the next 3 days, from the GPS-based times above.
// Re-armed on app open and every time updateSunInfo() runs. ──
function _sevaRemId(n, d) { return 9100 + n * 10 + d; }   // 9120 … 9192
function _sevaRemOn(n) { try { return localStorage.getItem('rjap_seva_rem_' + n) === '1'; } catch (_e) { return false; } }

async function lcArmSevaReminder(n) {
  if (typeof calcSunTimes !== 'function') return;
  const nowMs = Date.now();
  const ups = _sevaTimeline(new Date()).list.filter((e) => e.n === n && e.t - 5 * 60000 > nowMs).slice(0, 3);
  const hi = App.S && secLang('sv') === 'hi';
  const sec = SEVA_SECTIONS.find((x) => x.n === n);
  for (let d = 0; d < 3; d++) {
    const e = ups[d];
    if (!e) { _lcCancelOneShot(_sevaRemId(n, d)); continue; }
    await _lcScheduleOneShot(
      _sevaRemId(n, d),
      new Date(e.t - 5 * 60000),
      '🕉️ ' + SEVA_EN[n] + ' in 5 minutes',
      (sec ? (hi ? sec.hi : sec.bn) + ' — ' : '') +
        (hi ? 'श्री प्रिया-प्रियतम की सेवा का समय होने वाला है 🙏' : 'শ্রী প্রিয়া-প্রিয়তমের সেবার সময় হতে চলেছে 🙏'),
    );
  }
}
function lcCancelSevaReminder(n) { for (let d = 0; d < 3; d++) _lcCancelOneShot(_sevaRemId(n, d)); }
function lcArmAllSevaReminders() {
  SEVA_SCHEDULE.forEach((s) => { if (_sevaRemOn(s.n)) lcArmSevaReminder(s.n).catch(() => {}); });
}

function tgSevaReminder(n) {
  const tg = document.getElementById('tgSevaRem' + n);
  const isOn = tg && tg.classList.contains('on');
  if (!isOn) {
    lcRequestNotifPermission().then((granted) => {
      if (!granted) { toast('⚠️ Notification permission denied'); return; }
      lcArmSevaReminder(n).then(() => {
        try { localStorage.setItem('rjap_seva_rem_' + n, '1'); } catch (_e) {}
        if (tg) tg.classList.add('on');
        toast('🕉️ ' + SEVA_EN[n] + ' reminder enabled');
      });
    });
  } else {
    lcCancelSevaReminder(n);
    try { localStorage.removeItem('rjap_seva_rem_' + n); } catch (_e) {}
    if (tg) tg.classList.remove('on');
    toast('🔕 ' + SEVA_EN[n] + ' reminder turned off');
  }
}

// ─────────────────────────────────────────────────────────
// RASHIK JAN O BHAKTA JAN — bilingual gallery of 83 rasik-sant and
// bhakta portraits (Hindi names transcribed to Bangla too). Files at
// ./rashikan/pNNN.jpg, cropped from the source screenshots.
// ─────────────────────────────────────────────────────────
const RJ_GROUPS = {
  hari: { hi: "हरित्रयी — वृन्दावन", bn: "বৃন্দাবনের হরিত্রয়" },
  rasik: { hi: "रसिक जन — राधावल्लभ परम्परा", bn: "রসিক জন — রাধাবল্লভ পরম্পরা" },
  hdasi: { hi: "रसिक जन — हरिदासी परम्परा", bn: "রসিক জন — হরিদাসী পরম্পরা" },
  smarta: { hi: "आचार्य — स्मार्त परम्परा", bn: "আচার্য — স্মার্ত পরম্পরা" },
  vaish: { hi: "आचार्य — वैष्णव परम्परा", bn: "আচার্য — বৈষ্ণব পরম্পরা" },
  gaud: { hi: "गौड़ीय परम्परा", bn: "গৌড়ীয় পরম্পরা" },
  gos: { hi: "षड्गोस्वामी एवं गौड़ीय वंश", bn: "ষড়্গোস্বামী ও গৌড়ীয় বংশ" },
  sant: { hi: "अन्य सन्त एवं भक्तजन", bn: "অন্যান্য সন্ত ও ভক্তজন" },
  guru: { hi: "सद्गुरुदेव", bn: "সদ্গুরুদেব" },
};
// Serial order: Hari-Trayi → Rasik Jan → Acharyas → Gaudiya → Six Goswamis →
// other saints → Sadgurudev. g = group key, nh / nb = short note (Hindi / Bangla).
const RASHIKJAN_ITEMS = [
  { file: './rashikan/p080.JPG', hi: "वृन्दावन की हरित्रयी", bn: "বৃন্দাবনের হরিত্রয়", g: 'hari', nh: "मध्य में: परम पूज्य स्वामी श्री हरिदास जू महाराज (श्री ललिता सखी जू के अवतार)। बाएँ: परम पूज्य श्री हरिराम व्यास जी महाराज (श्री विशाखा सखी जू के अवतार)। दाएँ: परम पूज्य श्री हित हरिवंश चन्द्र जू महाराज (श्रीकृष्ण की वंशी के अवतार)।", nb: "মাঝে: পরম পূজ্য স্বামী শ্রী হরিদাস জূ মহারাজ (শ্রী ললিতা সখী জূর অবতার)। বামে: পরম পূজ্য শ্রী হরিরাম ব্যাস জী মহারাজ (শ্রী বিশাখা সখী জূর অবতার)। ডানে: পরম পূজ্য শ্রী হিত হরিবংশ চন্দ্র জূ মহারাজ (শ্রীকৃষ্ণের বংশীর অবতার)।", dh: "ये तीनों रसिक महापुरुष वृन्दावन की रस-परम्परा के आधार-स्तम्भ हैं और 'वृन्दावन की हरित्रयी' के नाम से स्मरण किए जाते हैं।\n\nमध्य में परम पूज्य स्वामी श्री हरिदास जू महाराज हैं — परम्परा में श्री ललिता सखी जू के अवतार, हरिदासी (सखी) सम्प्रदाय के प्रवर्तक और निधिवन के महान संगीतज्ञ सन्त।\n\nबाएँ परम पूज्य श्री हरिराम व्यास जी महाराज हैं — श्री विशाखा सखी जू के अवतार, ओरछा से आकर वृन्दावन में बसे रसिक कवि।\n\nदाएँ परम पूज्य श्री हित हरिवंश चन्द्र जू महाराज हैं — श्रीकृष्ण की वंशी के अवतार और श्रीराधावल्लभ सम्प्रदाय के प्रवर्तक।\n\nअगले पृष्ठों में तीनों का अलग-अलग परिचय दिया गया है।", db: "এই তিন রসিক মহাপুরুষ বৃন্দাবনের রস-পরম্পরার ভিত্তিস্তম্ভ এবং 'বৃন্দাবনের হরিত্রয়' নামে স্মরণীয়।\n\nমাঝে পরম পূজ্য স্বামী শ্রী হরিদাস জূ মহারাজ — পরম্পরায় শ্রী ললিতা সখী জূর অবতার, হরিদাসী (সখী) সম্প্রদায়ের প্রবর্তক ও নিধিবনের মহান সংগীতজ্ঞ সন্ত।\n\nবামে পরম পূজ্য শ্রী হরিরাম ব্যাস জী মহারাজ — শ্রী বিশাখা সখী জূর অবতার, ওরছা থেকে এসে বৃন্দাবনে বসবাসকারী রসিক কবি।\n\nডানে পরম পূজ্য শ্রী হিত হরিবংশ চন্দ্র জূ মহারাজ — শ্রীকৃষ্ণের বংশীর অবতার এবং শ্রীরাধাবল্লভ সম্প্রদায়ের প্রবর্তক।\n\nপরের পাতাগুলিতে তিনজনের আলাদা পরিচয় দেওয়া আছে।" },
  { file: './rashikan/p035.jpg', hi: "सम्प्रदायाचार्य वंशी अवतार श्री हित हरिवंश चन्द्र महाप्रभु जी", bn: "সম্প্রদায়াচার্য বংশী অবতার শ্রী হিত হরিবংশ চন্দ্র মহাপ্রভু জী", g: 'hari', nh: "राधावल्लभ सम्प्रदाय के संस्थापक (1502–1552)। मथुरा के निकट बाद ग्राम में जन्म; भगवान् की वंशी के अवतार माने जाते हैं। 'हित चौरासी' आपकी प्रमुख वाणी है; 1535 में वृन्दावन में श्रीराधावल्लभ जी की सेवा प्रकट हुई।", nb: "রাধাবল্লভ সম্প্রদায়ের প্রতিষ্ঠাতা (১৫০২–১৫৫২)। মথুরার কাছে বাদ গ্রামে জন্ম; ভগবানের বংশীর অবতার বলে মান্য। আপনার প্রধান বাণী 'হিত চৌরাশী'; ১৫৩৫ সালে বৃন্দাবনে শ্রীরাধাবল্লভজির সেবা প্রকট হয়।", dh: "श्रीहित हरिवंश महाप्रभु (1502–1552) का जन्म मथुरा के निकट बाद ग्राम में हुआ। पिता व्यास मिश्र मुग़ल दरबार में मनसबदार थे। परम्परा में आपको भगवान् श्रीकृष्ण की वंशी का अवतार माना जाता है।\n\nबत्तीस वर्ष की आयु में आप देववन से वृन्दावन चले; मार्ग में चिरथावल में आत्मदेव ब्राह्मण ने अपनी दो कन्याओं का विवाह आपसे किया और श्रीराधावल्लभ जी का विग्रह सौंपा। वृन्दावन में मदनटेर पर विग्रह की प्रतिष्ठा हुई और राधावल्लभ सम्प्रदाय का आरम्भ हुआ।\n\nआपकी चार रचनाएँ प्रसिद्ध हैं — 'राधासुधानिधि' (संस्कृत, लगभग 270 श्लोक), 'हित चौरासी' (ब्रजभाषा के 84 पद), 'स्फुट वाणी' और 'यमुनाष्टक'। आपके उपदेश का सार है — श्रीराधा की सर्वोच्चता और प्रेम-रूपा भक्ति। संगीत और पद गायन की जो परम्परा आपने चलाई, वह आज भी राधावल्लभ मन्दिर में जीवित है।", db: "শ্রীহিত হরিবংশ মহাপ্রভু (১৫০২–১৫৫২) মথুরার কাছে বাদ গ্রামে জন্মগ্রহণ করেন। পিতা ব্যাস মিশ্র মুঘল দরবারের মনসবদার ছিলেন। ঐতিহ্যে আপনাকে ভগবান শ্রীকৃষ্ণের বংশীর অবতার বলে মানা হয়।\n\nবত্রিশ বছর বয়সে আপনি দেববন থেকে বৃন্দাবনের পথে রওনা হন; পথে চিরথাবলে আত্মদেব ব্রাহ্মণ নিজের দুই কন্যার বিবাহ আপনার সঙ্গে দেন এবং শ্রীরাধাবল্লভজির বিগ্রহ সমর্পণ করেন। বৃন্দাবনে মদনটেরে বিগ্রহের প্রতিষ্ঠা হয় এবং রাধাবল্লভ সম্প্রদায়ের সূচনা ঘটে।\n\nআপনার চারটি রচনা প্রসিদ্ধ — 'রাধাসুধানিধি' (সংস্কৃত, প্রায় ২৭০ শ্লোক), 'হিত চৌরাশী' (ব্রজভাষার ৮৪টি পদ), 'স্ফুট বাণী' ও 'যমুনাষ্টক'। আপনার উপদেশের সার — শ্রীরাধার সর্বোচ্চতা এবং প্রেমস্বরূপা ভক্তি। সংগীত ও পদ গাওয়ার যে পরম্পরা আপনি চালু করেন তা আজও রাধাবল্লভ মন্দিরে জীবন্ত।" },
  { file: './rashikan/p067.jpg', hi: "श्री स्वामी हरिदास जू महाराज", bn: "শ্রী স্বামী হরিদাস জূ মহারাজ", g: 'hari', nh: "हरिदासी (सखी) सम्प्रदाय के प्रवर्तक; वृन्दावन के निधिवन में साधना। परम्परा में ललिता सखी के अवतार, ठाकुर श्रीबाँकेबिहारी जी के प्रकटकर्ता। महान संगीतज्ञ, तानसेन के गुरु माने जाते हैं।", nb: "হরিদাসী (সখী) সম্প্রদায়ের প্রবর্তক; বৃন্দাবনের নিধিবনে সাধনা। পরম্পরায় ললিতা সখীর অবতার, ঠাকুর শ্রীবাঁকেবিহারীজির প্রকটকর্তা। মহান সংগীতজ্ঞ, তানসেনের গুরু বলে মান্য।", dh: "स्वामी श्रीहरिदास जी हरिदासी (सखी) सम्प्रदाय के प्रवर्तक और महान संगीतज्ञ थे। हरिदासी परम्परा के अनुसार उनका जन्म वृन्दावन के पास राजपुर में लगभग 1480 ई. में हुआ; विद्वानों के मत में वे ग्वालियर क्षेत्र से जुड़े माने जाते हैं। जन्म-तिथि और स्थान पर मतभेद है, पर वृन्दावन के निधिवन में उनकी साधना और वहीं देह-त्याग (लगभग 1573–75) सब मानते हैं।\n\nआप सखी-भाव से श्यामा-कुंजबिहारी की उपासना करते थे और कहते थे — 'हरिदास के स्वामी श्यामा-कुंजबिहारी'। आपकी प्रमुख वाणी 'केलिमाल' (विहार-पद) और 'अष्टादश सिद्धान्त' है; लगभग 128 पद आपके नाम से मिलते हैं। परम्परा में आप ललिता सखी के अवतार हैं और आपके प्रेम से श्रीबाँकेबिहारी जी निधिवन में प्रकट हुए।\n\nध्रुपद-गायन में आपकी अद्वितीय देन मानी जाती है। तानसेन और बैजू बावरा जैसे संगीतकारों को आपका शिष्य कहा जाता है; कथा है कि अकबर तानसेन के साथ वेश बदलकर निधिवन में आपका गान सुनने आया था।", db: "স্বামী শ্রীহরিদাসজি হরিদাসী (সখী) সম্প্রদায়ের প্রবর্তক ও মহান সংগীতজ্ঞ। হরিদাসী পরম্পরা অনুসারে তাঁর জন্ম বৃন্দাবনের কাছে রাজপুরে প্রায় ১৪৮০ খ্রিষ্টাব্দে; পণ্ডিতদের মতে তিনি গোয়ালিয়র অঞ্চলের সঙ্গে যুক্ত। জন্মতারিখ ও স্থান নিয়ে মতভেদ আছে, তবে বৃন্দাবনের নিধিবনে তাঁর সাধনা ও সেখানেই দেহত্যাগ (প্রায় ১৫৭৩–৭৫) সবাই মানেন।\n\nতিনি সখী-ভাবে শ্যামা-কুঞ্জবিহারীর উপাসনা করতেন এবং বলতেন — 'হরিদাসের স্বামী শ্যামা-কুঞ্জবিহারী'। তাঁর প্রধান বাণী 'কেলিমাল' (বিহার-পদ) ও 'অষ্টাদশ সিদ্ধান্ত'; প্রায় ১২৮টি পদ তাঁর নামে পাওয়া যায়। ঐতিহ্যে তিনি ললিতা সখীর অবতার, এবং তাঁর প্রেমে শ্রীবাঁকেবিহারীজি নিধিবনে প্রকট হন।\n\nধ্রুপদ গায়নে তাঁর অনন্য অবদান মানা হয়। তানসেন ও বৈজু বাওরার মতো সংগীতশিল্পীদের তাঁর শিষ্য বলা হয়; কথিত আছে আকবর তানসেনের সঙ্গে ছদ্মবেশে নিধিবনে এসে তাঁর গান শুনেছিলেন।" },
  { file: './rashikan/p034.jpg', hi: "श्री हरिराम व्यास जी", bn: "শ্রী হরিরাম ব্যাস জী", g: 'hari', nh: "ओरछा में जन्म (1512); हित हरिवंश जी के शिष्य, राधावल्लभीय रसिक कवि-संगीतज्ञ। वृन्दावन के किशोरवन से श्रीजुगलकिशोर जी का विग्रह प्रकट करने वाले माने जाते हैं। परम्परा में विशाखा सखी के अवतार; राजा मधुकर शाह इनके शिष्य थे।", nb: "ওরছায় জন্ম (১৫১২); হিত হরিবংশজির শিষ্য, রাধাবল্লভীয় রসিক কবি ও সংগীতজ্ঞ। বৃন্দাবনের কিশোরবন থেকে শ্রীজুগলকিশোরজির বিগ্রহ প্রকট করেছিলেন বলে মান্য। পরম্পরায় বিশাখা সখীর অবতার; রাজা মধুকর শাহ তাঁর শিষ্য ছিলেন।", dh: "श्रीहरिराम व्यास (जन्म 1512) ओरछा (बुन्देलखण्ड) के सनाढ्य गौड़ ब्राह्मण परिवार में जन्मे। वे संस्कृत के विद्वान थे और ओरछा के राजा मधुकर शाह के राजगुरु बने। परम्परा में उन्हें अनेक रियासतों का गुरु कहा जाता है।\n\nहित हरिवंश जी के शिष्य नवलदास जी के सत्संग से उनमें वृन्दावन और श्रीहरिवंश के दर्शन की इच्छा जागी। वे सब कुछ छोड़कर वृन्दावन आए और आजीवन ब्रज से बाहर न जाने का व्रत लिया। कथा है कि महाप्रभु ने जब उन्हें ओरछा लौटने को कहा तो वे तीन दिन दर्शन को नहीं गए और बोले — 'यदि मैं धाम में रहने योग्य होता, तो गुरुदेव मुझे यहीं न रख लेते?' इस पर महाप्रभु ने उन्हें वृन्दावन में ही रहने दिया।\n\n'व्यासवाणी' आपकी रचना है, जिसमें वृन्दावन-रज की महिमा और श्रीराधा-कृष्ण की लीला गाई गई है। आप हरित्रयी (हित हरिवंश, स्वामी हरिदास और हरिराम व्यास) में गिने जाते हैं; परम्परा में विशाखा सखी के अवतार माने जाते हैं।", db: "শ্রীহরিরাম ব্যাস (জন্ম ১৫১২) ওরছার (বুন্দেলখণ্ড) সনাঢ্য গৌড় ব্রাহ্মণ পরিবারে জন্মান। তিনি সংস্কৃতজ্ঞ পণ্ডিত ছিলেন এবং ওরছার রাজা মধুকর শাহের রাজগুরু হন। ঐতিহ্যে তাঁকে বহু রাজ্যের গুরু বলা হয়।\n\nহিত হরিবংশজির শিষ্য নবলদাসজির সৎসঙ্গে তাঁর মনে বৃন্দাবন ও শ্রীহরিবংশের দর্শনের ইচ্ছা জাগে। তিনি সবকিছু ছেড়ে বৃন্দাবনে এসে আজীবন ব্রজের বাইরে না যাওয়ার ব্রত নেন। কথিত আছে মহাপ্রভু তাঁকে ওরছায় ফিরতে বললে তিনি তিন দিন দর্শনে যাননি এবং বলেন — 'আমি ধামে থাকার যোগ্য হলে কি গুরুদেব আমাকে এখানেই রাখতেন না?' তাতে মহাপ্রভু তাঁকে বৃন্দাবনেই থাকতে দেন।\n\n'ব্যাসবাণী' তাঁর রচনা, যেখানে বৃন্দাবন-রজের মহিমা ও শ্রীরাধা-কৃষ্ণের লীলা গীত হয়েছে। তিনি হরিত্রয়ের (হিত হরিবংশ, স্বামী হরিদাস ও হরিরাম ব্যাস) অন্যতম; ঐতিহ্যে বিশাখা সখীর অবতার বলে মান্য।" },
  { file: './rashikan/p065.jpg', hi: "गो. श्री वनचन्द्र महाप्रभु जी", bn: "গো. শ্রী বনচন্দ্র মহাপ্রভু জী", g: 'rasik', nh: "हित हरिवंश जी के ज्येष्ठ पुत्र और राधावल्लभ सम्प्रदाय के प्रमुख आचार्य। इन्हीं के शिष्य सुन्दरदास भटनागर ने 1585 में श्रीराधावल्लभ जी का प्राचीन लाल पत्थर का मन्दिर बनवाया।", nb: "হিত হরিবংশজির জ্যেষ্ঠ পুত্র ও রাধাবল্লভ সম্প্রদায়ের প্রধান আচার্য। তাঁরই শিষ্য সুন্দরদাস ভটনাগর ১৫৮৫ সালে শ্রীরাধাবল্লভজির প্রাচীন লাল পাথরের মন্দির নির্মাণ করান।", dh: "श्रीवनचन्द्र (वनचन्द्र) महाप्रभु हित हरिवंश जी के ज्येष्ठ पुत्र थे और पिता के बाद राधावल्लभ सम्प्रदाय के आचार्य बने। वे सेवा-पद्धति और आचार्य-परम्परा के आधार-स्तम्भ माने जाते हैं।\n\nसेवक जी की वाणी की गहराई देखकर उन्होंने आज्ञा दी कि 'सेवक वाणी' का पाठ 'हित चौरासी' के साथ किया जाए — यह परम्परा आज तक चल रही है। नेही नागरीदास जैसे रसिक सन्तों को भी उन्हीं से दीक्षा मिली। परम्परा के अनुसार उनके शिष्य सुन्दरदास भटनागर ने 1585 में श्रीराधावल्लभ जी का प्राचीन लाल पत्थर का मन्दिर बनवाया।", db: "শ্রীবনচন্দ্র মহাপ্রভু হিত হরিবংশজির জ্যেষ্ঠ পুত্র এবং পিতার পর রাধাবল্লভ সম্প্রদায়ের আচার্য হন। তিনি সেবা-পদ্ধতি ও আচার্য-পরম্পরার ভিত্তিস্তম্ভ বলে মান্য।\n\nসেবকজির বাণীর গভীরতা দেখে তিনি আদেশ দেন 'সেবক বাণী' যেন 'হিত চৌরাশী'র সঙ্গে পাঠ করা হয় — এই প্রথা আজও চলছে। নেহী নাগরীদাসের মতো রসিক সন্তরাও তাঁর কাছেই দীক্ষা পান। ঐতিহ্য অনুসারে তাঁর শিষ্য সুন্দরদাস ভটনাগর ১৫৮৫ সালে শ্রীরাধাবল্লভজির প্রাচীন লাল পাথরের মন্দির নির্মাণ করান।" },
  { file: './rashikan/p061.jpg', hi: "गो. श्रीहित श्रीकृष्णचन्द्र महाप्रभु जी महाराज", bn: "গো. শ্রীহিত শ্রীকৃষ্ণচন্দ্র মহাপ্রভু জী মহারাজ", g: 'rasik', nh: "हित हरिवंश जी के द्वितीय पुत्र। इनकी वंश-परम्परा में अनेक रसिक आचार्य हुए; अनन्य अली जी के गुरु गोस्वामी गोविन्दलाल जी इसी वंश के थे।", nb: "হিত হরিবংশজির দ্বিতীয় পুত্র। এঁর বংশ-পরম্পরায় বহু রসিক আচার্য হয়েছেন; অনন্য অলিজির গুরু গোস্বামী গোবিন্দলালজি এই বংশেরই ছিলেন।", dh: "श्रीकृष्णचन्द्र महाप्रभु हित हरिवंश जी के द्वितीय पुत्र थे। राधावल्लभ सम्प्रदाय में गोस्वामी वंश की कई शाखाएँ चलीं, जिनमें इनकी शाखा भी प्रसिद्ध है। इनकी वंश-परम्परा के गोस्वामी गोविन्दलाल जी, रसिक सन्त अनन्य अली जी के गुरु थे।\n\nआज भी राधावल्लभ मन्दिर की सेवा-व्यवस्था और पद गायन का दायित्व हित हरिवंश जी के वंशज गोस्वामी ही सँभालते हैं।", db: "শ্রীকৃষ্ণচন্দ্র মহাপ্রভু হিত হরিবংশজির দ্বিতীয় পুত্র। রাধাবল্লভ সম্প্রদায়ে গোস্বামী বংশের একাধিক শাখা চলে, যার মধ্যে এঁর শাখাও প্রসিদ্ধ। এঁর বংশের গোস্বামী গোবিন্দলালজি রসিক সন্ত অনন্য অলিজির গুরু ছিলেন।\n\nআজও রাধাবল্লভ মন্দিরের সেবা-ব্যবস্থা ও পদ গাওয়ার দায়িত্ব হিত হরিবংশজির বংশধর গোস্বামীরাই সামলান।" },
  { file: './rashikan/p017.jpg', hi: "गो. श्रीहित श्रीगोपीनाथ महाप्रभु जी महाराज", bn: "গো. শ্রীহিত শ্রীগোপীনাথ মহাপ্রভু জী মহারাজ", g: 'rasik', nh: "हित हरिवंश जी के तृतीय पुत्र। रसिक सन्त श्रीहित ध्रुवदास जी इन्हीं के शिष्य थे।", nb: "হিত হরিবংশজির তৃতীয় পুত্র। রসিক সন্ত শ্রীহিত ধ্রুবদাসজি এঁরই শিষ্য ছিলেন।", dh: "श्रीगोपीनाथ महाप्रभु हित हरिवंश जी के तृतीय पुत्र थे। वे राधावल्लभ आचार्य-परम्परा के प्रसिद्ध गोस्वामी हैं, जिनके शिष्य रसिक सन्त श्रीहित ध्रुवदास जी बने।\n\nध्रुवदास जी को श्रीराधा जी की कृपा का जो अनुभव हुआ और उन्होंने 'बयालीस लीला' जैसी रस-वाणी रची — उसकी आधार-भूमि में अपने गुरु गोपीनाथ जी की शिक्षा ही मानी जाती है।", db: "শ্রীগোপীনাথ মহাপ্রভু হিত হরিবংশজির তৃতীয় পুত্র। তিনি রাধাবল্লভ আচার্য-পরম্পরার প্রসিদ্ধ গোস্বামী, যাঁর শিষ্য ছিলেন রসিক সন্ত শ্রীহিত ধ্রুবদাসজি।\n\nধ্রুবদাসজি শ্রীরাধার যে কৃপা অনুভব করেন এবং 'বয়ালিস লীলা'-র মতো রস-বাণী রচনা করেন — তার ভিত্তিতে গুরু গোপীনাথজির শিক্ষাই মানা হয়।" },
  { file: './rashikan/p013.jpg', hi: "गो. श्रीहित श्रीमोहनचन्द्र महाप्रभु जी महाराज", bn: "গো. শ্রীহিত শ্রীমোহনচন্দ্র মহাপ্রভু জী মহারাজ", g: 'rasik', nh: "हित हरिवंश जी के वंश के पूज्य गोस्वामी; राधावल्लभीय आचार्य-परम्परा के महाप्रभु।", nb: "হিত হরিবংশজির বংশের পূজ্য গোস্বামী; রাধাবল্লভীয় আচার্য-পরম্পরার মহাপ্রভু।" },
  { file: './rashikan/p009.jpg', hi: "श्री हित सेवक जी महाराज", bn: "শ্রী হিত সেবক জী মহারাজ", g: 'rasik', nh: "श्री दामोदर दास 'सेवक जी' — हित हरिवंश जी के प्रमुख शिष्य। परम्परा में इन्हें दिव्य दर्शन में स्वयं महाप्रभु से दीक्षा मिली। 'श्रीहित सेवकवाणी' आपकी रचना है, जिसका पाठ 'हित चौरासी' के साथ होता है।", nb: "শ্রী দামোদর দাস 'সেবকজি' — হিত হরিবংশজির প্রধান শিষ্য। পরম্পরায় দিব্য দর্শনে স্বয়ং মহাপ্রভুর কাছে দীক্ষা পান। 'শ্রীহিত সেবকবাণী' আপনার রচনা, যা 'হিত চৌরাশী'র সঙ্গে পাঠ করা হয়।", dh: "श्रीसेवक जी (दामोदर दास) का चरित्र बहुत अनूठा है — परम्परा के अनुसार उन्होंने हित हरिवंश जी के प्रत्यक्ष दर्शन नहीं किए, फिर भी महाप्रभु की कृपा उन पर प्रत्यक्ष रही। 'गढ़ा' ग्राम में जब हरिवंश जी के शिष्य रस-उपासना की चर्चा करने पहुँचे, तब सेवक जी और चतुर्भुजदास जी बहुत प्रभावित हुए।\n\nचतुर्भुजदास जी ने दीक्षा आचार्य वनचन्द्र जी से ली, पर सेवक जी के बारे में परम्परा कहती है कि उन्हें दिव्य दर्शन में स्वयं महाप्रभु ने दीक्षा दी। 'श्रीहित सेवकवाणी' उनकी रचना है; वनचन्द्र जी ने उसके गूढ़ अर्थ देखकर कहा कि इसका पाठ 'हित चौरासी' के साथ हो।\n\nकथा है कि सेवक जी वृन्दावन में रासमण्डल के पास एक वट-वृक्ष में समाकर लीन हो गए।", db: "শ্রীসেবকজির (দামোদর দাস) চরিত্র অতি অনন্য — ঐতিহ্য অনুসারে তিনি হিত হরিবংশজির প্রত্যক্ষ দর্শন পাননি, তবু মহাপ্রভুর কৃপা তাঁর ওপর সরাসরি ছিল। 'গঢ়া' গ্রামে হরিবংশজির শিষ্যরা রস-উপাসনার আলোচনা করতে এলে সেবকজি ও চতুর্ভুজদাসজি খুব প্রভাবিত হন।\n\nচতুর্ভুজদাসজি আচার্য বনচন্দ্রজির কাছে দীক্ষা নেন, কিন্তু সেবকজির বিষয়ে ঐতিহ্য বলে দিব্য দর্শনে স্বয়ং মহাপ্রভু তাঁকে দীক্ষা দেন। 'শ্রীহিত সেবকবাণী' তাঁর রচনা; বনচন্দ্রজি এর গূঢ় অর্থ দেখে বলেন যে এটি 'হিত চৌরাশী'র সঙ্গে পাঠ হোক।\n\nকথিত আছে সেবকজি বৃন্দাবনে রাসমণ্ডলের কাছে এক বটগাছে বিলীন হয়ে যান।" },
  { file: './rashikan/p047.jpg', hi: "श्री हित ध्रुवदास जी", bn: "শ্রী হিত ধ্রুবদাস জী", g: 'rasik', nh: "गोस्वामी गोपीनाथ जी के शिष्य; वृन्दावन के अग्रणी रसिक कवि। 'बयालीस लीला' और 'वृन्दावन सत लीला' जैसी नित्य-विहार की रस-वाणी के रचयिता।", nb: "গোস্বামী গোপীনাথজির শিষ্য; বৃন্দাবনের অগ্রগণ্য রসিক কবি। 'বয়ালিস লীলা' ও 'বৃন্দাবন সত লীলা'-র মতো নিত্য-বিহারের রস-বাণীর রচয়িতা।", dh: "श्रीहित ध्रुवदास जी गोस्वामी गोपीनाथ जी (हित हरिवंश जी के तृतीय पुत्र) के शिष्य थे। बचपन से ही श्रीराधा-कृष्ण के प्रति तीव्र अनुराग था; वे प्रेम में विह्वल होकर यमुना-तट और वृन्दावन के वनों में घूमा करते थे।\n\nकथा है कि श्रीराधा के विरह में वे रासमण्डल (वर्तमान 'पुराना रास मण्डल') पर बैठ गए और संकल्प किया कि बिना दर्शन के यहाँ से नहीं जाऊँगा। कई दिन-रात बीत गए। एक रात उन्हें नूपुर की मधुर झंकार सुनाई दी और सिर पर कोमल स्पर्श हुआ — श्रीराधा जी सामने खड़ी थीं और बोलीं, 'मैं तुम्हें कभी नहीं छोड़ूँगी।' इसके बाद उनका जीवन प्रेममय हो गया।\n\n'बयालीस लीला' और 'वृन्दावन सत लीला' उनकी प्रसिद्ध रचनाएँ हैं, जो वृन्दावन की रसोपासना करने वालों में बहुत प्रिय हैं।", db: "শ্রীহিত ধ্রুবদাসজি গোস্বামী গোপীনাথজির (হিত হরিবংশজির তৃতীয় পুত্র) শিষ্য ছিলেন। শৈশব থেকেই শ্রীরাধা-কৃষ্ণের প্রতি তীব্র অনুরাগ ছিল; প্রেমে বিহ্বল হয়ে তিনি যমুনার তীরে ও বৃন্দাবনের বনে ঘুরে বেড়াতেন।\n\nকথিত আছে শ্রীরাধার বিরহে তিনি রাসমণ্ডলে (বর্তমানের 'পুরনো রাস মণ্ডল') বসে সংকল্প করেন — দর্শন না পেলে এখান থেকে যাব না। কয়েক দিন-রাত কেটে যায়। এক রাতে নূপুরের মধুর ঝঙ্কার শোনা গেল এবং মাথায় কোমল স্পর্শ — শ্রীরাধারানি সামনে দাঁড়িয়ে বললেন, 'আমি তোমাকে কখনও ছাড়ব না।' এরপর তাঁর জীবন প্রেমময় হয়ে ওঠে।\n\n'বয়ালিস লীলা' ও 'বৃন্দাবন সত লীলা' তাঁর প্রসিদ্ধ রচনা, যা বৃন্দাবনের রসোপাসকদের কাছে অত্যন্ত প্রিয়।" },
  { file: './rashikan/p049.jpg', hi: "श्री नेही नागरी दास जी", bn: "শ্রী নেহী নাগরী দাস জী", g: 'rasik', nh: "लगभग 1590 में गोंडवाना (बेरछा ग्राम) में जन्मे पँवार क्षत्रिय। चतुर्भुज दास जी के सत्संग से घर छोड़कर वृन्दावन आए, वनचन्द्र जी से दीक्षा ली और नित्य-विहार उपासना की।", nb: "প্রায় ১৫৯০ সালে গোন্ডওয়ানার বেরছা গ্রামে পঁওয়ার ক্ষত্রিয় বংশে জন্ম। চতুর্ভুজ দাসজির সৎসঙ্গে গৃহত্যাগ করে বৃন্দাবনে আসেন, বনচন্দ্রজির কাছে দীক্ষা নিয়ে নিত্য-বিহার উপাসনা করেন।", dh: "नेही नागरीदास जी का जन्म लगभग 1590 में गोंडवाना क्षेत्र के बेरछा ग्राम में पँवार क्षत्रिय कुल में हुआ। राधावल्लभीय रसिक सन्त चतुर्भुजदास जी के सत्संग से उनमें विरक्ति जागी और वे घर छोड़कर वृन्दावन आ गए।\n\nवृन्दावन में उन्होंने आचार्य वनचन्द्र जी से दीक्षा ली और नित्य-विहार की उपासना में जीवन लगाया। रसिक परम्परा में उन्हें सहचरी-भाव के अनन्य उपासक के रूप में स्मरण किया जाता है।", db: "নেহী নাগরীদাসজির জন্ম প্রায় ১৫৯০ সালে গোন্ডওয়ানা অঞ্চলের বেরছা গ্রামে পঁওয়ার ক্ষত্রিয় বংশে। রাধাবল্লভীয় রসিক সন্ত চতুর্ভুজদাসজির সৎসঙ্গে তাঁর মনে বৈরাগ্য জাগে এবং তিনি গৃহ ছেড়ে বৃন্দাবনে আসেন।\n\nবৃন্দাবনে তিনি আচার্য বনচন্দ্রজির কাছে দীক্ষা নেন এবং নিত্য-বিহার উপাসনায় জীবন উৎসর্গ করেন। রসিক পরম্পরায় তাঁকে সহচরী-ভাবের অনন্য উপাসক হিসেবে স্মরণ করা হয়।" },
  { file: './rashikan/p073.jpg', hi: "गो. श्री हित रूपलालजी", bn: "গো. শ্রী হিত রূপলালজী", g: 'rasik', nh: "अठारहवीं शताब्दी के राधावल्लभीय गोस्वामी, चाचा हित वृन्दावन दास जी के गुरु। कथा है कि गुरु-आज्ञा से मानसरोवर जाने पर चाचा जी में काव्य-प्रतिभा जाग उठी।", nb: "অষ্টাদশ শতাব্দীর রাধাবল্লভীয় গোস্বামী, চাচা হিত বৃন্দাবন দাসজির গুরু। কথিত আছে গুরুর আদেশে মানসরোবরে গেলে চাচাজির কাব্য-প্রতিভা জেগে ওঠে।", dh: "गोस्वामी श्रीहित रूपलाल जी अठारहवीं शताब्दी के राधावल्लभीय गोस्वामी और रसिक आचार्य थे। वे चाचा श्रीहित वृन्दावनदास जी के गुरु थे।\n\nपरम्परा में कथा मिलती है कि गुरु-आज्ञा से जब चाचा जी मानसरोवर गए, तब उनके भीतर काव्य-प्रतिभा जाग उठी और उन्होंने अपने गुरु का चरित्र 'हित रूप चरित्र बेलि' के रूप में गाया। इस प्रकार रूपलाल जी का जीवन उनके शिष्य की वाणी में सुरक्षित है।", db: "গোস্বামী শ্রীহিত রূপলালজি অষ্টাদশ শতাব্দীর রাধাবল্লভীয় গোস্বামী ও রসিক আচার্য ছিলেন। তিনি চাচা শ্রীহিত বৃন্দাবনদাসজির গুরু।\n\nঐতিহ্যে কথা আছে — গুরুর আদেশে চাচাজি মানসরোবরে গেলে তাঁর ভেতর কাব্য-প্রতিভা জেগে ওঠে এবং তিনি গুরুর চরিত্র 'হিত রূপ চরিত্র বেলি' রূপে গান করেন। এভাবে রূপলালজির জীবন তাঁর শিষ্যের বাণীতে সংরক্ষিত।" },
  { file: './rashikan/p002.jpg', hi: "चाचा श्रीहित वृंदावन दास जी", bn: "চাচা শ্রীহিত বৃন্দাবন দাস জী", g: 'rasik', nh: "(लगभग 1700–1787) राधावल्लभीय रसिक सन्त-कवि, हित रूपलाल जी के शिष्य। 'हित रूप चरित्र बेलि', 'ब्रज प्रेम आनन्द सागर', 'स्वप्न विलास' आदि के रचयिता; अब्दाली के आक्रमण (1757) के समय का वर्णन भी इनकी रचनाओं में मिलता है।", nb: "(প্রায় ১৭০০–১৭৮৭) রাধাবল্লভীয় রসিক সন্ত-কবি, হিত রূপলালজির শিষ্য। 'হিত রূপ চরিত্র বেলি', 'ব্রজ প্রেম আনন্দ সাগর', 'স্বপ্ন বিলাস' ইত্যাদির রচয়িতা; আবদালির আক্রমণের (১৭৫৭) সময়ের বর্ণনাও তাঁর রচনায় পাওয়া যায়।", dh: "चाचा श्रीहित वृन्दावनदास जी (लगभग 1700–1787) राधावल्लभीय रसिक सन्त और कवि थे; वे गोस्वामी हित रूपलाल जी के शिष्य थे। 'चाचा' नाम उन्हें प्रेम और आदर से मिला।\n\nउनकी प्रमुख रचनाएँ हैं — 'हित रूप चरित्र बेलि', 'ब्रज प्रेम आनन्द सागर', 'स्वप्न विलास' आदि। इनमें राधा-कृष्ण की नित्य-लीला के साथ अपने समय की घटनाओं का भी वर्णन मिलता है; अब्दाली के आक्रमण (1757) के समय वृन्दावन का हाल उनकी रचनाओं से जाना जाता है।", db: "চাচা শ্রীহিত বৃন্দাবনদাসজি (প্রায় ১৭০০–১৭৮৭) রাধাবল্লভীয় রসিক সন্ত ও কবি; তিনি গোস্বামী হিত রূপলালজির শিষ্য। 'চাচা' নামটি তিনি ভালোবাসা ও শ্রদ্ধায় পেয়েছেন।\n\nতাঁর প্রধান রচনা — 'হিত রূপ চরিত্র বেলি', 'ব্রজ প্রেম আনন্দ সাগর', 'স্বপ্ন বিলাস' ইত্যাদি। এগুলিতে রাধা-কৃষ্ণের নিত্যলীলার পাশাপাশি তাঁর সময়ের ঘটনাও পাওয়া যায়; আবদালির আক্রমণের (১৭৫৭) সময় বৃন্দাবনের অবস্থা তাঁর রচনা থেকে জানা যায়।" },
  { file: './rashikan/p069.jpg', hi: "रसिक सन्त श्रीहित प्रेमदास जी", bn: "রসিক সন্ত শ্রীহিত প্রেমদাস জী", g: 'rasik', nh: "राधावल्लभ परम्परा के रसिक सन्त। इनका विस्तृत परिचय अभी संकलित नहीं हुआ है; आगे जोड़ा जाएगा।", nb: "রাধাবল্লভ পরম্পরার রসিক সন্ত। এঁর বিস্তারিত পরিচয় এখনও সংকলিত হয়নি; পরে যোগ করা হবে।" },
  { file: './rashikan/p027.jpg', hi: "श्री विट्ठल विपुल देव जी महाराज", bn: "শ্রী বিঠ্ঠল বিপুল দেব জী মহারাজ", g: 'hdasi', nh: "स्वामी हरिदास जी के शिष्य; हरिदासी परम्परा के अष्ट आचार्यों में द्वितीय। निधिवन में निवास और समाधि; 'विपुल बिहारिणी दासी' भाव से सखी-रस की वाणी रची।", nb: "স্বামী হরিদাসজির শিষ্য; হরিদাসী পরম্পরার অষ্ট আচার্যের মধ্যে দ্বিতীয়। নিধিবনে বাস ও সমাধি; 'বিপুল বিহারিণী দাসী' ভাবে সখী-রসের বাণী রচনা করেন।", dh: "विट्ठल विपुल देव जी स्वामी हरिदास जी के प्रमुख शिष्य और हरिदासी परम्परा के अष्टाचार्यों में द्वितीय माने जाते हैं। विद्वानों के अनुसार वे स्वामी जी के सबसे प्रमुख विरक्त अनुयायी थे।\n\nवे निधिवन में रहे और उनकी समाधि भी वहीं है। 'विट्ठल विपुल' छाप से उन्होंने सखी-रस के पद रचे; 'विपुल बिहारिणी दासी' भाव उनकी उपासना का प्रमुख स्वर है।", db: "বিট্ঠল বিপুল দেবজি স্বামী হরিদাসজির প্রধান শিষ্য এবং হরিদাসী পরম্পরার অষ্টাচার্যের মধ্যে দ্বিতীয় বলে মান্য। পণ্ডিতদের মতে তিনি স্বামীজির সবচেয়ে প্রধান বিরক্ত অনুগামী ছিলেন।\n\nতিনি নিধিবনে থাকতেন এবং তাঁর সমাধিও সেখানেই। 'বিট্ঠল বিপুল' ছাপে তিনি সখী-রসের পদ রচনা করেন; 'বিপুল বিহারিণী দাসী' ভাব তাঁর উপাসনার প্রধান সুর।" },
  { file: './rashikan/p054.jpg', hi: "श्री विहारिन देव जू", bn: "শ্রী বিহারিন দেব জূ", g: 'hdasi', nh: "स्वामी हरिदास जी के प्रमुख शिष्य और हरिदासी अष्टाचार्यों में से एक; वृन्दावन के सखी-भाव के रसिक।", nb: "স্বামী হরিদাসজির প্রধান শিষ্য ও হরিদাসী অষ্টাচার্যদের একজন; বৃন্দাবনের সখী-ভাবের রসিক।" },
  { file: './rashikan/p066.jpg', hi: "श्री नागरी देव जू", bn: "শ্রী নাগরী দেব জূ", g: 'hdasi', nh: "हरिदासी अष्टाचार्यों में से एक; स्वामी हरिदास जी की परम्परा के सखी-भावुक रसिक।", nb: "হরিদাসী অষ্টাচার্যদের একজন; স্বামী হরিদাসজির পরম্পরার সখী-ভাবুক রসিক।" },
  { file: './rashikan/p036.jpg', hi: "श्री सरस देव जी", bn: "শ্রী সরস দেব জী", g: 'hdasi', nh: "हरिदासी परम्परा के चतुर्थ आचार्य; निधिवन की गद्दी पर विराजे। बुन्देलखण्ड के बालक नरहरि देव को दीक्षा देकर अपना उत्तराधिकारी बनाया।", nb: "হরিদাসী পরম্পরার চতুর্থ আচার্য; নিধিবনের গদিতে আসীন। বুন্দেলখণ্ডের বালক নরহরি দেবকে দীক্ষা দিয়ে নিজের উত্তরসূরি করেন।", dh: "सरसदेव जी हरिदासी परम्परा के चतुर्थ आचार्य थे और निधिवन की आचार्य-गद्दी पर विराजे। वे हरिदासी (टट्टी स्थान) परम्परा के रसिक सन्त के रूप में प्रसिद्ध हैं।\n\nबुन्देलखण्ड के बालक नरहरि देव को उन्होंने दीक्षा दी और बाद में उन्हें अपना उत्तराधिकारी बनाया — इस प्रकार निधिवन की गद्दी की परम्परा आगे बढ़ी।", db: "সরসদেবজি হরিদাসী পরম্পরার চতুর্থ আচার্য এবং নিধিবনের আচার্য-গদিতে আসীন ছিলেন। তিনি হরিদাসী (টাট্টি স্থান) পরম্পরার রসিক সন্ত হিসেবে প্রসিদ্ধ।\n\nবুন্দেলখণ্ডের বালক নরহরি দেবকে তিনি দীক্ষা দেন এবং পরে নিজের উত্তরসূরি করেন — এভাবে নিধিবনের গদির পরম্পরা এগিয়ে যায়।" },
  { file: './rashikan/p062.jpg', hi: "श्री नरहरि देव जू", bn: "শ্রী নরহরি দেব জূ", g: 'hdasi', nh: "बुन्देलखण्ड में धसान नदी-तट के गुढ़ा ग्राम में विष्णुदास जी के घर जन्म। सरसदेव जी से दीक्षा लेकर वृन्दावन आए और निधिवन की गद्दी पर बैठे; ब्रजवासियों से अतिशय प्रेम रखते थे।", nb: "বুন্দেলখণ্ডে ধসান নদীর তীরে গুঢ়া গ্রামে বিষ্ণুদাসজির গৃহে জন্ম। সরসদেবজির কাছে দীক্ষা নিয়ে বৃন্দাবনে আসেন ও নিধিবনের গদিতে বসেন; ব্রজবাসীদের অত্যন্ত ভালোবাসতেন।", dh: "नरहरि देव जी का जन्म बुन्देलखण्ड में धसान नदी के तट पर बसे गुढ़ा ग्राम में विष्णुदास जी के घर हुआ। बालपन में ही वे सरसदेव जी के पास पहुँचे, उनसे दीक्षा ली और वृन्दावन आ गए।\n\nगुरु के बाद वे निधिवन की गद्दी पर विराजे। परम्परा बताती है कि वे ब्रजवासियों से अत्यन्त प्रेम रखते थे और उनकी सेवा को ही अपनी साधना मानते थे।", db: "নরহরি দেবজির জন্ম বুন্দেলখণ্ডে ধসান নদীর তীরে গুঢ়া গ্রামে বিষ্ণুদাসজির গৃহে। শৈশবেই তিনি সরসদেবজির কাছে পৌঁছে দীক্ষা নেন এবং বৃন্দাবনে আসেন।\n\nগুরুর পর তিনি নিধিবনের গদিতে আসীন হন। পরম্পরা বলে তিনি ব্রজবাসীদের অত্যন্ত ভালোবাসতেন এবং তাঁদের সেবাকেই নিজের সাধনা মানতেন।" },
  { file: './rashikan/p012.jpg', hi: "श्री रसिक देव जू", bn: "শ্রী রসিক দেব জূ", g: 'hdasi', nh: "हरिदासी अष्टाचार्यों में से एक; निधिवन की रसिक परम्परा के सन्त।", nb: "হরিদাসী অষ্টাচার্যদের একজন; নিধিবনের রসিক পরম্পরার সন্ত।" },
  { file: './rashikan/p025.jpg', hi: "श्री ललित किशोरी देव जी", bn: "শ্রী ললিত কিশোরী দেব জী", g: 'hdasi', nh: "हरिदासी अष्टाचार्यों में गिने जाने वाले रसिक सन्त; युगल-प्रेम की सखी-भावना की वाणी।", nb: "হরিদাসী অষ্টাচার্যদের মধ্যে গণ্য রসিক সন্ত; যুগল-প্রেমের সখী-ভাবনার বাণী।" },
  { file: './rashikan/p018.jpg', hi: "श्री ललित मोहिनी देव जू", bn: "শ্রী ললিত মোহিনী দেব জূ", g: 'hdasi', nh: "हरिदासी अष्टाचार्यों में गिने जाने वाले रसिक सन्त; निधिवन की सखी-भाव परम्परा के उपासक।", nb: "হরিদাসী অষ্টাচার্যদের মধ্যে গণ্য রসিক সন্ত; নিধিবনের সখী-ভাব পরম্পরার উপাসক।" },
  { file: './rashikan/p024.jpg', hi: "श्री भगवत रसिक देव जू", bn: "শ্রী ভগবত রসিক দেব জূ", g: 'hdasi', nh: "हरिदासी (टट्टी स्थान) परम्परा के प्रसिद्ध रसिक कवि; 'अनन्य निर्णय' आदि वाणी के रचयिता।", nb: "হরিদাসী (টাট্টি স্থান) পরম্পরার প্রসিদ্ধ রসিক কবি; 'অনন্য নির্ণয়' প্রভৃতি বাণীর রচয়িতা।" },
  { file: './rashikan/p032.jpg', hi: "श्री वंशी अली जी", bn: "শ্রী বংশী অলী জী", g: 'hdasi', nh: "(1707–1765) वृन्दावन के रसिक सन्त; परम्परा में श्रीललिता सखी से दीक्षित। बरसाना में भजन के बाद वृन्दावन के ललित कुंज में रहे, जहाँ भजन-स्थली और समाधि है। शिष्य: अलबेली अली, किशोरी अली।", nb: "(১৭০৭–১৭৬৫) বৃন্দাবনের রসিক সন্ত; পরম্পরায় শ্রীললিতা সখীর কাছে দীক্ষিত। বরসানায় ভজনের পর বৃন্দাবনের ললিত কুঞ্জে থাকেন, সেখানেই ভজনস্থলী ও সমাধি। শিষ্য: অলবেলি অলি, কিশোরী অলি।", dh: "श्रीवंशी अली जी (1707–1765) वृन्दावन के रसिक सन्त थे। परम्परा में उन्हें श्रीललिता सखी से दीक्षित माना जाता है। पहले बरसाना में भजन किया, फिर वृन्दावन के ललित कुंज में रहे, जहाँ आज भी उनकी भजन-स्थली और समाधि है।\n\nउनके शिष्यों में अलबेली अली और किशोरी अली प्रसिद्ध हुए।", db: "শ্রীবংশী অলিজি (১৭০৭–১৭৬৫) বৃন্দাবনের রসিক সন্ত। ঐতিহ্যে তাঁকে শ্রীললিতা সখীর কাছে দীক্ষিত বলে মানা হয়। প্রথমে বরসানায় ভজন করেন, পরে বৃন্দাবনের ললিত কুঞ্জে বাস করেন, যেখানে আজও তাঁর ভজনস্থলী ও সমাধি আছে।\n\nতাঁর শিষ্যদের মধ্যে অলবেলি অলি ও কিশোরী অলি প্রসিদ্ধ।" },
  { file: './rashikan/p053.jpg', hi: "श्री शंकराचार्य जी", bn: "শ্রী শংকরাচার্য জী", g: 'smarta', nh: "आदि शंकराचार्य (लगभग 8वीं शताब्दी) — अद्वैत वेदान्त के प्रतिपादक और स्मार्त परम्परा के अग्रणी। उपनिषद्, गीता और ब्रह्मसूत्र पर भाष्य रचे; चारों दिशाओं में चार मठों की स्थापना की।", nb: "আদি শঙ্করাচার্য (প্রায় ৮ম শতাব্দী) — অদ্বৈত বেদান্তের প্রবক্তা ও স্মার্ত পরম্পরার অগ্রণী। উপনিষদ, গীতা ও ব্রহ্মসূত্রের ভাষ্য রচনা করেন; চার দিকে চারটি মঠ স্থাপন করেন।", dh: "आदि शंकराचार्य का जन्म केरल के कालडी ग्राम में हुआ (परम्परागत काल लगभग 8वीं शताब्दी)। बचपन में ही संन्यास लेकर वे गुरु गोविन्दपाद के शिष्य बने और अद्वैत वेदान्त की स्थापना के लिए पूरे भारत की यात्रा की।\n\nउन्होंने उपनिषद्, श्रीमद्भगवद्गीता और ब्रह्मसूत्र (प्रस्थानत्रयी) पर भाष्य लिखे तथा 'भज गोविन्दम्', 'विवेकचूडामणि' जैसे ग्रन्थ दिए। चारों दिशाओं में चार मठ — श्रृंगेरी, द्वारका, पुरी और ज्योतिर्मठ — स्थापित किए। स्मार्त परम्परा में पंचायतन-पूजा (शिव, विष्णु, देवी, सूर्य, गणेश) को उन्होंने व्यवस्थित किया, इसी कारण वे स्मार्त परम्परा के अग्रणी माने जाते हैं।", db: "আদি শঙ্করাচার্যের জন্ম কেরলের কালাডি গ্রামে (ঐতিহ্যগত কাল প্রায় ৮ম শতাব্দী)। শৈশবেই সন্ন্যাস নিয়ে তিনি গুরু গোবিন্দপাদের শিষ্য হন এবং অদ্বৈত বেদান্ত প্রতিষ্ঠায় সারা ভারত ভ্রমণ করেন।\n\nতিনি উপনিষদ, শ্রীমদ্ভগবদ্গীতা ও ব্রহ্মসূত্র (প্রস্থানত্রয়ী)-র ভাষ্য লেখেন এবং 'ভজ গোবিন্দম্', 'বিবেকচূড়ামণি'-র মতো গ্রন্থ রচনা করেন। চার দিকে চারটি মঠ — শৃঙ্গেরী, দ্বারকা, পুরী ও জ্যোতির্মঠ — স্থাপন করেন। স্মার্ত পরম্পরায় পঞ্চায়তন-পূজা (শিব, বিষ্ণু, দেবী, সূর্য, গণেশ) তিনি সুবিন্যস্ত করেন, তাই তিনি স্মার্ত পরম্পরার অগ্রণী বলে মান্য।" },
  { file: './rashikan/p031.jpg', hi: "श्री रामानुजाचार्य जी", bn: "শ্রী রামানুজাচার্য জী", g: 'vaish', nh: "(1017–1137) श्रीरंगम के महान आचार्य; विशिष्टाद्वैत वेदान्त और श्रीवैष्णव सम्प्रदाय के प्रतिष्ठापक। 'श्रीभाष्य' के रचयिता; शरणागति और सबके लिए भक्ति का उपदेश दिया।", nb: "(১০১৭–১১৩৭) শ্রীরঙ্গমের মহান আচার্য; বিশিষ্টাদ্বৈত বেদান্ত ও শ্রীবৈষ্ণব সম্প্রদায়ের প্রতিষ্ঠাতা। 'শ্রীভাষ্য'-র রচয়িতা; শরণাগতি ও সকলের জন্য ভক্তির উপদেশ দেন।", dh: "श्रीरामानुजाचार्य (परम्परागत काल 1017–1137) का जन्म तमिलनाडु के श्रीपेरुम्बुदूर में हुआ। उन्होंने यामुनाचार्य की परम्परा के आचार्यों से शिक्षा पाई और श्रीरंगम को अपना केन्द्र बनाया।\n\nवे विशिष्टाद्वैत वेदान्त के प्रतिपादक हैं — जिसके अनुसार जीव और जगत् ईश्वर के शरीर-स्वरूप हैं और भक्ति-शरणागति ही मार्ग है। 'श्रीभाष्य', 'गीताभाष्य' और 'वेदार्थसंग्रह' उनके प्रमुख ग्रन्थ हैं। परम्परा में प्रसिद्ध है कि उन्होंने गुरु से सुना गोपनीय मन्त्र मन्दिर की ऊँचाई से सबके लिए प्रकट कर दिया — सबके लिए भक्ति के द्वार खोलने का यह उदाहरण है। श्रीवैष्णव (श्री) सम्प्रदाय का विस्तार उन्हीं से हुआ।", db: "শ্রীরামানুজাচার্যের (ঐতিহ্যগত কাল ১০১৭–১১৩৭) জন্ম তামিলনাড়ুর শ্রীপেরুম্বুদূরে। যামুনাচার্যের পরম্পরার আচার্যদের কাছে শিক্ষা নিয়ে তিনি শ্রীরঙ্গমকে কেন্দ্র করেন।\n\nতিনি বিশিষ্টাদ্বৈত বেদান্তের প্রবক্তা — যার মতে জীব ও জগৎ ঈশ্বরের শরীরস্বরূপ এবং ভক্তি-শরণাগতিই পথ। 'শ্রীভাষ্য', 'গীতাভাষ্য' ও 'বেদার্থসংগ্রহ' তাঁর প্রধান গ্রন্থ। ঐতিহ্যে প্রসিদ্ধ, তিনি গুরুর কাছে শোনা গোপন মন্ত্র মন্দিরের উঁচু স্থান থেকে সবার জন্য প্রকাশ করেন — সবার জন্য ভক্তির দ্বার খোলার উদাহরণ এটি। শ্রীবৈষ্ণব (শ্রী) সম্প্রদায়ের বিস্তার তাঁর থেকেই।" },
  { file: './rashikan/p016.jpg', hi: "श्री रामानन्दाचार्य जी", bn: "শ্রী রামানন্দাচার্য জী", g: 'vaish', nh: "(14वीं–15वीं शताब्दी) काशी के वैष्णव आचार्य; रामानन्दी सम्प्रदाय के प्रवर्तक। जाति-भेद के बिना भक्ति का प्रचार किया; कबीर, रैदास आदि इनके शिष्य कहे जाते हैं।", nb: "(১৪শ–১৫শ শতাব্দী) কাশীর বৈষ্ণব আচার্য; রামানন্দী সম্প্রদায়ের প্রবর্তক। জাতিভেদ ছাড়া ভক্তির প্রচার করেন; কবীর, রৈদাস প্রমুখ তাঁর শিষ্য বলে কথিত।", dh: "स्वामी रामानन्द (लगभग 14वीं–15वीं शताब्दी) का जन्म प्रयाग में हुआ और उन्होंने काशी को अपना कार्यक्षेत्र बनाया। वे राघवानन्द जी के शिष्य थे और रामानन्दी (श्रीराम-सीता उपासक) सम्प्रदाय के प्रवर्तक कहे जाते हैं।\n\nउन्होंने भक्ति का प्रचार संस्कृत के बजाय जन-भाषा में किया और जाति-भेद के बिना सबको राम-नाम की दीक्षा दी। परम्परा में कबीर, रैदास, पीपा, धन्ना और सेना जैसे सन्त उनके शिष्य गिने जाते हैं। उत्तर भारत में भक्ति-आन्दोलन की धारा को व्यापक बनाने में उनकी बड़ी भूमिका मानी जाती है।", db: "স্বামী রামানন্দ (প্রায় ১৪শ–১৫শ শতাব্দী) প্রয়াগে জন্মান এবং কাশীকে কর্মক্ষেত্র করেন। তিনি রাঘবানন্দজির শিষ্য এবং রামানন্দী (শ্রীরাম-সীতা উপাসক) সম্প্রদায়ের প্রবর্তক বলে কথিত।\n\nতিনি সংস্কৃতের বদলে জনভাষায় ভক্তির প্রচার করেন এবং জাতিভেদ ছাড়া সবাইকে রাম-নামের দীক্ষা দেন। ঐতিহ্যে কবীর, রৈদাস, পীপা, ধন্না ও সেনার মতো সন্তরা তাঁর শিষ্য বলে গণ্য। উত্তর ভারতে ভক্তি-আন্দোলনের ধারাকে বিস্তৃত করায় তাঁর বড় ভূমিকা মানা হয়।" },
  { file: './rashikan/p074.jpg', hi: "श्री नाभादास जी", bn: "শ্রী নাভাদাস জী", g: 'vaish', nh: "रामानन्दी परम्परा के सन्त (अग्रदास जी के शिष्य); 'भक्तमाल' के रचयिता, जिसमें अनेक भक्तों का चरित्र-गान है।", nb: "রামানন্দী পরম্পরার সন্ত (অগ্রদাসজির শিষ্য); 'ভক্তমাল'-এর রচয়িতা, যেখানে বহু ভক্তের চরিত্র-গান আছে।", dh: "नाभादास जी (नाभाजी) रामानन्दी परम्परा के सन्त थे और अग्रदास जी (गलता पीठ) के शिष्य माने जाते हैं। उनकी अमर रचना 'भक्तमाल' लगभग 1600 ई. के आसपास की है।\n\nइसमें छप्पय छन्दों में सैकड़ों भक्तों और सन्तों के संक्षिप्त चरित्र गाए गए हैं, चाहे वे किसी भी जाति, सम्प्रदाय या प्रदेश के हों। बाद में प्रियादास जी की टीका ने इसे और लोकप्रिय बनाया। आज जितने भक्तों की कथाएँ हमें परम्परा से मिलती हैं, उनका बड़ा आधार भक्तमाल ही है।", db: "নাভাদাসজি (নাভাজি) রামানন্দী পরম্পরার সন্ত এবং অগ্রদাসজির (গলতা পীঠ) শিষ্য বলে মান্য। তাঁর অমর রচনা 'ভক্তমাল' প্রায় ১৬০০ খ্রিষ্টাব্দের কাছাকাছি।\n\nএতে ছপ্পয় ছন্দে শত শত ভক্ত ও সন্তের সংক্ষিপ্ত চরিত্র গীত হয়েছে, তাঁরা যে জাতি, সম্প্রদায় বা অঞ্চলেরই হোন। পরে প্রিয়াদাসজির টীকা একে আরও জনপ্রিয় করে। আজ যত ভক্তের কথা পরম্পরা থেকে আমরা পাই, তার বড় ভিত্তি ভক্তমালই।" },
  { file: './rashikan/p077.jpg', hi: "पुष्टि मार्ग संस्थापक महाप्रभु वल्लभाचार्य जी", bn: "পুষ্টি মার্গ সংস্থাপক মহাপ্রভু বল্লভাচার্য জী", g: 'vaish', nh: "(1479–1531) पुष्टिमार्ग के प्रवर्तक; शुद्धाद्वैत दर्शन के आचार्य। 'श्रीमद्भागवत सुबोधिनी' और 'अणुभाष्य' के रचयिता; गोवर्धन पर श्रीनाथ जी की सेवा-परम्परा का आरम्भ हुआ।", nb: "(১৪৭৯–১৫৩১) পুষ্টিমার্গের প্রবর্তক; শুদ্ধাদ্বৈত দর্শনের আচার্য। 'শ্রীমদ্ভাগবত সুবোধিনী' ও 'অণুভাষ্য'-র রচয়িতা; গোবর্ধনে শ্রীনাথজির সেবা-পরম্পরার সূচনা।", dh: "श्रीवल्लभाचार्य (1479–1531) का जन्म तीर्थ-यात्रा के समय चम्पारण्य (वर्तमान छत्तीसगढ़) में हुआ। काशी में शिक्षा पाकर उन्होंने शुद्धाद्वैत वेदान्त का प्रतिपादन किया; परम्परा में उनके अनुसार जगत् ब्रह्म का ही स्वरूप है और भगवान् का अनुग्रह (पुष्टि) ही भक्ति का आधार है।\n\nउन्होंने पूरे भारत में 84 स्थानों पर भागवत-पारायण किए (जो 'चौरासी बैठकें' कहलाती हैं), 'श्रीमद्भागवत सुबोधिनी', 'अणुभाष्य' और 'षोडश ग्रन्थ' रचे। गिरिराज गोवर्धन पर श्रीनाथ जी की सेवा उन्हीं से आरम्भ हुई और सूरदास जैसे कवि उनके शिष्य बने। परम्परा के अनुसार उन्होंने काशी में हनुमान घाट पर देह-लीला पूरी की।", db: "শ্রীবল্লভাচার্যের (১৪৭৯–১৫৩১) জন্ম তীর্থযাত্রার সময় চম্পারণ্যে (বর্তমান ছত্তিশগড়)। কাশীতে শিক্ষা নিয়ে তিনি শুদ্ধাদ্বৈত বেদান্তের প্রতিপাদন করেন; ঐতিহ্যে জগৎ ব্রহ্মেরই রূপ এবং ভগবানের অনুগ্রহ (পুষ্টি)-ই ভক্তির ভিত্তি।\n\nতিনি সারা ভারতে ৮৪টি স্থানে ভাগবত-পারায়ণ করেন (যা 'চৌরাশী বৈঠক' নামে পরিচিত), 'শ্রীমদ্ভাগবত সুবোধিনী', 'অণুভাষ্য' ও 'ষোড়শ গ্রন্থ' রচনা করেন। গিরিরাজ গোবর্ধনে শ্রীনাথজির সেবা তাঁর থেকেই শুরু এবং সূরদাসের মতো কবি তাঁর শিষ্য হন। ঐতিহ্য অনুসারে তিনি কাশীর হনুমান ঘাটে দেহলীলা সংবরণ করেন।" },
  { file: './rashikan/p060.jpg', hi: "निम्बार्क सम्प्रदाय संस्थापक श्री निम्बार्काचार्य जी", bn: "নিম্বার্ক সম্প্রদায় সংস্থাপক শ্রী নিম্বার্কাচার্য জী", g: 'vaish', nh: "द्वैताद्वैत (भेदाभेद) के आचार्य; सनकादि (कुमार) सम्प्रदाय के प्रवर्तक। 'वेदान्त पारिजात सौरभ' के रचयिता; श्रीराधा-कृष्ण की युगल उपासना के प्राचीन आचार्य।", nb: "দ্বৈতাদ্বৈত (ভেদাভেদ) আচার্য; সনকাদি (কুমার) সম্প্রদায়ের প্রবর্তক। 'বেদান্ত পারিজাত সৌরভ'-এর রচয়িতা; শ্রীরাধা-কৃষ্ণের যুগল উপাসনার প্রাচীন আচার্য।", dh: "श्रीनिम्बार्काचार्य द्वैताद्वैत (भेदाभेद) वेदान्त के आचार्य और सनकादि (कुमार) सम्प्रदाय के प्रवर्तक हैं। उनका मूल नाम नियमानन्द बताया जाता है। उनके समय पर मतभेद है — परम्परा उन्हें बहुत प्राचीन मानती है, जबकि विद्वान लगभग 12वीं शताब्दी का अनुमान करते हैं।\n\nप्रसिद्ध कथा है कि एक सन्ध्या को अतिथि संन्यासी के भोजन के लिए उन्होंने सूर्य को नीम के वृक्ष पर रोक लिया; तभी से 'निम्बादित्य' या 'निम्बार्क' नाम पड़ा। 'वेदान्त पारिजात सौरभ' और 'दशश्लोकी' उनकी प्रमुख रचनाएँ हैं। श्रीराधा-कृष्ण की युगल-उपासना को उन्होंने दार्शनिक आधार दिया।", db: "শ্রীনিম্বার্কাচার্য দ্বৈতাদ্বৈত (ভেদাভেদ) বেদান্তের আচার্য ও সনকাদি (কুমার) সম্প্রদায়ের প্রবর্তক। তাঁর আদি নাম নিয়মানন্দ বলা হয়। তাঁর সময় নিয়ে মতভেদ আছে — ঐতিহ্য তাঁকে অতি প্রাচীন মানে, আর পণ্ডিতেরা প্রায় ১২শ শতাব্দী অনুমান করেন।\n\nপ্রসিদ্ধ কথা: এক সন্ধ্যায় অতিথি সন্ন্যাসীর ভোজনের জন্য তিনি সূর্যকে নিমগাছে আটকে রাখেন; তখন থেকেই 'নিম্বাদিত্য' বা 'নিম্বার্ক' নাম। 'বেদান্ত পারিজাত সৌরভ' ও 'দশশ্লোকী' তাঁর প্রধান রচনা। শ্রীরাধা-কৃষ্ণের যুগল-উপাসনাকে তিনি দার্শনিক ভিত্তি দেন।" },
  { file: './rashikan/p072.jpg', hi: "श्री हरिव्यास देवाचार्य जी", bn: "শ্রী হরিব্যাস দেবাচার্য জী", g: 'vaish', nh: "निम्बार्क सम्प्रदाय के आचार्य (16वीं शताब्दी), श्रीभट्ट जी के शिष्य; 'महावाणी' के रचयिता। ब्रज में युगल उपासना के प्रचारक।", nb: "নিম্বার্ক সম্প্রদায়ের আচার্য (১৬শ শতাব্দী), শ্রীভট্টজির শিষ্য; 'মহাবাণী'-র রচয়িতা। ব্রজে যুগল উপাসনার প্রচারক।", dh: "हरिव्यास देवाचार्य (16वीं शताब्दी) निम्बार्क सम्प्रदाय के प्रसिद्ध आचार्य और श्रीभट्ट जी के शिष्य थे। उन्होंने मथुरा-वृन्दावन क्षेत्र में निम्बार्क परम्परा की युगल-उपासना का व्यापक प्रचार किया।\n\nब्रजभाषा में उनकी वाणी 'महावाणी' के नाम से जानी जाती है, और संस्कृत में 'सिद्धान्त रत्नाञ्जलि' उनका प्रसिद्ध वेदान्त-ग्रन्थ है। उनकी शिष्य-परम्परा ने ब्रज में अनेक रसिक सन्त दिए।", db: "হরিব্যাস দেবাচার্য (১৬শ শতাব্দী) নিম্বার্ক সম্প্রদায়ের প্রসিদ্ধ আচার্য এবং শ্রীভট্টজির শিষ্য। তিনি মথুরা-বৃন্দাবন অঞ্চলে নিম্বার্ক পরম্পরার যুগল-উপাসনার ব্যাপক প্রচার করেন।\n\nব্রজভাষায় তাঁর বাণী 'মহাবাণী' নামে পরিচিত, আর সংস্কৃতে 'সিদ্ধান্ত রত্নাঞ্জলি' তাঁর প্রসিদ্ধ বেদান্ত-গ্রন্থ। তাঁর শিষ্য-পরম্পরা ব্রজে বহু রসিক সন্ত উপহার দিয়েছে।" },
  { file: './rashikan/p051.jpg', hi: "श्री भट्टु देवाचार्य जी", bn: "শ্রী ভট্টু দেবাচার্য জী", g: 'vaish', nh: "श्री केशव कश्मीरी भट्ट जी के शिष्य; उनके बाद निम्बार्क सम्प्रदाय के आचार्य बने। उत्तर भारत के पहले आचार्य थे और ब्रजभाषा में वाणी रचने वाले पहले वक्ता; 'युगल शतक' प्रसिद्ध है।", nb: "শ্রী কেশব কাশ্মীরী ভট্টজির শিষ্য; তাঁর পর নিম্বার্ক সম্প্রদায়ের আচার্য হন। উত্তর ভারতের প্রথম আচার্য ও ব্রজভাষায় বাণী-রচনাকারী প্রথম বক্তা; 'যুগল শতক' প্রসিদ্ধ।", dh: "श्रीभट्ट (भट्टु) देवाचार्य निम्बार्क सम्प्रदाय के आचार्य थे — केशव कश्मीरी भट्ट जी के शिष्य। उत्तर भारत में निम्बार्क परम्परा को जन-मानस तक पहुँचाने में उनका बड़ा योगदान है।\n\nपरम्परा उन्हें ब्रजभाषा में वाणी रचने वाले पहले आचार्यों में गिनती है। उनकी रचना 'युगल शतक' श्रीराधा-कृष्ण की युगल-उपासना का सौ पदों का मधुर संग्रह है। उनके शिष्य हरिव्यास देवाचार्य ने इस धारा को आगे बढ़ाया।", db: "শ্রীভট্ট (ভট্টু) দেবাচার্য নিম্বার্ক সম্প্রদায়ের আচার্য — কেশব কাশ্মীরী ভট্টজির শিষ্য। উত্তর ভারতে নিম্বার্ক পরম্পরাকে সাধারণ মানুষের কাছে পৌঁছে দিতে তাঁর বড় অবদান।\n\nপরম্পরা তাঁকে ব্রজভাষায় বাণী রচনাকারী প্রথম আচার্যদের মধ্যে গণ্য করে। তাঁর রচনা 'যুগল শতক' শ্রীরাধা-কৃষ্ণের যুগল-উপাসনার শত পদের মধুর সংকলন। তাঁর শিষ্য হরিব্যাস দেবাচার্য এই ধারাকে এগিয়ে নিয়ে যান।" },
  { file: './rashikan/p075.jpg', hi: "श्री मध्वाचार्य जी", bn: "শ্রী মধ্বাচার্য জী", g: 'vaish', nh: "(1238–1317) उडुपी के आचार्य; द्वैत वेदान्त और ब्रह्म सम्प्रदाय के प्रवर्तक। उडुपी में श्रीकृष्ण की प्रतिष्ठा की; आगे चलकर गौड़ीय परम्परा इसी माध्व धारा से जुड़ी मानी जाती है।", nb: "(১২৩৮–১৩১৭) উডুপির আচার্য; দ্বৈত বেদান্ত ও ব্রহ্ম সম্প্রদায়ের প্রবর্তক। উডুপিতে শ্রীকৃষ্ণের প্রতিষ্ঠা করেন; পরবর্তীকালে গৌড়ীয় পরম্পরা এই মাধ্ব ধারার সঙ্গে যুক্ত বলে মান্য।", dh: "श्रीमध्वाचार्य (1238–1317) का जन्म उडुपी के निकट पाजक में हुआ; बचपन का नाम वासुदेव और संन्यास के बाद आनन्दतीर्थ। उन्होंने द्वैत वेदान्त (तत्त्ववाद) की स्थापना की, जिसमें ईश्वर, जीव और जगत् तीनों के भेद को सत्य माना गया है और विष्णु की भक्ति को परम मार्ग।\n\nवे प्रस्थानत्रयी पर भाष्य और लगभग 37 ग्रन्थों के रचयिता हैं। परम्परा के अनुसार समुद्र-तट से प्राप्त बालकृष्ण की मूर्ति उन्होंने उडुपी में प्रतिष्ठित की और अष्ट-मठों की पूजा-व्यवस्था बनाई। उन्हें वायुदेव का तृतीय अवतार माना जाता है। गौड़ीय परम्परा अपनी गुरु-परम्परा को माध्व धारा से जोड़ती है।", db: "শ্রীমধ্বাচার্যের (১২৩৮–১৩১৭) জন্ম উডুপির কাছে পাজকে; শৈশবের নাম বাসুদেব এবং সন্ন্যাসের পর আনন্দতীর্থ। তিনি দ্বৈত বেদান্ত (তত্ত্ববাদ) প্রতিষ্ঠা করেন, যেখানে ঈশ্বর, জীব ও জগতের ভেদ সত্য এবং বিষ্ণুভক্তিই পরম পথ।\n\nতিনি প্রস্থানত্রয়ীর ভাষ্য ও প্রায় ৩৭টি গ্রন্থের রচয়িতা। ঐতিহ্য অনুসারে সমুদ্রতীরে পাওয়া বালকৃষ্ণের মূর্তি তিনি উডুপিতে প্রতিষ্ঠা করেন এবং অষ্টমঠের পূজা-ব্যবস্থা গড়েন। তাঁকে বায়ুদেবের তৃতীয় অবতার মানা হয়। গৌড়ীয় পরম্পরা নিজেদের গুরু-পরম্পরাকে মাধ্ব ধারার সঙ্গে যুক্ত করে।" },
  { file: './rashikan/p014.jpg', hi: "श्री चैतन्य महाप्रभु जी", bn: "শ্রী চৈতন্য মহাপ্রভু জী", g: 'gaud', nh: "(1486–1534) नवद्वीप में जन्म; गौड़ीय वैष्णव धर्म के प्रवर्तक, राधा-कृष्ण के संयुक्त अवतार माने जाते हैं। हरिनाम-संकीर्तन का प्रचार किया; अचिन्त्य भेदाभेद दर्शन की धारा इन्हीं से चली।", nb: "(১৪৮৬–১৫৩৪) নবদ্বীপে জন্ম; গৌড়ীয় বৈষ্ণব ধর্মের প্রবর্তক, রাধা-কৃষ্ণের মিলিত অবতার বলে মান্য। হরিনাম-সংকীর্তনের প্রচার করেন; অচিন্ত্য ভেদাভেদ দর্শনের ধারা তাঁর থেকেই।", dh: "श्रीचैतन्य महाप्रभु (1486–1534) का जन्म नवद्वीप (मायापुर) में फाल्गुन पूर्णिमा को हुआ; पिता जगन्नाथ मिश्र और माता शचीदेवी। बचपन का नाम निमाई (विश्वम्भर) था; वे बहुत मेधावी विद्वान् थे।\n\nगया में ईश्वरपुरी से दीक्षा के बाद उनका जीवन कृष्ण-प्रेम में बदल गया। 24 वर्ष की आयु में उन्होंने संन्यास लिया और जीवन के अन्तिम वर्ष पुरी (नीलाचल) में बिताए। उन्होंने हरिनाम-संकीर्तन को जन-जन तक पहुँचाया, दक्षिण भारत की यात्रा की और वृन्दावन आए। उनके 'शिक्षाष्टकम्' के आठ श्लोक उनकी शिक्षा के सार हैं। अचिन्त्य-भेदाभेद दर्शन उन्हीं के उपदेश पर आधारित है, और गोस्वामियों ने उनकी आज्ञा से वृन्दावन में तीर्थ-उद्धार किया।", db: "শ্রীচৈতন্য মহাপ্রভুর (১৪৮৬–১৫৩৪) জন্ম নবদ্বীপে (মায়াপুর) ফাল্গুনী পূর্ণিমায়; পিতা জগন্নাথ মিশ্র ও মাতা শচীদেবী। শৈশবের নাম নিমাই (বিশ্বম্ভর); তিনি অত্যন্ত মেধাবী পণ্ডিত ছিলেন।\n\nগয়ায় ঈশ্বরপুরীর কাছে দীক্ষার পর তাঁর জীবন কৃষ্ণপ্রেমে বদলে যায়। ২৪ বছর বয়সে সন্ন্যাস নিয়ে জীবনের শেষ বছরগুলি পুরীতে (নীলাচল) কাটান। তিনি হরিনাম-সংকীর্তনকে ঘরে ঘরে পৌঁছে দেন, দক্ষিণ ভারত ভ্রমণ করেন এবং বৃন্দাবনে আসেন। তাঁর 'শিক্ষাষ্টকম্'-এর আটটি শ্লোক তাঁর শিক্ষার সার। অচিন্ত্য-ভেদাভেদ দর্শন তাঁর উপদেশের ওপর প্রতিষ্ঠিত, আর গোস্বামীরা তাঁর আজ্ঞায় বৃন্দাবনে তীর্থ-উদ্ধার করেন।" },
  { file: './rashikan/p068.jpg', hi: "श्री नित्यानंद महाप्रभु जी", bn: "শ্রী নিত্যানন্দ মহাপ্রভু জী", g: 'gaud', nh: "श्रीचैतन्य महाप्रभु के प्रमुख सहचर, अवधूत; बलराम के अवतार माने जाते हैं। बंगाल में हरिनाम का प्रचार किया और जगाई-मधाई जैसे पतितों का उद्धार किया।", nb: "শ্রীচৈতন্য মহাপ্রভুর প্রধান সহচর, অবধূত; বলরামের অবতার বলে মান্য। বাংলায় হরিনাম প্রচার করেন এবং জগাই-মাধাইয়ের মতো পতিতদের উদ্ধার করেন।", dh: "श्रीनित्यानन्द प्रभु का जन्म बंगाल के एकचक्रा (बीरभूम) में हुआ; पिता हाड़ाई पण्डित। बारह वर्ष की आयु में एक संन्यासी के साथ घर छोड़ा और वर्षों तीर्थ-यात्रा की, फिर नवद्वीप में चैतन्य महाप्रभु से मिले।\n\nमहाप्रभु की आज्ञा से वे हरिदास ठाकुर के साथ नगर-नगर हरिनाम का प्रचार करने निकले। प्रसिद्ध कथा है कि जगाई-मधाई नामक दो पापी भाइयों ने उन पर प्रहार किया, पर उन्होंने क्षमा करके उन्हें भक्ति दी। बाद में वे खड़दह में बसे, गृहस्थ-जीवन अपनाया और बंगाल में गौड़ीय भक्ति को जन-जन तक पहुँचाया। परम्परा में उन्हें बलराम का अवतार माना जाता है।", db: "শ্রীনিত্যানন্দ প্রভুর জন্ম বাংলার একচক্রায় (বীরভূম); পিতা হাড়াই পণ্ডিত। বারো বছর বয়সে এক সন্ন্যাসীর সঙ্গে গৃহত্যাগ করে বহু বছর তীর্থভ্রমণ করেন, তারপর নবদ্বীপে চৈতন্য মহাপ্রভুর সঙ্গে মিলিত হন।\n\nমহাপ্রভুর আজ্ঞায় তিনি হরিদাস ঠাকুরের সঙ্গে নগরে নগরে হরিনামের প্রচারে বের হন। প্রসিদ্ধ কথা: জগাই-মাধাই নামে দুই পাপী ভাই তাঁকে আঘাত করলে তিনি ক্ষমা করে তাঁদের ভক্তি দান করেন। পরে তিনি খড়দহে বসবাস করেন, গৃহস্থ-জীবন গ্রহণ করেন এবং বাংলায় গৌড়ীয় ভক্তিকে ঘরে ঘরে পৌঁছে দেন। ঐতিহ্যে তিনি বলরামের অবতার।" },
  { file: './rashikan/p081.jpg', hi: "श्री श्रीवास ठाकुर जी", bn: "শ্রী শ্রীবাস ঠাকুর জী", g: 'gaud', nh: "पंचतत्त्व में 'भक्त' स्वरूप; नारद मुनि के अवतार माने जाते हैं। नवद्वीप में इनके आँगन में महाप्रभु का नित्य कीर्तन होता था।", nb: "পঞ্চতত্ত্বে 'ভক্ত' স্বরূপ; নারদ মুনির অবতার বলে মান্য। নবদ্বীপে তাঁর আঙিনায় মহাপ্রভুর নিত্য কীর্তন হত।", dh: "श्रीवास ठाकुर पंचतत्त्व में 'भक्त-आख्य' (शुद्ध भक्त) माने जाते हैं और परम्परा में नारद मुनि के अवतार कहे जाते हैं। वे नवद्वीप में चैतन्य महाप्रभु के प्रमुख पार्षद थे और जीव-तत्त्व के रूप में सभी शुद्ध भक्तों का प्रतिनिधित्व करते हैं।\n\nउनका आँगन (श्रीवास आँगन) महाप्रभु के संकीर्तन का केन्द्र था, जहाँ रात-रात भर हरिनाम संकीर्तन होता और महाप्रभु ने अनेक लीलाएँ प्रकट कीं। श्रीवास ठाकुर की अटल श्रद्धा और भक्ति का आदर्श आज भी गौड़ीय परम्परा में पूजनीय है।", db: "শ্রীবাস ঠাকুর পঞ্চতত্ত্বে 'ভক্ত-আখ্য' (শুদ্ধ ভক্ত) বলে গণ্য এবং ঐতিহ্যে নারদ মুনির অবতার। তিনি নবদ্বীপে চৈতন্য মহাপ্রভুর প্রধান পার্ষদ ছিলেন এবং জীব-তত্ত্বরূপে সমস্ত শুদ্ধ ভক্তের প্রতিনিধিত্ব করেন।\n\nতাঁর আঙিনা (শ্রীবাস আঙিনা) ছিল মহাপ্রভুর সংকীর্তনের কেন্দ্র, যেখানে সারা রাত হরিনাম সংকীর্তন হত এবং মহাপ্রভু বহু লীলা প্রকট করেন। শ্রীবাস ঠাকুরের অটল শ্রদ্ধা ও ভক্তি আজও গৌড়ীয় পরম্পরায় পূজনীয়।" },
  { file: './rashikan/p082.jpg', hi: "श्री गदाधर पण्डित जी", bn: "শ্রী গদাধর পণ্ডিত জী", g: 'gaud', nh: "पंचतत्त्व में 'भक्त-शक्ति'; श्रीमती राधारानी की ह्लादिनी शक्ति के अवतार माने जाते हैं। पुरी में श्रीटोटा गोपीनाथ जी की सेवा की।", nb: "পঞ্চতত্ত্বে 'ভক্ত-শক্তি'; শ্রীমতী রাধারানীর হ্লাদিনী শক্তির অবতার বলে মান্য। পুরীতে শ্রীটোটা গোপীনাথজির সেবা করেন।", dh: "श्रीगदाधर पण्डित पंचतत्त्व में 'भक्त-शक्ति' हैं — परम्परा में श्रीमती राधारानी की आन्तरिक आह्लादिनी शक्ति के अवतार। वे बाल्यकाल से चैतन्य महाप्रभु के अत्यन्त प्रिय सखा और निरन्तर सहचर रहे।\n\nमहाप्रभु के संन्यास के बाद गदाधर पण्डित पुरी में रहे और समुद्र-तट पर टोटा (बगीचे) में विराजमान श्रीटोटा गोपीनाथ जी की सेवा की। यहीं वे महाप्रभु को श्रीमद्भागवत सुनाया करते थे। निर्मल, अनन्य प्रेम और सेवा-भाव की वे जीवन्त मूर्ति माने जाते हैं।", db: "শ্রীগদাধর পণ্ডিত পঞ্চতত্ত্বে 'ভক্ত-শক্তি' — ঐতিহ্যে শ্রীমতী রাধারানীর অন্তরঙ্গা হ্লাদিনী শক্তির অবতার। শৈশব থেকেই তিনি চৈতন্য মহাপ্রভুর অত্যন্ত প্রিয় সখা ও নিত্য সহচর ছিলেন।\n\nমহাপ্রভুর সন্ন্যাসের পর গদাধর পণ্ডিত পুরীতে থাকেন এবং সমুদ্রতীরের টোটায় (উদ্যানে) বিরাজমান শ্রীটোটা গোপীনাথজির সেবা করেন। সেখানেই তিনি মহাপ্রভুকে শ্রীমদ্ভাগবত শোনাতেন। নির্মল, অনন্য প্রেম ও সেবাভাবের তিনি জীবন্ত বিগ্রহ।" },
  { file: './rashikan/p083.jpg', hi: "श्री अद्वैत आचार्य जी", bn: "শ্রী অদ্বৈত আচার্য জী", g: 'gaud', nh: "पंचतत्त्व में 'भक्त-अवतार'; महाविष्णु और शिव के संयुक्त अवतार माने जाते हैं। गंगाजल और तुलसी से पूजा कर महाप्रभु के प्राकट्य की प्रार्थना की।", nb: "পঞ্চতত্ত্বে 'ভক্ত-অবতার'; মহাবিষ্ণু ও শিবের মিলিত অবতার বলে মান্য। গঙ্গাজল ও তুলসী দিয়ে পূজা করে মহাপ্রভুর আবির্ভাবের প্রার্থনা করেন।", dh: "श्रीअद्वैत आचार्य पंचतत्त्व में 'भक्त-अवतार' कहे जाते हैं और परम्परा में महाविष्णु तथा भगवान् शिव के संयुक्त अवतार माने जाते हैं। वे चैतन्य महाप्रभु से आयु में बड़े और नवद्वीप के वयोवृद्ध आचार्य थे।\n\nकथा है कि संसार को कलह और अधर्म में डूबा देखकर उन्होंने गंगाजल और तुलसी-दल से श्रीकृष्ण की आराधना की और करुणा-भरी पुकार से भगवान् को पृथ्वी पर अवतरित होने के लिए प्रार्थना की। उनकी इसी तीव्र प्रार्थना से श्रीचैतन्य महाप्रभु का प्राकट्य माना जाता है।", db: "শ্রীঅদ্বৈত আচার্য পঞ্চতত্ত্বে 'ভক্ত-অবতার' এবং ঐতিহ্যে মহাবিষ্ণু ও ভগবান শিবের মিলিত অবতার। তিনি চৈতন্য মহাপ্রভুর চেয়ে বয়সে বড় এবং নবদ্বীপের বর্ষীয়ান আচার্য ছিলেন।\n\nকথিত আছে, জগৎকে কলহ ও অধর্মে নিমজ্জিত দেখে তিনি গঙ্গাজল ও তুলসীদল দিয়ে শ্রীকৃষ্ণের আরাধনা করেন এবং করুণ আহ্বানে ভগবানকে পৃথিবীতে অবতীর্ণ হতে প্রার্থনা করেন। তাঁর সেই তীব্র প্রার্থনায় শ্রীচৈতন্য মহাপ্রভুর আবির্ভাব বলে মান্য।" },
  { file: './rashikan/p084.jpg', hi: "श्री हरिदास ठाकुर जी", bn: "শ্রী হরিদাস ঠাকুর জী", g: 'gaud', nh: "'नाम-आचार्य' — प्रतिदिन तीन लाख हरिनाम जप करने वाले। तुलसी के समीप बैठकर माला पर नाम-जप की अनुपम निष्ठा।", nb: "'নামাচার্য' — প্রতিদিন তিন লক্ষ হরিনাম জপকারী। তুলসীর পাশে বসে মালায় নাম-জপের অনুপম নিষ্ঠা।", dh: "श्रीहरिदास ठाकुर 'नामाचार्य' के नाम से प्रसिद्ध हैं। परम्परा के अनुसार वे प्रतिदिन तीन लाख हरिनाम का जप करते थे और इस नियम में कभी चूक नहीं हुई। चैतन्य महाप्रभु ने उन्हें हरिनाम-प्रचार का आचार्य बनाया।\n\nबाईस बाज़ारों में बेंत मारे जाने पर भी उन्होंने नाम-जप नहीं छोड़ा और अपने विरोधियों के लिए भी मंगल की कामना की। नित्यानन्द प्रभु के साथ उन्होंने नगर-नगर हरिनाम का प्रचार किया। तुलसी के समीप बैठकर माला पर जप करने की उनकी निष्ठा हर नाम-साधक के लिए आदर्श है।", db: "শ্রীহরিদাস ঠাকুর 'নামাচার্য' নামে প্রসিদ্ধ। ঐতিহ্য অনুসারে তিনি প্রতিদিন তিন লক্ষ হরিনাম জপ করতেন এবং এই নিয়মে কখনও ব্যতিক্রম হয়নি। চৈতন্য মহাপ্রভু তাঁকে হরিনাম-প্রচারের আচার্য করেন।\n\nবাইশ বাজারে বেত্রাঘাত সত্ত্বেও তিনি নামজপ ত্যাগ করেননি এবং বিরোধীদের জন্যও মঙ্গল কামনা করেছেন। নিত্যানন্দ প্রভুর সঙ্গে তিনি নগরে নগরে হরিনামের প্রচার করেন। তুলসীর পাশে বসে মালায় জপের তাঁর নিষ্ঠা প্রতিটি নামসাধকের আদর্শ।" },
  { file: './rashikan/p045.jpg', hi: "श्री जयदेव गोस्वामी जी", bn: "শ্রী জয়দেব গোস্বামী জী", g: 'gaud', nh: "बारहवीं शताब्दी के संस्कृत कवि; 'गीत गोविन्द' के रचयिता, जिसमें राधा-कृष्ण की मधुर लीला है। श्रीचैतन्य महाप्रभु इसका रसास्वादन करते थे।", nb: "দ্বাদশ শতাব্দীর সংস্কৃত কবি; 'গীত গোবিন্দ'-এর রচয়িতা, যেখানে রাধা-কৃষ্ণের মধুর লীলা বর্ণিত। শ্রীচৈতন্য মহাপ্রভু এটি আস্বাদন করতেন।", dh: "जयदेव गोस्वामी बारहवीं शताब्दी के संस्कृत कवि थे, जो बंगाल के राजा लक्ष्मणसेन के दरबार से जुड़े थे; जन्मस्थान केन्दुली (केन्दुबिल्व) माना जाता है। उनकी पत्नी पद्मावती भी भक्त और नृत्यांगना थीं।\n\nउनकी रचना 'गीत गोविन्द' राधा-कृष्ण की मधुर लीला का अमर काव्य है और आज भी जगन्नाथ मन्दिर (पुरी) में गाया जाता है। परम्परा में कथा है कि 'देहि पदपल्लवमुदारम्' वाला पद लिखने में जयदेव झिझके, तब स्वयं श्रीकृष्ण ने उसे पूरा किया। श्रीचैतन्य महाप्रभु भी इस काव्य का रसास्वादन करते थे। निम्बार्क परम्परा उन्हें अपना सन्त मानती है; अन्य वैष्णव परम्पराएँ भी उनका गहरा सम्मान करती हैं।", db: "জয়দেব গোস্বামী দ্বাদশ শতাব্দীর সংস্কৃত কবি, বাংলার রাজা লক্ষ্মণসেনের দরবারের সঙ্গে যুক্ত; জন্মস্থান কেন্দুলি (কেন্দুবিল্ব) বলে মানা হয়। তাঁর পত্নী পদ্মাবতীও ভক্ত ও নৃত্যশিল্পী ছিলেন।\n\nতাঁর রচনা 'গীতগোবিন্দ' রাধা-কৃষ্ণের মধুর লীলার অমর কাব্য এবং আজও পুরীর জগন্নাথ মন্দিরে গীত হয়। ঐতিহ্যে কথা আছে — একটি পদ লিখতে জয়দেব দ্বিধা করলে স্বয়ং শ্রীকৃষ্ণ তা পূর্ণ করেন। শ্রীচৈতন্য মহাপ্রভুও এই কাব্য আস্বাদন করতেন। নিম্বার্ক পরম্পরা তাঁকে নিজেদের সন্ত বলে মানে; অন্য বৈষ্ণব পরম্পরাও তাঁকে গভীর শ্রদ্ধা করে।" },
  { file: './rashikan/p043.jpg', hi: "श्री रूप गोस्वामी जी", bn: "শ্রী রূপ গোস্বামী জী", g: 'gos', nh: "षड्गोस्वामियों में प्रमुख; वृन्दावन में श्रीगोविन्ददेव जी की सेवा प्रकट की। 'भक्तिरसामृतसिन्धु' और 'उज्ज्वलनीलमणि' द्वारा गौड़ीय भक्ति-रस शास्त्र की नींव रखी।", nb: "ষড়্গোস্বামীদের প্রধান; বৃন্দাবনে শ্রীগোবিন্দদেবজির সেবা প্রকট করেন। 'ভক্তিরসামৃতসিন্ধু' ও 'উজ্জ্বলনীলমণি' দ্বারা গৌড়ীয় ভক্তি-রসশাস্ত্রের ভিত্তি স্থাপন করেন।", dh: "श्रीरूप गोस्वामी (लगभग 1489–1564) बंगाल के नवाब हुसैन शाह के उच्च अधिकारी थे; उनका नाम साकर मल्लिक था। रामकेलि में चैतन्य महाप्रभु के दर्शन पाकर उन्होंने सब छोड़ दिया और प्रयाग में महाप्रभु से भक्ति-रस की शिक्षा पाई।\n\nवृन्दावन में उन्होंने लुप्त तीर्थों का उद्धार किया और श्रीगोविन्ददेव जी का विग्रह प्रकट किया। 'भक्तिरसामृतसिन्धु', 'उज्ज्वलनीलमणि', 'उपदेशामृत', 'ललितमाधव' और 'विदग्धमाधव' उनके प्रमुख ग्रन्थ हैं, जिनसे गौड़ीय भक्ति-शास्त्र की नींव पड़ी। उनके भाई सनातन और भतीजे जीव गोस्वामी इस कार्य में सहयोगी रहे।", db: "শ্রীরূপ গোস্বামী (প্রায় ১৪৮৯–১৫৬৪) বাংলার নবাব হুসেন শাহের উচ্চপদস্থ কর্মচারী ছিলেন; তাঁর নাম ছিল সাকর মল্লিক। রামকেলিতে চৈতন্য মহাপ্রভুর দর্শন পেয়ে তিনি সব ছেড়ে দেন এবং প্রয়াগে মহাপ্রভুর কাছে ভক্তি-রসের শিক্ষা পান।\n\nবৃন্দাবনে তিনি লুপ্ত তীর্থের উদ্ধার করেন এবং শ্রীগোবিন্দদেবজির বিগ্রহ প্রকট করেন। 'ভক্তিরসামৃতসিন্ধু', 'উজ্জ্বলনীলমণি', 'উপদেশামৃত', 'ললিতমাধব' ও 'বিদগ্ধমাধব' তাঁর প্রধান গ্রন্থ, যা গৌড়ীয় ভক্তি-শাস্ত্রের ভিত্তি রচনা করে। তাঁর ভ্রাতা সনাতন ও ভ্রাতুষ্পুত্র জীব গোস্বামী এই কাজে সহযোগী ছিলেন।" },
  { file: './rashikan/p026.jpg', hi: "श्री सनातन गोस्वामी जी", bn: "শ্রী সনাতন গোস্বামী জী", g: 'gos', nh: "रूप गोस्वामी के अग्रज; वैराग्य के आदर्श। 'बृहद्भागवतामृत' के रचयिता; वृन्दावन में श्रीमदनमोहन जी की सेवा प्रकट की।", nb: "রূপ গোস্বামীর অগ্রজ; বৈরাগ্যের আদর্শ। 'বৃহদ্ভাগবতামৃত'-এর রচয়িতা; বৃন্দাবনে শ্রীমদনমোহনজির সেবা প্রকট করেন।", dh: "श्रीसनातन गोस्वामी रूप गोस्वामी के बड़े भाई थे और हुसैन शाह के दरबार में उच्च पद (दबीर खास) पर थे। 1514 में रामकेलि में चैतन्य महाप्रभु से मिलने के बाद सब त्यागकर वे वृन्दावन आए।\n\nकाशी में महाप्रभु ने उन्हें दो मास तक वैष्णव-सिद्धान्त की शिक्षा दी। उन्होंने 'हरिभक्तिविलास' (वैष्णव आचार-ग्रन्थ), 'बृहद्भागवतामृत' और 'बृहद्वैष्णवतोषणी' रचे। वृन्दावन में श्रीमदनमोहन जी की सेवा प्रकट की और माधुकरी से जीवन चलाया। वृद्धावस्था में भी नित्य गोवर्धन-परिक्रमा करते रहे।", db: "শ্রীসনাতন গোস্বামী রূপ গোস্বামীর বড় ভাই এবং হুসেন শাহের দরবারে উচ্চপদে (দবীর খাস) ছিলেন। ১৫১৪ সালে রামকেলিতে চৈতন্য মহাপ্রভুর সঙ্গে সাক্ষাতের পর সব ত্যাগ করে তিনি বৃন্দাবনে আসেন।\n\nকাশীতে মহাপ্রভু তাঁকে দুই মাস বৈষ্ণব-সিদ্ধান্ত শিক্ষা দেন। তিনি 'হরিভক্তিবিলাস' (বৈষ্ণব আচার-গ্রন্থ), 'বৃহদ্ভাগবতামৃত' ও 'বৃহদ্বৈষ্ণবতোষণী' রচনা করেন। বৃন্দাবনে শ্রীমদনমোহনজির সেবা প্রকট করেন এবং মাধুকরীতে জীবন কাটান। বৃদ্ধ বয়সেও নিত্য গোবর্ধন-পরিক্রমা করতেন।" },
  { file: './rashikan/p076.jpg', hi: "श्री रघुनाथ भट्टू गोस्वामी जी", bn: "শ্রী রঘুনাথ ভট্টু গোস্বামী জী", g: 'gos', nh: "काशी के तपन मिश्र के पुत्र; भागवत-कथा के अनन्य वक्ता, जिनकी कथा सुनकर महाप्रभु भाव-विभोर हो जाते थे। वृन्दावन में निवास।", nb: "কাশীর তপন মিশ্রের পুত্র; ভাগবত-কথার অনন্য বক্তা, যাঁর কথা শুনে মহাপ্রভু ভাববিভোর হতেন। বৃন্দাবনে বাস।", dh: "श्रीरघुनाथ भट्ट गोस्वामी काशी के तपन मिश्र के पुत्र थे। बचपन में चैतन्य महाप्रभु जब काशी आए, तब उनके घर रुके और बालक रघुनाथ ने उनकी सेवा की। बाद में पुरी में आठ मास महाप्रभु के पास रहकर वे वृन्दावन भेजे गए।\n\nवे अत्यन्त मधुर कण्ठ से श्रीमद्भागवत की कथा कहते थे। परम्परा में उनके भागवत-पाठ का रस ऐसा बताया जाता है कि रूप गोस्वामी की सभा के श्रोता भाव-विभोर हो जाते। वृन्दावन में रूप गोस्वामी के सान्निध्य में उनका जीवन बीता।", db: "শ্রীরঘুনাথ ভট্ট গোস্বামী কাশীর তপন মিশ্রের পুত্র। শৈশবে চৈতন্য মহাপ্রভু কাশী এলে তাঁদের গৃহে অবস্থান করেন এবং বালক রঘুনাথ তাঁর সেবা করেন। পরে পুরীতে আট মাস মহাপ্রভুর কাছে থেকে তিনি বৃন্দাবনে প্রেরিত হন।\n\nতিনি অতি মধুর কণ্ঠে শ্রীমদ্ভাগবতের কথা বলতেন। ঐতিহ্যে তাঁর ভাগবত-পাঠের রস এমন বলা হয় যে রূপ গোস্বামীর সভার শ্রোতারা ভাববিভোর হতেন। বৃন্দাবনে রূপ গোস্বামীর সান্নিধ্যে তাঁর জীবন কাটে।" },
  { file: './rashikan/p038.jpg', hi: "श्री जीव गोस्वामी जी", bn: "শ্রী জীব গোস্বামী জী", g: 'gos', nh: "रूप-सनातन के भतीजे; गौड़ीय दर्शन के महान आचार्य। 'षट्सन्दर्भ' के रचयिता; वृन्दावन में श्रीराधादामोदर जी की सेवा की।", nb: "রূপ-সনাতনের ভাইপো; গৌড়ীয় দর্শনের মহান আচার্য। 'ষট্সন্দর্ভ'-এর রচয়িতা; বৃন্দাবনে শ্রীরাধাদামোদরজির সেবা করেন।", dh: "श्रीजीव गोस्वामी (लगभग 1513–1598) रूप और सनातन गोस्वामी के भतीजे थे। बंगाल से वे काशी में पढ़े और फिर वृन्दावन पहुँचकर रूप गोस्वामी के शिष्य बने। वे गौड़ीय दर्शन के सबसे बड़े आचार्य माने जाते हैं।\n\nउनका 'षट्सन्दर्भ' अचिन्त्य-भेदाभेद तत्त्व का सुव्यवस्थित ग्रन्थ है; 'गोपालचम्पू', 'हरिनामामृत व्याकरण' और 'सर्वसंवादिनी' भी उनकी रचनाएँ हैं। उन्होंने वृन्दावन में श्रीराधादामोदर मन्दिर की सेवा की और श्रीनिवास आचार्य, नरोत्तम दास तथा श्यामानन्द को गोस्वामी-ग्रन्थों के साथ बंगाल-उत्कल भेजकर गौड़ीय भक्ति का प्रसार कराया।", db: "শ্রীজীব গোস্বামী (প্রায় ১৫১৩–১৫৯৮) রূপ ও সনাতন গোস্বামীর ভ্রাতুষ্পুত্র। বাংলা থেকে কাশীতে পড়াশোনা করে তিনি বৃন্দাবনে পৌঁছে রূপ গোস্বামীর শিষ্য হন। তিনি গৌড়ীয় দর্শনের শ্রেষ্ঠ আচার্য বলে মান্য।\n\nতাঁর 'ষট্সন্দর্ভ' অচিন্ত্য-ভেদাভেদ তত্ত্বের সুবিন্যস্ত গ্রন্থ; 'গোপালচম্পূ', 'হরিনামামৃত ব্যাকরণ' ও 'সর্বসংবাদিনী'-ও তাঁর রচনা। তিনি বৃন্দাবনে শ্রীরাধাদামোদর মন্দিরের সেবা করেন এবং শ্রীনিবাস আচার্য, নরোত্তম দাস ও শ্যামানন্দকে গোস্বামী-গ্রন্থ সহ বাংলা-উৎকলে পাঠিয়ে গৌড়ীয় ভক্তির প্রসার ঘটান।" },
  { file: './rashikan/p057.jpg', hi: "श्री गोपाल भट्टू गोस्वामी जी", bn: "শ্রী গোপাল ভট্টু গোস্বামী জী", g: 'gos', nh: "दक्षिण भारत के वेंकट भट्ट जी के पुत्र; वृन्दावन में शालग्राम शिला से श्रीराधारमण जी प्रकट हुए, जिनकी सेवा इन्होंने की।", nb: "দক্ষিণ ভারতের বেঙ্কট ভট্টজির পুত্র; বৃন্দাবনে শালগ্রাম শিলা থেকে শ্রীরাধারমণজি প্রকট হন, যাঁর সেবা তিনি করেন।", dh: "श्रीगोपाल भट्ट गोस्वामी (लगभग 1503–1578) का जन्म दक्षिण भारत के श्रीरंगम में वेंकट भट्ट जी के घर हुआ। चैतन्य महाप्रभु ने अपनी दक्षिण-यात्रा में चातुर्मास्य इन्हीं के घर बिताया, जिससे बालक गोपाल पर गहरा प्रभाव पड़ा।\n\nमाता-पिता के देहान्त के बाद वे वृन्दावन आए। नेपाल की काली गण्डकी से लाई शालग्राम शिलाओं में से एक से 1542 में श्रीराधारमण जी प्रकट हुए। उन्होंने 'हरिभक्तिविलास' के संकलन में सनातन गोस्वामी का सहयोग किया और 'सत्क्रियासारदीपिका' जैसे ग्रन्थ रचे। उनके वंशज सेवायत आज भी राधारमण मन्दिर की सेवा करते हैं।", db: "শ্রীগোপাল ভট্ট গোস্বামী (প্রায় ১৫০৩–১৫৭৮) দক্ষিণ ভারতের শ্রীরঙ্গমে বেঙ্কট ভট্টজির গৃহে জন্মান। চৈতন্য মহাপ্রভু দক্ষিণ-যাত্রায় চাতুর্মাস্য এঁদের গৃহেই কাটান, যার গভীর প্রভাব বালক গোপালের ওপর পড়ে।\n\nপিতামাতার দেহান্তের পর তিনি বৃন্দাবনে আসেন। নেপালের কালী গণ্ডকী থেকে আনা শালগ্রাম শিলার একটি থেকে ১৫৪২ সালে শ্রীরাধারমণজি প্রকট হন। তিনি 'হরিভক্তিবিলাস' সংকলনে সনাতন গোস্বামীকে সহযোগিতা করেন এবং 'সৎক্রিয়াসারদীপিকা'-র মতো গ্রন্থ রচনা করেন। তাঁর বংশধর সেবায়েতরা আজও রাধারমণ মন্দিরের সেবা করেন।" },
  { file: './rashikan/p052.jpg', hi: "श्री रघुनाथ दास गोस्वामी जी", bn: "শ্রী রঘুনাথ দাস গোস্বামী জী", g: 'gos', nh: "सप्तग्राम के धनी परिवार से; सब कुछ त्यागकर पुरी और फिर राधाकुण्ड में कठोर वैराग्य से भजन किया। 'स्तवावली' के रचयिता।", nb: "সপ্তগ্রামের ধনী পরিবারে জন্ম; সব ত্যাগ করে পুরী এবং পরে রাধাকুণ্ডে কঠোর বৈরাগ্যে ভজন করেন। 'স্তবাবলী'-র রচয়িতা।", dh: "श्रीरघुनाथ दास गोस्वामी (लगभग 1494–1586) सप्तग्राम (हुगली) के धनी जमींदार गोवर्धन मजूमदार के एकमात्र पुत्र थे। युवावस्था में ही चैतन्य महाप्रभु के प्रेम में सब छोड़कर वे पुरी पहुँचे, जहाँ स्वरूप दामोदर की देख-रेख में रहे और महाप्रभु से गोवर्धन-शिला और गुंजा-माला पाई।\n\nमहाप्रभु के अप्रकट होने के बाद वे वृन्दावन आकर राधाकुण्ड में रहे और अत्यन्त कठोर वैराग्य से भजन किया — परम्परा में वे प्रतिदिन बहुत थोड़ा तक्र (छाछ) लेकर नाम-जप और लीला-स्मरण में लगे रहते। 'स्तवावली', 'दानकेलिचिन्तामणि' और 'मुक्ताचरित' उनकी रचनाएँ हैं। कृष्णदास कविराज उन्हीं के सान्निध्य में रहे।", db: "শ্রীরঘুনাথ দাস গোস্বামী (প্রায় ১৪৯৪–১৫৮৬) সপ্তগ্রামের (হুগলি) ধনী জমিদার গোবর্ধন মজুমদারের একমাত্র পুত্র। যৌবনেই চৈতন্য মহাপ্রভুর প্রেমে সব ছেড়ে তিনি পুরী পৌঁছান, সেখানে স্বরূপ দামোদরের তত্ত্বাবধানে থাকেন এবং মহাপ্রভুর কাছ থেকে গোবর্ধন-শিলা ও গুঞ্জা-মালা পান।\n\nমহাপ্রভুর অপ্রকটের পর বৃন্দাবনে এসে রাধাকুণ্ডে থেকে কঠোর বৈরাগ্যে ভজন করেন — ঐতিহ্যে তিনি প্রতিদিন সামান্য ঘোল নিয়ে নামজপ ও লীলা-স্মরণে লেগে থাকতেন। 'স্তবাবলী', 'দানকেলিচিন্তামণি' ও 'মুক্তাচরিত' তাঁর রচনা। কৃষ্ণদাস কবিরাজ তাঁর সান্নিধ্যেই ছিলেন।" },
  { file: './rashikan/p022.jpg', hi: "श्री नरोत्तम दास जी", bn: "শ্রী নরোত্তম দাস জী", g: 'gos', nh: "(16वीं शताब्दी) खेतुरी के राजकुमार; लोकनाथ गोस्वामी के शिष्य। 'प्रार्थना' और 'प्रेमभक्तिचन्द्रिका' के पद रचे; खेतुरी महोत्सव से बंगाल में गौड़ीय भक्ति का प्रसार हुआ।", nb: "(১৬শ শতাব্দী) খেতুরির রাজকুমার; লোকনাথ গোস্বামীর শিষ্য। 'প্রার্থনা' ও 'প্রেমভক্তিচন্দ্রিকা'-র পদ রচনা করেন; খেতুরি মহোৎসবের মাধ্যমে বাংলায় গৌড়ীয় ভক্তির প্রসার ঘটে।", dh: "श्रीनरोत्तम दास ठाकुर (16वीं शताब्दी) बंगाल (वर्तमान बांग्लादेश) के खेतुरी के राजकुमार थे। सब त्यागकर वे वृन्दावन आए, लोकनाथ गोस्वामी के शिष्य बने और जीव गोस्वामी के पास श्रीनिवास आचार्य के साथ भक्ति-शास्त्र पढ़ा।\n\nवृन्दावन से लौटकर उन्होंने बंगाल में गौड़ीय भक्ति का प्रचार किया। खेतुरी महोत्सव (16वीं शताब्दी के उत्तरार्ध) में छह श्रीविग्रहों की प्रतिष्ठा हुई और गौड़ीय वैष्णवों का महासम्मेलन हुआ। 'प्रार्थना' और 'प्रेमभक्तिचन्द्रिका' के उनके पद आज भी गौड़ीय भक्तों के हृदय में बसे हैं; उन्होंने गराणहाटी शैली का कीर्तन चलाया।", db: "শ্রীনরোত্তম দাস ঠাকুর (১৬শ শতাব্দী) বাংলার (বর্তমান বাংলাদেশ) খেতুরির রাজকুমার। সব ত্যাগ করে তিনি বৃন্দাবনে আসেন, লোকনাথ গোস্বামীর শিষ্য হন এবং জীব গোস্বামীর কাছে শ্রীনিবাস আচার্যের সঙ্গে ভক্তি-শাস্ত্র পড়েন।\n\nবৃন্দাবন থেকে ফিরে তিনি বাংলায় গৌড়ীয় ভক্তির প্রচার করেন। খেতুরি মহোৎসবে (১৬শ শতাব্দীর শেষার্ধে) ছয় শ্রীবিগ্রহের প্রতিষ্ঠা হয় এবং গৌড়ীয় বৈষ্ণবদের মহাসম্মেলন ঘটে। 'প্রার্থনা' ও 'প্রেমভক্তিচন্দ্রিকা'-র তাঁর পদ আজও গৌড়ীয় ভক্তদের হৃদয়ে বসবাস করে; তিনি গড়ানহাটি শৈলীর কীর্তন প্রবর্তন করেন।" },
  { file: './rashikan/p004.jpg', hi: "श्री विट्ठलनाथ जी (गुसाईंजी)", bn: "শ্রী বিঠ্ঠলনাথ জী (গুসাঁইজী)", g: 'sant', nh: "(1515–1585) वल्लभाचार्य जी के पुत्र, 'गुसाईं जी'। पुष्टिमार्ग की सेवा-पद्धति का विस्तार किया और 'अष्टछाप' कवि-मण्डली की स्थापना की।", nb: "(১৫১৫–১৫৮৫) বল্লভাচার্যজির পুত্র, 'গুসাইজি'। পুষ্টিমার্গের সেবা-পদ্ধতির বিস্তার করেন এবং 'অষ্টছাপ' কবি-মণ্ডলী স্থাপন করেন।", dh: "श्रीविट्ठलनाथ जी (1515–1585), जिन्हें 'गुसाईं जी' कहा जाता है, वल्लभाचार्य जी के द्वितीय पुत्र थे। पिता के बाद उन्होंने पुष्टिमार्ग का नेतृत्व सँभाला और सेवा-पद्धति को सुव्यवस्थित किया — राग, भोग और शृंगार की जो विस्तृत परम्परा आज दिखती है, उसका बड़ा श्रेय उन्हीं को है।\n\nउन्होंने श्रीनाथ जी की सेवा को गोवर्धन पर स्थिर किया और वल्लभाचार्य जी तथा अपने शिष्यों में से आठ कवियों को चुनकर 'अष्टछाप' की स्थापना की, जिनके कीर्तन श्रीनाथ जी को सुनाए जाते थे। 'विद्वन्मण्डन' और 'शृंगाररसमण्डन' उनकी रचनाएँ हैं।", db: "শ্রীবিট্ঠলনাথজি (১৫১৫–১৫৮৫), যাঁকে 'গুসাঁইজি' বলা হয়, বল্লভাচার্যজির দ্বিতীয় পুত্র। পিতার পর তিনি পুষ্টিমার্গের নেতৃত্ব নেন এবং সেবা-পদ্ধতিকে সুসংগঠিত করেন — রাগ, ভোগ ও শৃঙ্গারের যে বিস্তৃত পরম্পরা আজ দেখা যায়, তার বড় কৃতিত্ব তাঁরই।\n\nতিনি শ্রীনাথজির সেবা গোবর্ধনে স্থির করেন এবং বল্লভাচার্যজি ও নিজের শিষ্যদের মধ্য থেকে আটজন কবিকে বেছে 'অষ্টছাপ' স্থাপন করেন, যাঁদের কীর্তন শ্রীনাথজিকে শোনানো হতো। 'বিদ্বন্মণ্ডন' ও 'শৃঙ্গাররসমণ্ডন' তাঁর রচনা।" },
  { file: './rashikan/p071.jpg', hi: "श्री सूरदास जी", bn: "শ্রী সূরদাস জী", g: 'sant', nh: "अष्टछाप के प्रमुख कवि; 'सूरसागर' के रचयिता। वात्सल्य और भक्ति के अनुपम गायक, श्रीनाथ जी के कीर्तनकार; परम्परा में जन्मान्ध माने जाते हैं।", nb: "অষ্টছাপের প্রধান কবি; 'সূরসাগর'-এর রচয়িতা। বাৎসল্য ও ভক্তির অনুপম গায়ক, শ্রীনাথজির কীর্তনকার; পরম্পরায় জন্মান্ধ বলে মান্য।", dh: "सूरदास जी (लगभग 15वीं–16वीं शताब्दी) ब्रजभाषा के महान कवि हैं; दिल्ली के निकट सीही ग्राम में जन्म माना जाता है। परम्परा में वे जन्मान्ध थे, यद्यपि कुछ मत इससे भिन्न हैं। बचपन में गाते हुए वे ब्रज के गऊघाट (मथुरा) पहुँचे, जहाँ वल्लभाचार्य जी ने उन्हें दीक्षा दी और श्रीनाथ जी के कीर्तन की सेवा सौंपी।\n\n'सूरसागर' उनकी प्रमुख रचना है, जिसमें श्रीकृष्ण की बाल-लीला और गोपी-विरह के अद्भुत पद हैं; 'सूरसारावली' और 'साहित्यलहरी' भी उनकी कृतियाँ मानी जाती हैं। हिन्दी साहित्य में उन्हें वात्सल्य रस का अप्रतिम कवि कहा जाता है।", db: "সূরদাসজি (প্রায় ১৫শ–১৬শ শতাব্দী) ব্রজভাষার মহান কবি; দিল্লির কাছে সীহী গ্রামে জন্ম বলে মানা হয়। ঐতিহ্যে তিনি জন্মান্ধ ছিলেন, যদিও কিছু মত ভিন্ন। শৈশবে গান গাইতে গাইতে তিনি মথুরার গউঘাটে পৌঁছান, যেখানে বল্লভাচার্যজি তাঁকে দীক্ষা দেন এবং শ্রীনাথজির কীর্তন-সেবা অর্পণ করেন।\n\n'সূরসাগর' তাঁর প্রধান রচনা, যেখানে শ্রীকৃষ্ণের বাল্যলীলা ও গোপী-বিরহের অপূর্ব পদ রয়েছে; 'সূরসারাবলী' ও 'সাহিত্যলহরী'-ও তাঁর রচনা বলে মানা হয়। হিন্দি সাহিত্যে তিনি বাৎসল্য রসের অতুলনীয় কবি।" },
  { file: './rashikan/p039.jpg', hi: "श्री कुंभनदास जी", bn: "শ্রী কুম্ভনদাস জী", g: 'sant', nh: "अष्टछाप कवि; गोवर्धन क्षेत्र में निवास। निर्धन रहकर भी अकबर के दरबार का निमन्त्रण स्वीकार नहीं किया — निःस्पृह भक्ति के आदर्श।", nb: "অষ্টছাপ কবি; গোবর্ধন অঞ্চলে বাস। দারিদ্র্য সত্ত্বেও আকবরের দরবারের আমন্ত্রণ গ্রহণ করেননি — নিঃস্পৃহ ভক্তির আদর্শ।", dh: "कुम्भनदास जी (लगभग 1468–1582) अष्टछाप के कवि और गोवर्धन के निकट पारसोली ग्राम के किसान थे। वे वल्लभाचार्य जी के शिष्य थे और श्रीनाथ जी के सामने कीर्तन गाते थे।\n\nप्रसिद्ध है कि अकबर ने उन्हें फतेहपुर सीकरी बुलवाया; पर राज-दरबार में जाना उन्हें बोझ लगा और उन्होंने पद में कहा कि सीकरी आने-जाने में जूते घिस गए, सन्तों का राजदरबार से क्या काम। कठिन निर्धनता में भी उन्होंने किसी का दान नहीं लिया — सच्ची निःस्पृह भक्ति का उदाहरण। उनके पुत्र चतुर्भुजदास भी अष्टछाप के कवि हुए।", db: "কুম্ভনদাসজি (প্রায় ১৪৬৮–১৫৮২) অষ্টছাপের কবি এবং গোবর্ধনের কাছে পারসোলী গ্রামের কৃষক ছিলেন। তিনি বল্লভাচার্যজির শিষ্য এবং শ্রীনাথজির সামনে কীর্তন গাইতেন।\n\nপ্রসিদ্ধ কথা: আকবর তাঁকে ফতেহপুর সিক্রিতে ডেকে পাঠান; কিন্তু রাজদরবারে যাওয়া তাঁর কাছে বোঝা মনে হয়, তিনি পদে বলেন সিক্রি যাতায়াতে জুতো ক্ষয়ে গেছে, সন্তদের রাজদরবারে কী কাজ। কঠিন দারিদ্র্যেও তিনি কারও দান নেননি — প্রকৃত নিঃস্পৃহ ভক্তির উদাহরণ। তাঁর পুত্র চতুর্ভুজদাসও অষ্টছাপের কবি।" },
  { file: './rashikan/p000.jpg', hi: "श्री परमानंद दास जी", bn: "শ্রী পরমানন্দ দাস জী", g: 'sant', nh: "अष्टछाप कवि; कन्नौज क्षेत्र में जन्म। पुष्टिमार्ग के मधुर कीर्तनकार, अनेक पदों के रचयिता।", nb: "অষ্টছাপ কবি; কনৌজ অঞ্চলে জন্ম। পুষ্টিমার্গের মধুর কীর্তনকার, বহু পদের রচয়িতা।", dh: "परमानन्ददास जी (लगभग 1493–1583) अष्टछाप के प्रमुख कवि थे; कन्नौज क्षेत्र में जन्म माना जाता है। वे वल्लभाचार्य जी के शिष्य बने और श्रीनाथ जी के कीर्तन की सेवा की।\n\nउनके पदों का संग्रह 'परमानन्दसागर' कहलाता है, जिसमें सैकड़ों पद श्रीकृष्ण की बाल-लीला, रास और विरह पर हैं।", db: "পরমানন্দদাসজি (প্রায় ১৪৯৩–১৫৮৩) অষ্টছাপের প্রধান কবি; কনৌজ অঞ্চলে জন্ম বলে মানা হয়। তিনি বল্লভাচার্যজির শিষ্য হন এবং শ্রীনাথজির কীর্তন-সেবা করেন।\n\nতাঁর পদের সংকলন 'পরমানন্দসাগর' নামে পরিচিত, যেখানে শত শত পদ শ্রীকৃষ্ণের বাল্যলীলা, রাস ও বিরহ নিয়ে।" },
  { file: './rashikan/p033.jpg', hi: "श्री कृष्णदास जी", bn: "শ্রী কৃষ্ণদাস জী", g: 'sant', nh: "अष्टछाप कवि; श्रीनाथ जी मन्दिर के अधिकारी के रूप में प्रसिद्ध, सेवा-व्यवस्था के कुशल संचालक और पदकार।", nb: "অষ্টছাপ কবি; শ্রীনাথজির মন্দিরের অধিকারী হিসেবে প্রসিদ্ধ, সেবা-ব্যবস্থার দক্ষ পরিচালক ও পদকার।", dh: "कृष्णदास जी (अधिकारी) अष्टछाप के कवि थे। गुजरात क्षेत्र में जन्मे कृष्णदास को वल्लभाचार्य जी ने श्रीनाथ जी के मन्दिर का अधिकारी (प्रबन्धक) नियुक्त किया।\n\nवे सेवा-व्यवस्था में कठोर अनुशासन के लिए जाने जाते थे और पदों की रचना भी करते थे; 'जुगल मान चरित्र' जैसी रचनाएँ उनके नाम से मिलती हैं। उनकी निष्ठा के कारण श्रीनाथ जी की सेवा की व्यवस्थाएँ दृढ़ हुईं।", db: "কৃষ্ণদাসজি (অধিকারী) অষ্টছাপের কবি। গুজরাট অঞ্চলে জন্মানো কৃষ্ণদাসকে বল্লভাচার্যজি শ্রীনাথজির মন্দিরের অধিকারী (ব্যবস্থাপক) নিযুক্ত করেন।\n\nতিনি সেবা-ব্যবস্থায় কঠোর শৃঙ্খলার জন্য পরিচিত ছিলেন এবং পদও রচনা করতেন; 'জুগল মান চরিত্র'-এর মতো রচনা তাঁর নামে পাওয়া যায়। তাঁর নিষ্ঠায় শ্রীনাথজির সেবা-ব্যবস্থা সুদৃঢ় হয়।" },
  { file: './rashikan/p005.jpg', hi: "श्री गोविन्द स्वामी जी", bn: "শ্রী গোবিন্দ স্বামী জী", g: 'sant', nh: "अष्टछाप कवि; गोवर्धन के निकट कदम्बखण्डी में निवास। श्रेष्ठ संगीतज्ञ, श्रीनाथ जी को कीर्तन सुनाते थे।", nb: "অষ্টছাপ কবি; গোবর্ধনের কাছে কদম্বখণ্ডীতে বাস। শ্রেষ্ঠ সংগীতজ্ঞ, শ্রীনাথজিকে কীর্তন শোনাতেন।", dh: "गोविन्दस्वामी जी (लगभग 1505–1585) अष्टछाप के श्रेष्ठ कवि और संगीतज्ञ थे। गुसाईं विट्ठलनाथ जी से दीक्षा लेकर वे गोवर्धन के निकट कदम्बखण्डी में रहे और श्रीनाथ जी को कीर्तन सुनाते रहे।\n\nपरम्परा में प्रसिद्ध है कि श्रीनाथ जी उनके साथ गुल्ली-डण्डा खेलते थे। उनके पद संगीत की दृष्टि से अत्यन्त समृद्ध माने जाते हैं और आज भी पुष्टिमार्ग के कीर्तन में गाए जाते हैं।", db: "গোবিন্দস্বামীজি (প্রায় ১৫০৫–১৫৮৫) অষ্টছাপের শ্রেষ্ঠ কবি ও সংগীতজ্ঞ। গুসাঁই বিট্ঠলনাথজির কাছে দীক্ষা নিয়ে তিনি গোবর্ধনের কাছে কদম্বখণ্ডীতে থাকতেন এবং শ্রীনাথজিকে কীর্তন শোনাতেন।\n\nঐতিহ্যে প্রসিদ্ধ, শ্রীনাথজি তাঁর সঙ্গে গুল্লি-ডান্ডা খেলতেন। তাঁর পদ সংগীতের দিক থেকে অত্যন্ত সমৃদ্ধ মানা হয় এবং আজও পুষ্টিমার্গের কীর্তনে গাওয়া হয়।" },
  { file: './rashikan/p030.jpg', hi: "श्री चतुर्भुज दास जी", bn: "শ্রী চতুর্ভুজ দাস জী", g: 'sant', nh: "अष्टछाप कवि; कुम्भनदास जी के पुत्र, पुष्टिमार्ग के पदकार।", nb: "অষ্টছাপ কবি; কুম্ভনদাসজির পুত্র, পুষ্টিমার্গের পদকার।", dh: "चतुर्भुजदास जी अष्टछाप के कवि और कुम्भनदास जी के पुत्र थे। वे गुसाईं विट्ठलनाथ जी के शिष्य बने और पिता की तरह श्रीनाथ जी की कीर्तन-सेवा की।\n\n'द्वादश यश', 'भक्ति प्रताप' और 'हितजू को मंगल' जैसी रचनाएँ उनके नाम से मिलती हैं। उनके पद सरल भाषा में श्रीकृष्ण की लीला और भक्ति की महिमा गाते हैं।", db: "চতুর্ভুজদাসজি অষ্টছাপের কবি এবং কুম্ভনদাসজির পুত্র। তিনি গুসাঁই বিট্ঠলনাথজির শিষ্য হন এবং পিতার মতো শ্রীনাথজির কীর্তন-সেবা করেন।\n\n'দ্বাদশ যশ', 'ভক্তি প্রতাপ' ও 'হিতজূ কো মঙ্গল'-এর মতো রচনা তাঁর নামে পাওয়া যায়। তাঁর পদ সহজ ভাষায় শ্রীকৃষ্ণের লীলা ও ভক্তির মহিমা গায়।" },
  { file: './rashikan/p008.jpg', hi: "श्री छीत स्वामी जी", bn: "শ্রী ছীত স্বামী জী", g: 'sant', nh: "अष्टछाप कवि; मथुरा में जन्म, गोस्वामी विट्ठलनाथ जी के शिष्य। प्रारम्भ में चंचल स्वभाव के थे, सम्प्रदाय में आकर उच्च कोटि के भक्त-कवि बने।", nb: "অষ্টছাপ কবি; মথুরায় জন্ম, গোস্বামী বিট্ঠলনাথজির শিষ্য। প্রথমে চঞ্চল স্বভাবের ছিলেন, সম্প্রদায়ে এসে উচ্চ স্তরের ভক্ত-কবি হন।", dh: "छीत स्वामी जी (लगभग 1515–1585) अष्टछाप के कवि थे। मथुरा के चौबे ब्राह्मण परिवार में जन्म हुआ; परम्परा के अनुसार युवावस्था में वे उद्दण्ड स्वभाव के थे, पर गुसाईं विट्ठलनाथ जी की शरण में आकर उच्च कोटि के भक्त-कवि बन गए।\n\nउन्होंने गोवर्धन में रहकर श्रीनाथ जी की सेवा और कीर्तन किया। उनके पदों में श्रीकृष्ण के बाल-रूप और शृंगार का मधुर वर्णन मिलता है।", db: "ছীত স্বামীজি (প্রায় ১৫১৫–১৫৮৫) অষ্টছাপের কবি। মথুরার চৌবে ব্রাহ্মণ পরিবারে জন্ম; ঐতিহ্য অনুসারে যৌবনে তিনি উদ্ধত স্বভাবের ছিলেন, কিন্তু গুসাঁই বিট্ঠলনাথজির শরণ নিয়ে উচ্চস্তরের ভক্ত-কবি হয়ে ওঠেন।\n\nগোবর্ধনে থেকে তিনি শ্রীনাথজির সেবা ও কীর্তন করেন। তাঁর পদে শ্রীকৃষ্ণের বাল্যরূপ ও শৃঙ্গারের মধুর বর্ণনা পাওয়া যায়।" },
  { file: './rashikan/p019.jpg', hi: "श्री नंददास जी", bn: "শ্রী নন্দদাস জী", g: 'sant', nh: "अष्टछाप कवि; 'रासपंचाध्यायी' और 'भँवरगीत' के रचयिता — भागवत की रासलीला और उद्धव-गोपी संवाद को काव्य में ढाला।", nb: "অষ্টছাপ কবি; 'রাসপঞ্চাধ্যায়ী' ও 'ভ্রমরগীত'-এর রচয়িতা — ভাগবতের রাসলীলা ও উদ্ধব-গোপী সংবাদ কাব্যে রূপ দেন।", dh: "नन्ददास जी (लगभग 1533–1586) अष्टछाप के विद्वान् कवि थे। कुछ परम्पराओं में उन्हें गोस्वामी तुलसीदास जी का साथी या सम्बन्धी माना जाता है। वे गुसाईं विट्ठलनाथ जी के शिष्य बने।\n\n'रासपंचाध्यायी' में उन्होंने भागवत की रासलीला को और 'भँवरगीत' में उद्धव-गोपी संवाद को काव्य का रूप दिया; 'सिद्धान्तपंचाध्यायी', 'रूपमंजरी' और 'अनेकार्थमंजरी' भी उनकी रचनाएँ हैं। विद्वत्ता के कारण कहा गया कि कवियों में 'नन्ददास' जड़िया (रत्नजटित) हैं।", db: "নন্দদাসজি (প্রায় ১৫৩৩–১৫৮৬) অষ্টছাপের বিদ্বান কবি। কিছু পরম্পরায় তাঁকে গোস্বামী তুলসীদাসজির সঙ্গী বা আত্মীয় মানা হয়। তিনি গুসাঁই বিট্ঠলনাথজির শিষ্য হন।\n\n'রাসপঞ্চাধ্যায়ী'-তে তিনি ভাগবতের রাসলীলাকে এবং 'ভ্রমরগীত'-এ উদ্ধব-গোপী সংবাদকে কাব্যরূপ দেন; 'সিদ্ধান্তপঞ্চাধ্যায়ী', 'রূপমঞ্জরী' ও 'অনেকার্থমঞ্জরী'-ও তাঁর রচনা। পাণ্ডিত্যের জন্য বলা হতো কবিদের মধ্যে 'নন্দদাস' রত্নখচিত।" },
  { file: './rashikan/p050.jpg', hi: "भक्त रसखान जी", bn: "ভক্ত রসখান জী", g: 'sant', nh: "(16वीं शताब्दी) मुसलमान कुल में जन्मे कृष्णभक्त कवि; ब्रज में निवास। 'सुजान रसखान' और 'प्रेमवाटिका' उनकी प्रसिद्ध रचनाएँ हैं।", nb: "(১৬শ শতাব্দী) মুসলিম বংশে জন্মানো কৃষ্ণভক্ত কবি; ব্রজে বাস। 'সুজান রসখান' ও 'প্রেমবাটিকা' তাঁর প্রসিদ্ধ রচনা।", dh: "रसखान (सय्यद इब्राहीम, लगभग 16वीं शताब्दी) का जन्म पठान परिवार में हुआ; वे पहले जागीरदार थे। परम्परा में कथा है कि कृष्ण-प्रेम में डूबकर वे वृन्दावन-गोकुल पहुँचे और गुसाईं विट्ठलनाथ जी से दीक्षा ली।\n\n'सुजान रसखान' और 'प्रेमवाटिका' में उनके सवैये और कवित्त श्रीकृष्ण के प्रति सहज, माधुर्य-भरे प्रेम को गाते हैं, जिनमें अगले जन्म में भी ब्रज में रहने की कामना बार-बार झलकती है। उनकी समाधि महावन (गोकुल) में मानी जाती है।", db: "রসখান (সৈয়দ ইব্রাহিম, প্রায় ১৬শ শতাব্দী) পাঠান পরিবারে জন্মান; আগে তিনি জায়গিরদার ছিলেন। ঐতিহ্যে কথা আছে, কৃষ্ণপ্রেমে ডুবে তিনি বৃন্দাবন-গোকুলে পৌঁছান এবং গুসাঁই বিট্ঠলনাথজির কাছে দীক্ষা নেন।\n\n'সুজান রসখান' ও 'প্রেমবাটিকা'-য় তাঁর সবৈয়া ও কবিত্ত শ্রীকৃষ্ণের প্রতি সহজ, মাধুর্যভরা প্রেম গায়, যেখানে পরজন্মেও ব্রজে থাকার আকাঙ্ক্ষা বারবার ফুটে ওঠে। তাঁর সমাধি মহাবনে (গোকুল) বলে মানা হয়।" },
  { file: './rashikan/p001.jpg', hi: "गो. श्री तुलसी दास जी", bn: "গো. শ্রী তুলসী দাস জী", g: 'sant', nh: "(1532–1623) 'श्रीरामचरितमानस' के रचयिता; रामभक्ति के महान कवि। 'विनय पत्रिका', 'कवितावली' आदि भी आपकी रचनाएँ हैं।", nb: "(১৫৩২–১৬২৩) 'শ্রীরামচরিতমানস'-এর রচয়িতা; রামভক্তির মহান কবি। 'বিনয় পত্রিকা', 'কবিতাবলী' প্রভৃতিও আপনার রচনা।", dh: "गोस्वामी तुलसीदास (1532–1623) का जन्म राजापुर (चित्रकूट) या सोरों माना जाता है। बचपन कष्ट में बीता; गुरु नरहरिदास जी ने उन्हें राम-कथा सुनाई। परम्परा में पत्नी रत्नावली की एक बात ने उनके जीवन की दिशा बदल दी।\n\nउन्होंने संवत् 1631 (लगभग 1574) में अयोध्या में 'श्रीरामचरितमानस' का आरम्भ किया; मान्यता है कि इसका बड़ा भाग काशी में पूरा हुआ। 'हनुमान चालीसा', 'विनय पत्रिका', 'कवितावली' और 'दोहावली' भी उनकी देन हैं। रामलीला की परम्परा को जनप्रिय बनाने में भी उनकी बड़ी भूमिका मानी जाती है।", db: "গোস্বামী তুলসীদাসের (১৫৩২–১৬২৩) জন্ম রাজাপুর (চিত্রকূট) বা সোরোঁ বলে মানা হয়। শৈশব কষ্টে কাটে; গুরু নরহরিদাসজি তাঁকে রাম-কথা শোনান। ঐতিহ্যে পত্নী রত্নাবলীর একটি কথা তাঁর জীবনের দিক বদলে দেয়।\n\nতিনি সংবৎ ১৬৩১ (প্রায় ১৫৭৪) সালে অযোধ্যায় 'শ্রীরামচরিতমানস' রচনা শুরু করেন; মান্যতা, এর বড় অংশ কাশীতে সম্পূর্ণ হয়। 'হনুমান চালিসা', 'বিনয় পত্রিকা', 'কবিতাবলী' ও 'দোহাবলী'-ও তাঁর দান। রামলীলার পরম্পরাকে জনপ্রিয় করতেও তাঁর বড় ভূমিকা মানা হয়।" },
  { file: './rashikan/p037.jpg', hi: "संत कबीर दास जी", bn: "সন্ত কবীর দাস জী", g: 'sant', nh: "(15वीं शताब्दी) काशी के सन्त-कवि; निर्गुण भक्ति और सामाजिक समरसता के प्रबल स्वर। साखी, सबद और रमैनी 'बीजक' में संकलित हैं।", nb: "(১৫শ শতাব্দী) কাশীর সন্ত-কবি; নির্গুণ ভক্তি ও সামাজিক সম্প্রীতির প্রবল কণ্ঠ। সাখী, শব্দ ও রমৈনী 'বীজক'-এ সংকলিত।", dh: "सन्त कबीर (15वीं शताब्दी) काशी में जुलाहा परिवार में पले। परम्परा में वे स्वामी रामानन्द के शिष्य माने जाते हैं। वे निर्गुण भक्ति के प्रबल स्वर थे — मूर्ति-पूजा, जाति-भेद और बाह्य आडम्बर पर उन्होंने सीधी-सरल भाषा में प्रश्न उठाए।\n\nउनकी वाणी साखी, सबद और रमैनी के रूप में 'बीजक' में संकलित है; कुछ पद गुरु ग्रन्थ साहिब में भी हैं। कथा है कि उनके निधन (मगहर) के बाद हिन्दू और मुसलमान दोनों अपने-अपने रीति से अन्तिम संस्कार चाहते थे, पर कफ़न हटाने पर वहाँ केवल फूल मिले। हिन्दू-मुस्लिम एकता के प्रतीक के रूप में उन्हें स्मरण किया जाता है।", db: "সন্ত কবীর (১৫শ শতাব্দী) কাশীতে তাঁতি পরিবারে বড় হন। ঐতিহ্যে তিনি স্বামী রামানন্দের শিষ্য বলে মান্য। তিনি নির্গুণ ভক্তির প্রবল কণ্ঠ — মূর্তিপূজা, জাতিভেদ ও বাহ্যিক আড়ম্বর নিয়ে সহজ ভাষায় সরাসরি প্রশ্ন তোলেন।\n\nতাঁর বাণী সাখী, শব্দ ও রমৈনী রূপে 'বীজক'-এ সংকলিত; কিছু পদ গুরু গ্রন্থ সাহিবেও আছে। কথিত আছে মগহরে তাঁর দেহান্তের পর হিন্দু ও মুসলমান উভয় পক্ষ নিজ নিজ রীতিতে সৎকার চাইলে আচ্ছাদন সরাতেই সেখানে কেবল ফুল পাওয়া যায়। হিন্দু-মুসলিম ঐক্যের প্রতীক হিসেবে তাঁকে স্মরণ করা হয়।" },
  { file: './rashikan/p015.jpg', hi: "श्री रविदास जी महाराज", bn: "শ্রী রবিদাস জী মহারাজ", g: 'sant', nh: "काशी के सन्त, रामानन्द जी के शिष्य कहे जाते हैं। सरल भाषा में भक्ति और समता का उपदेश दिया; इनकी वाणी गुरु ग्रन्थ साहिब में भी सम्मिलित है।", nb: "কাশীর সন্ত, রামানন্দজির শিষ্য বলে কথিত। সহজ ভাষায় ভক্তি ও সাম্যের উপদেশ দেন; তাঁর বাণী গুরু গ্রন্থ সাহিবেও অন্তর্ভুক্ত।", dh: "सन्त रैदास (रविदास, 15वीं–16वीं शताब्दी) काशी में चर्मकार परिवार में जन्मे और अपने पैतृक कार्य को ही सेवा मानकर भक्ति करते रहे। परम्परा में वे स्वामी रामानन्द के शिष्य गिने जाते हैं।\n\nउनके पदों का मूल भाव है कि ईश्वर-भक्ति में जन्म या जाति का कोई भेद नहीं; उन्होंने 'बेगमपुरा' (दुःख-रहित नगर) की कल्पना की। उनके चालीस से अधिक पद गुरु ग्रन्थ साहिब में सम्मिलित हैं। परम्परा में मीराबाई उन्हें अपना गुरु मानती थीं।", db: "সন্ত রৈদাস (রবিদাস, ১৫শ–১৬শ শতাব্দী) কাশীতে চর্মকার পরিবারে জন্মান এবং পৈতৃক কাজকেই সেবা মনে করে ভক্তি করতেন। ঐতিহ্যে তিনি স্বামী রামানন্দের শিষ্য বলে গণ্য।\n\nতাঁর পদের মূল ভাব — ঈশ্বর-ভক্তিতে জন্ম বা জাতির কোনো ভেদ নেই; তিনি 'বেগমপুরা' (দুঃখহীন নগর)-র কল্পনা করেন। তাঁর চল্লিশটিরও বেশি পদ গুরু গ্রন্থ সাহিবে অন্তর্ভুক্ত। ঐতিহ্যে মীরাবাঈ তাঁকে নিজের গুরু মানতেন।" },
  { file: './rashikan/p048.jpg', hi: "भक्तिमती मीरा बाई जी", bn: "ভক্তিমতী মীরা বাঈ জী", g: 'sant', nh: "(16वीं शताब्दी) मेवाड़ की राजकुमारी; गिरिधर गोपाल की अनन्य उपासिका। उनके पदों में मधुर-भाव की प्रेमोन्मत्त भक्ति झलकती है; वृन्दावन और द्वारका में रहीं।", nb: "(১৬শ শতাব্দী) মেবারের রাজকন্যা; গিরিধর গোপালের অনন্য উপাসিকা। তাঁর পদে মধুর-ভাবের প্রেমোন্মত্ত ভক্তি ফুটে ওঠে; বৃন্দাবন ও দ্বারকায় ছিলেন।", dh: "मीराबाई (लगभग 1498–1547) का जन्म मेड़ता (राजस्थान) के राठौड़ परिवार में हुआ। बचपन से ही वे श्रीकृष्ण (गिरधर गोपाल) को अपना पति मानती थीं। मेवाड़ में विवाह के बाद पति के निधन और ससुराल के विरोध के बावजूद उनकी भक्ति अडिग रही।\n\nवे वृन्दावन और फिर द्वारका गईं, जहाँ परम्परा के अनुसार वे श्रीरणछोड़ जी में विलीन हो गईं। उनके पद राजस्थानी-ब्रज मिश्रित भाषा में हैं और माधुर्य-भक्ति, विरह और पूर्ण समर्पण से भरे हैं। परम्परा में कहा जाता है कि रैदास जी उनके गुरु थे।", db: "মীরাবাঈ (প্রায় ১৪৯৮–১৫৪৭) রাজস্থানের মেড়তার রাঠোর পরিবারে জন্মান। শৈশব থেকেই তিনি শ্রীকৃষ্ণকে (গিরিধর গোপাল) নিজের স্বামী মানতেন। মেবারে বিবাহের পর স্বামীর মৃত্যু ও শ্বশুরবাড়ির বিরোধ সত্ত্বেও তাঁর ভক্তি অটল ছিল।\n\nতিনি বৃন্দাবন এবং পরে দ্বারকায় যান, যেখানে ঐতিহ্য অনুসারে তিনি শ্রীরণছোড়জির বিগ্রহে বিলীন হন। তাঁর পদ রাজস্থানি-ব্রজ মিশ্র ভাষায় এবং মাধুর্য-ভক্তি, বিরহ ও পূর্ণ সমর্পণে ভরা। ঐতিহ্যে বলা হয় রৈদাস তাঁর গুরু ছিলেন।" },
  { file: './rashikan/p059.jpg', hi: "भक्त करमैती बाई जी", bn: "ভক্ত করমৈতী বাঈ জী", g: 'sant', nh: "खण्डेला (राजस्थान) की कृष्ण-भक्त; संसार त्यागकर वृन्दावन आयीं और भजन में लीन रहीं।", nb: "খণ্ডেলা (রাজস্থান)-র কৃষ্ণভক্ত; সংসার ত্যাগ করে বৃন্দাবনে এসে ভজনে লীন থাকেন।" },
  { file: './rashikan/p070.jpg', hi: "भक्त रानी रत्नावती जी", bn: "ভক্ত রানী রত্নাবতী জী", g: 'sant', nh: "कृष्ण-भक्त रानी; राजसी वैभव के बीच अनन्य भक्ति के लिए स्मरण की जाती हैं।", nb: "কৃষ্ণভক্ত রানি; রাজকীয় বৈভবের মাঝেও অনন্য ভক্তির জন্য স্মরণীয়।" },
  { file: './rashikan/p011.jpg', hi: "श्री नरसी मेहता जी", bn: "শ্রী নরসী মেহতা জী", g: 'sant', nh: "(15वीं शताब्दी) गुजरात के आदिकवि, जूनागढ़ के कृष्णभक्त। 'वैष्णव जन तो तेने कहिये' जैसे भजनों के रचयिता माने जाते हैं।", nb: "(১৫শ শতাব্দী) গুজরাটের আদি কবি, জুনাগড়ের কৃষ্ণভক্ত। 'বৈষ্ণব জন তো তেনে কহিয়ে'-র মতো ভজনের রচয়িতা বলে মান্য।", dh: "नरसी मेहता (15वीं शताब्दी) गुजरात के जूनागढ़ क्षेत्र के नागर ब्राह्मण थे और गुजराती के आदिकवि माने जाते हैं। भाभी के कटु वचन सुनकर वे घर छोड़कर वन में तप करने चले गए, जहाँ परम्परा के अनुसार शिव जी ने उन्हें श्रीकृष्ण की रासलीला के दर्शन कराए।\n\nउनके भजन 'वैष्णव जन तो तेने कहिए' को बाद में महात्मा गाँधी ने अपनी प्रार्थना-सभाओं में अमर कर दिया। कथा है कि पुत्री के विवाह और 'मामेरा' जैसे कठिन अवसरों पर स्वयं भगवान् ने उनकी सहायता की। गुजरात में उनके पद आज भी घर-घर गाए जाते हैं।", db: "নরসী মেহতা (১৫শ শতাব্দী) গুজরাটের জুনাগড় অঞ্চলের নাগর ব্রাহ্মণ এবং গুজরাটির আদিকবি বলে মান্য। বৌদির কটু কথায় ঘর ছেড়ে বনে তপস্যায় গেলে ঐতিহ্য অনুসারে শিব তাঁকে শ্রীকৃষ্ণের রাসলীলার দর্শন করান।\n\nতাঁর ভজন 'বৈষ্ণব জন তো তেনে কহিয়ে' পরে মহাত্মা গান্ধী নিজের প্রার্থনাসভায় অমর করে দেন। কথিত আছে কন্যার বিবাহ ও 'মামেরা'-র মতো কঠিন সময়ে স্বয়ং ভগবান তাঁর সহায় হন। গুজরাটে তাঁর পদ আজও ঘরে ঘরে গাওয়া হয়।" },
  { file: './rashikan/p046.jpg', hi: "संत श्री ज्ञानेश्वर जी महाराज", bn: "সন্ত শ্রী জ্ঞানেশ্বর জী মহারাজ", g: 'sant', nh: "(1275–1296) महाराष्ट्र के सन्त; 'ज्ञानेश्वरी' (गीता की मराठी टीका) और 'अमृतानुभव' के रचयिता। वारकरी परम्परा के आधार-स्तम्भ; आलन्दी में समाधि।", nb: "(১২৭৫–১২৯৬) মহারাষ্ট্রের সন্ত; 'জ্ঞানেশ্বরী' (গীতার মারাঠি টীকা) ও 'অমৃতানুভব'-এর রচয়িতা। বারকরী পরম্পরার স্তম্ভ; আলন্দীতে সমাধি।", dh: "सन्त ज्ञानेश्वर (1275–1296) का जन्म आपेगाँव (महाराष्ट्र) में विट्ठल पन्त और रुक्मिणी बाई के घर हुआ। संन्यास के बाद गृहस्थ बने पिता के कारण परिवार को समाज ने बहिष्कृत कर दिया; बालक निवृत्तिनाथ, ज्ञानदेव, सोपान और मुक्ताबाई ने कठिन बचपन झेला।\n\nमात्र 16 वर्ष की आयु में उन्होंने 'ज्ञानेश्वरी' (गीता की मराठी टीका) और बाद में 'अमृतानुभव' तथा 'हरिपाठ' रचे। परम्परा में कथा है कि उन्होंने भैंसे के मुख से वेद-मन्त्र उच्चरित कराए। वारकरी परम्परा के आधार-स्तम्भ ज्ञानेश्वर ने 21 वर्ष की आयु में आलन्दी में संजीवन समाधि ली।", db: "সন্ত জ্ঞানেশ্বর (১২৭৫–১২৯৬) মহারাষ্ট্রের আপেগাঁওয়ে বিট্ঠল পন্ত ও রুক্মিণী বাঈয়ের গৃহে জন্মান। সন্ন্যাসের পর গৃহস্থ হওয়া পিতার কারণে সমাজ পরিবারটিকে একঘরে করে; শিশু নিবৃত্তিনাথ, জ্ঞানদেব, সোপান ও মুক্তাবাঈ কঠিন শৈশব কাটান।\n\nমাত্র ১৬ বছর বয়সে তিনি 'জ্ঞানেশ্বরী' (গীতার মারাঠি টীকা) এবং পরে 'অমৃতানুভব' ও 'হরিপাঠ' রচনা করেন। ঐতিহ্যে কথা আছে, তিনি এক মহিষের মুখে বেদমন্ত্র উচ্চারণ করান। বারকরী পরম্পরার স্তম্ভ জ্ঞানেশ্বর ২১ বছর বয়সে আলন্দীতে সঞ্জীবন সমাধি নেন।" },
  { file: './rashikan/p028.jpg', hi: "संत मुक्ताबाई जी", bn: "সন্ত মুক্তাবাঈ জী", g: 'sant', nh: "ज्ञानेश्वर जी की छोटी बहन; बाल्यावस्था में ही ज्ञान-सम्पन्न। 'ताटीचे अभंग' के लिए प्रसिद्ध।", nb: "জ্ঞানেশ্বরজির ছোট বোন; শৈশবেই জ্ঞানসম্পন্ন। 'তাটীচে অভঙ্গ'-এর জন্য প্রসিদ্ধ।", dh: "मुक्ताबाई (लगभग 1279–1297) सन्त ज्ञानेश्वर की छोटी बहन थीं। बचपन में ही अपने भाइयों के साथ कठिन परिस्थितियों में पली और अल्पायु में ही ज्ञान और भक्ति में परिपक्व हुईं।\n\nउनके अभंग गहरे आध्यात्मिक अर्थ वाले हैं; 'ताटीचे अभंग' विशेष प्रसिद्ध है, जिसमें कथा के अनुसार ज्ञानेश्वर जी के क्रोध पर उन्होंने कुटिया का द्वार खोलने के लिए समझाया था। योगी चांगदेव को भी उन्होंने ज्ञान का मार्ग दिखाया — ऐसा परम्परा में बताया जाता है।", db: "মুক্তাবাঈ (প্রায় ১২৭৯–১২৯৭) সন্ত জ্ঞানেশ্বরের ছোট বোন। শৈশবেই ভাইদের সঙ্গে কঠিন পরিস্থিতিতে বড় হন এবং অল্প বয়সেই জ্ঞান ও ভক্তিতে পরিণত হন।\n\nতাঁর অভঙ্গ গভীর আধ্যাত্মিক অর্থযুক্ত; 'তাটীচে অভঙ্গ' বিশেষ প্রসিদ্ধ, যেখানে কথিত আছে জ্ঞানেশ্বরের ক্রোধের সময় কুটিরের দরজা খুলতে তিনি বুঝিয়েছিলেন। যোগী চাংদেবকেও তিনি জ্ঞানের পথ দেখান — ঐতিহ্যে এমনটি বলা হয়।" },
  { file: './rashikan/p055.jpg', hi: "श्री नामदेव जी महाराज", bn: "শ্রী নামদেব জী মহারাজ", g: 'sant', nh: "(1270–1350) पंढरपुर के विठोबा-भक्त; मराठी अभंग और हिन्दी पदों के रचयिता। कुछ पद गुरु ग्रन्थ साहिब में भी हैं।", nb: "(১২৭০–১৩৫০) পন্ধরপুরের বিঠোবা-ভক্ত; মারাঠি অভঙ্গ ও হিন্দি পদের রচয়িতা। কিছু পদ গুরু গ্রন্থ সাহিবেও আছে।", dh: "सन्त नामदेव (लगभग 1270–1350) का जन्म नरसी बामनी (महाराष्ट्र) में दर्जी (शिम्पी) परिवार में हुआ। बचपन से ही वे विट्ठल (पंढरपुर) के अनन्य भक्त थे; कथा है कि उनके हाथ से लाए नैवेद्य को विट्ठल जी ने स्वयं ग्रहण किया।\n\nवे ज्ञानेश्वर जी के मित्र थे और उनके साथ तीर्थ-यात्रा की। उत्तर भारत और पंजाब तक उन्होंने भक्ति का प्रचार किया; उनके 60 से अधिक पद गुरु ग्रन्थ साहिब में सम्मिलित हैं। मराठी अभंगों के साथ हिन्दी पदों की रचना भी उन्होंने की। पंढरपुर में विट्ठल मन्दिर की पहली सीढ़ी पर उनकी समाधि है।", db: "সন্ত নামদেব (প্রায় ১২৭০–১৩৫০) মহারাষ্ট্রের নরসী বামনীতে দর্জি (শিম্পী) পরিবারে জন্মান। শৈশব থেকেই তিনি বিঠোবা (পন্ধরপুর)-র অনন্য ভক্ত; কথিত আছে তাঁর হাতের নৈবেদ্য স্বয়ং বিঠ্ঠলজি গ্রহণ করেছিলেন।\n\nতিনি জ্ঞানেশ্বরের বন্ধু ছিলেন এবং তাঁর সঙ্গে তীর্থযাত্রা করেন। উত্তর ভারত ও পাঞ্জাব পর্যন্ত তিনি ভক্তির প্রচার করেন; তাঁর ৬০টিরও বেশি পদ গুরু গ্রন্থ সাহিবে আছে। মারাঠি অভঙ্গের পাশাপাশি হিন্দি পদও রচনা করেন। পন্ধরপুরে বিঠোবা মন্দিরের প্রথম সিঁড়িতে তাঁর সমাধি।" },
  { file: './rashikan/p063.jpg', hi: "संत जनाबाई जी", bn: "সন্ত জনাবাঈ জী", g: 'sant', nh: "सन्त नामदेव के घर की सेविका; काम करते हुए विठोबा का नाम गाने वाली भक्तिमती। अभंग-रचनाएँ प्रसिद्ध हैं।", nb: "সন্ত নামদেবের গৃহের সেবিকা; কাজ করতে করতে বিঠোবার নাম গাওয়া ভক্তিমতী। অভঙ্গ রচনা প্রসিদ্ধ।", dh: "जनाबाई (13वीं–14वीं शताब्दी) महाराष्ट्र के गंगाखेड़ में जन्मीं और बचपन से ही सन्त नामदेव के घर दासी के रूप में रहीं। घर के कामों — विशेषकर चक्की पीसने और झाड़ू-बुहारी — के बीच वे निरन्तर विट्ठल का नाम गाती थीं।\n\nउनके तीन सौ से अधिक अभंग मिलते हैं, जिनमें 'दळिता कांडिता' जैसे श्रम-गीत अत्यन्त प्रसिद्ध हैं। परम्परा में कथा है कि विट्ठल जी स्वयं उनके कामों में हाथ बँटाते थे। वे दिखाती हैं कि दास्य-भाव और परिश्रम के बीच भी सर्वोच्च भक्ति सम्भव है।", db: "জনাবাঈ (১৩শ–১৪শ শতাব্দী) মহারাষ্ট্রের গঙ্গাখেড়ে জন্মান এবং শৈশব থেকে সন্ত নামদেবের গৃহে দাসী হিসেবে থাকেন। গৃহকাজের — বিশেষ করে জাঁতা পেষা ও ঝাড়ু দেওয়ার — মধ্যেও তিনি অবিরত বিঠ্ঠলের নাম গাইতেন।\n\nতাঁর তিনশোরও বেশি অভঙ্গ পাওয়া যায়, যার মধ্যে 'দলিতা কান্ডিতা'-র মতো শ্রম-গান অত্যন্ত প্রসিদ্ধ। ঐতিহ্যে কথা আছে স্বয়ং বিঠ্ঠলজি তাঁর কাজে হাত লাগাতেন। তিনি দেখান, দাস্য-ভাব ও পরিশ্রমের মাঝেও সর্বোচ্চ ভক্তি সম্ভব।" },
  { file: './rashikan/p029.jpg', hi: "संत श्री एकनाथ जी महाराज", bn: "সন্ত শ্রী একনাথ জী মহারাজ", g: 'sant', nh: "(1533–1599) पैठण के सन्त; 'एकनाथी भागवत' और भारुड़ के रचयिता। जाति-भेद से ऊपर उठकर उदार भक्ति-मार्ग का उपदेश दिया।", nb: "(১৫৩৩–১৫৯৯) পৈঠনের সন্ত; 'একনাথী ভাগবত' ও ভারুড়ের রচয়িতা। জাতিভেদের ঊর্ধ্বে উদার ভক্তিমার্গের উপদেশ দেন।", dh: "सन्त एकनाथ (1533–1599) पैठण (महाराष्ट्र) के प्रसिद्ध सन्त और विद्वान् थे; उनके गुरु देवगढ़ के जनार्दन स्वामी थे। उन्होंने 'एकनाथी भागवत' (श्रीमद्भागवत के एकादश स्कन्ध की मराठी टीका), 'भावार्थ रामायण' और अनेक 'भारूड' रचे।\n\nवे जाति-भेद और छुआछूत के विरोधी थे। प्रसिद्ध कथा है कि काशी से लाया गंगाजल उन्होंने रामेश्वर चढ़ाने के बजाय प्यासे गधे को पिला दिया, क्योंकि उसमें भी उन्होंने ईश्वर को देखा। क्षमा और धैर्य के उनके अनेक प्रसंग परम्परा में प्रसिद्ध हैं; उन्होंने ज्ञानेश्वरी का शुद्ध पाठ भी तैयार कराया।", db: "সন্ত একনাথ (১৫৩৩–১৫৯৯) পৈঠনের প্রসিদ্ধ সন্ত ও বিদ্বান; তাঁর গুরু দেবগড়ের জনার্দন স্বামী। তিনি 'একনাথী ভাগবত' (শ্রীমদ্ভাগবতের একাদশ স্কন্ধের মারাঠি টীকা), 'ভাবার্থ রামায়ণ' ও বহু 'ভারুড়' রচনা করেন।\n\nতিনি জাতিভেদ ও অস্পৃশ্যতার বিরোধী ছিলেন। প্রসিদ্ধ কথা: কাশী থেকে আনা গঙ্গাজল রামেশ্বরে চড়ানোর বদলে তিনি তৃষ্ণার্ত গাধাকে পান করান, কারণ তার মধ্যেও তিনি ঈশ্বরকে দেখেছিলেন। ক্ষমা ও ধৈর্যের বহু প্রসঙ্গ ঐতিহ্যে প্রসিদ্ধ; তিনি জ্ঞানেশ্বরীর শুদ্ধ পাঠও প্রস্তুত করান।" },
  { file: './rashikan/p010.jpg', hi: "श्री तुकाराम जी", bn: "শ্রী তুকারাম জী", g: 'sant', nh: "(17वीं शताब्दी) देहू के वारकरी सन्त; सरल भाषा में हज़ारों अभंग रचे। विठोबा के अनन्य भक्त।", nb: "(১৭শ শতাব্দী) দেহুর বারকরী সন্ত; সহজ ভাষায় হাজার হাজার অভঙ্গ রচনা করেন। বিঠোবার অনন্য ভক্ত।", dh: "सन्त तुकाराम (लगभग 1608–1650) देहू (पुणे के निकट) के वारकरी सन्त थे। उनका परिवार व्यापारी था, पर अकाल और परिजनों की मृत्यु ने उन्हें विरक्ति की ओर मोड़ा। वे विट्ठल के अनन्य भक्त बने।\n\nउन्होंने हज़ारों अभंग रचे, जो 'तुकाराम गाथा' में संकलित हैं और मराठी जन-जीवन में गहरे रचे-बसे हैं। परम्परा में कथा है कि विरोधियों ने उनकी गाथा इन्द्रायणी नदी में डुबो दी, तेरह दिन के आग्रह के बाद वह सुरक्षित मिली। छत्रपति शिवाजी महाराज उनसे श्रद्धा रखते थे। परम्परा के अनुसार वे सदेह वैकुण्ठ गए।", db: "সন্ত তুকারাম (প্রায় ১৬০৮–১৬৫০) দেহুর (পুনের কাছে) বারকরী সন্ত। তাঁর পরিবার ব্যবসায়ী ছিল, কিন্তু দুর্ভিক্ষ ও আপনজনের মৃত্যু তাঁকে বৈরাগ্যের দিকে ঘুরিয়ে দেয়। তিনি বিঠোবার অনন্য ভক্ত হন।\n\nতিনি হাজার হাজার অভঙ্গ রচনা করেন, যা 'তুকারাম গাথা'-য় সংকলিত এবং মারাঠি জনজীবনে গভীরভাবে মিশে আছে। ঐতিহ্যে কথা আছে, বিরোধীরা তাঁর গাথা ইন্দ্রায়ণী নদীতে ডুবিয়ে দেয়, তেরো দিনের আকুতির পর তা অক্ষত পাওয়া যায়। ছত্রপতি শিবাজী মহারাজ তাঁকে শ্রদ্ধা করতেন। ঐতিহ্য অনুসারে তিনি সশরীরে বৈকুণ্ঠে যান।" },
  { file: './rashikan/p056.jpg', hi: "भक्त सखुबाई जी", bn: "ভক্ত সখুবাঈ জী", g: 'sant', nh: "महाराष्ट्र की विठ्ठल-भक्त; गृह-कष्टों के बीच भी भक्ति नहीं छोड़ी। कथा है कि स्वयं पांडुरंग ने उनकी सेवा की।", nb: "মহারাষ্ট্রের বিট্ঠল-ভক্ত; সংসারের কষ্টের মধ্যেও ভক্তি ছাড়েননি। কথিত আছে স্বয়ং পান্ডুরঙ্গ তাঁর সেবা করেছিলেন।", dh: "सखुबाई महाराष्ट्र के कराड़ क्षेत्र की विट्ठल-भक्त थीं। ससुराल में उन्हें कठोर व्यवहार और कष्ट सहने पड़े, पर पंढरपुर और विट्ठल के प्रति उनकी भक्ति कभी कम नहीं हुई।\n\nपरम्परा में कथा है कि जब उन्हें बाँधकर पंढरपुर जाने से रोका गया, तब स्वयं पाण्डुरंग ने उनका रूप धरकर उनके घर के काम किए और सखुबाई वारी में पहुँच सकीं। यह कथा वारकरी परम्परा में भक्ति की शक्ति का सुन्दर उदाहरण है।", db: "সখুবাঈ মহারাষ্ট্রের কারাড় অঞ্চলের বিঠ্ঠল-ভক্ত ছিলেন। শ্বশুরবাড়িতে তাঁকে কঠোর আচরণ ও কষ্ট সইতে হয়, কিন্তু পন্ধরপুর ও বিঠ্ঠলের প্রতি তাঁর ভক্তি কখনও কমেনি।\n\nঐতিহ্যে কথা আছে, তাঁকে বেঁধে পন্ধরপুরে যেতে বাধা দিলে স্বয়ং পান্ডুরঙ্গ তাঁর রূপ ধরে ঘরের কাজ করে দেন এবং সখুবাঈ বারিতে পৌঁছাতে পারেন। এই কথা বারকরী পরম্পরায় ভক্তির শক্তির সুন্দর উদাহরণ।" },
  { file: './rashikan/p064.jpg', hi: "श्री कवि बिहारी जी", bn: "শ্রী কবি বিহারী জী", g: 'sant', nh: "ब्रज के कवि-भक्त। इनका विस्तृत परिचय अभी संकलित नहीं हुआ है; आगे जोड़ा जाएगा।", nb: "ব্রজের কবি-ভক্ত। এঁর বিস্তারিত পরিচয় এখনও সংকলিত হয়নি; পরে যোগ করা হবে।" },
  { file: './rashikan/p003.jpg', hi: "संत आनंदमयी माँ", bn: "সন্ত আনন্দময়ী মা", g: 'sant', nh: "(1896–1982) बंगाल में जन्मीं; 'माँ आनन्दमयी' नाम से विख्यात सन्त। देश भर में आश्रम, कनखल (हरिद्वार) में समाधि; सहज भक्ति और आनन्द की मूर्ति।", nb: "(১৮৯৬–১৯৮২) বাংলায় জন্ম; 'মা আনন্দময়ী' নামে বিখ্যাত সন্ত। দেশজুড়ে আশ্রম, কনখলে (হরিদ্বার) সমাধি; সহজ ভক্তি ও আনন্দের মূর্তি।", dh: "माँ आनन्दमयी (1896–1982) का जन्म वर्तमान बांग्लादेश के खेवड़ा (ब्राह्मणबाड़िया) गाँव में निर्मला सुन्दरी के रूप में हुआ। साधारण शिक्षा और कम आयु में विवाह के बाद भी उनमें स्वतः समाधि और भाव-अवस्थाएँ प्रकट होने लगीं; पति भोलानाथ ने उन्हें 'माँ' के रूप में सम्मान दिया।\n\nवे किसी सम्प्रदाय या गुरु-परम्परा में बँधी नहीं थीं और कहती थीं कि 'मैं तो जो थी, वही हूँ'। ढाका, कनखल (हरिद्वार), वाराणसी, वृन्दावन और अल्मोड़ा सहित देश भर में उनके आश्रम हैं। 1982 में कनखल में उनकी समाधि हुई। सहज आनन्द और सब धर्मों के प्रति समभाव उनकी पहचान है।", db: "মা আনন্দময়ী (১৮৯৬–১৯৮২) বর্তমান বাংলাদেশের খেওড়া (ব্রাহ্মণবাড়িয়া) গ্রামে নির্মলা সুন্দরী রূপে জন্মান। সাধারণ শিক্ষা ও অল্প বয়সে বিবাহের পরও তাঁর মধ্যে স্বতঃস্ফূর্ত সমাধি ও ভাবাবস্থা প্রকাশ পেতে থাকে; স্বামী ভোলানাথ তাঁকে 'মা' রূপে সম্মান করেন।\n\nতিনি কোনো সম্প্রদায় বা গুরু-পরম্পরায় বাঁধা ছিলেন না এবং বলতেন 'আমি যা ছিলাম, তাই আছি'। ঢাকা, কনখল (হরিদ্বার), বারাণসী, বৃন্দাবন ও আলমোড়া সহ দেশজুড়ে তাঁর আশ্রম। ১৯৮২ সালে কনখলে তাঁর সমাধি হয়। সহজ আনন্দ ও সব ধর্মের প্রতি সমভাব তাঁর পরিচয়।" },
  { file: './rashikan/p006.jpg', hi: "संत शारदा माँ", bn: "সন্ত শারদা মা", g: 'sant', nh: "(1853–1920) श्रीरामकृष्ण परमहंस की धर्मपत्नी, 'श्रीश्रीमाँ'। जयरामबाटी में जन्म; सबको अपना समझने का उपदेश दिया और रामकृष्ण संघ की मातृस्वरूपा रहीं।", nb: "(১৮৫৩–১৯২০) শ্রীরামকৃষ্ণ পরমহংসের সহধর্মিণী, 'শ্রীশ্রীমা'। জয়রামবাটীতে জন্ম; সবাইকে আপন ভাবার উপদেশ দেন এবং রামকৃষ্ণ সংঘের মাতৃস্বরূপা ছিলেন।", dh: "माँ शारदा देवी (1853–1920) का जन्म बंगाल के जयरामबाटी गाँव में हुआ। पाँच वर्ष की आयु में श्रीरामकृष्ण परमहंस से उनका विवाह हुआ; बाद में दक्षिणेश्वर में रहकर उन्होंने पति की सेवा की और साथ ही अपनी साधना भी की।\n\n1886 में श्रीरामकृष्ण के देहावसान के बाद वे रामकृष्ण-संघ की मार्गदर्शिका बनीं — स्वामी विवेकानन्द सहित सभी भक्त उन्हें 'श्रीश्रीमाँ' कहते थे। वे कहा करती थीं कि 'मैं सबकी माँ हूँ' और अपने सहज मातृ-स्नेह से हजारों को शरण दी। कलकत्ता के उद्बोधन-भवन और जयरामबाटी में उनकी स्मृति सुरक्षित है।", db: "মা সারদা দেবী (১৮৫৩–১৯২০) বাংলার জয়রামবাটী গ্রামে জন্মান। পাঁচ বছর বয়সে শ্রীরামকৃষ্ণ পরমহংসের সঙ্গে তাঁর বিবাহ হয়; পরে দক্ষিণেশ্বরে থেকে তিনি স্বামীর সেবা করেন এবং নিজের সাধনাও করেন।\n\n১৮৮৬ সালে শ্রীরামকৃষ্ণের দেহান্তের পর তিনি রামকৃষ্ণ সংঘের পথপ্রদর্শিকা হন — স্বামী বিবেকানন্দ সহ সব ভক্ত তাঁকে 'শ্রীশ্রীমা' বলতেন। তিনি বলতেন 'আমি সবার মা' এবং সহজ মাতৃস্নেহে হাজারো মানুষকে আশ্রয় দেন। কলকাতার উদ্বোধন ভবন ও জয়রামবাটীতে তাঁর স্মৃতি সংরক্ষিত।" },
  { file: './rashikan/p078.jpg', hi: "श्री पूर्णानंद तीर्थ जी महाराज (श्री उड़िया बाबा जी)", bn: "শ্রী পূর্ণানন্দ তীর্থ জী মহারাজ (শ্রী উড়িয়া বাবা জী)", g: 'sant', nh: "ओडिशा-मूल के विरक्त सन्त, 'उड़िया बाबा' नाम से विख्यात। अद्वैत और भक्ति का समन्वय करने वाले; ब्रज-वृन्दावन में सत्संग-भजन के लिए प्रसिद्ध। बीसवीं शताब्दी।", nb: "ওড়িশা-মূলের বিরক্ত সন্ত, 'উড়িয়া বাবা' নামে বিখ্যাত। অদ্বৈত ও ভক্তির সমন্বয়কারী; ব্রজ-বৃন্দাবনে সৎসঙ্গ-ভজনের জন্য প্রসিদ্ধ। বিংশ শতাব্দী।" },
  { file: './rashikan/p044.jpg', hi: "परम पूज्य भाईजी श्रीहनुमानप्रसादजी पोद्दार जी", bn: "পরম পূজ্য ভাইজী শ্রীহনুমানপ্রসাদজী পোদ্দার জী", g: 'sant', nh: "(1892–1971) गीता प्रेस, गोरखपुर से जुड़े; 'कल्याण' पत्रिका के सम्पादक, 'भाईजी' नाम से विख्यात। सनातन ग्रन्थों के प्रचार और राधा-कृष्ण भक्ति के प्रसार में अमूल्य योगदान।", nb: "(১৮৯২–১৯৭১) গীতা প্রেস, গোরক্ষপুরের সঙ্গে যুক্ত; 'কল্যাণ' পত্রিকার সম্পাদক, 'ভাইজি' নামে বিখ্যাত। সনাতন গ্রন্থের প্রচার ও রাধা-কৃষ্ণ ভক্তি প্রসারে অমূল্য অবদান।", dh: "श्रीहनुमानप्रसाद पोद्दार, 'भाईजी' (1892–1971) का जन्म राजस्थान के रतनगढ़ में हुआ। कोलकाता में कारोबारी परिवार में पले; स्वतन्त्रता-आन्दोलन में भी भाग लिया और बाद में पूरा जीवन भक्ति और धर्म-प्रचार को दिया।\n\nवे गीता प्रेस (गोरखपुर) के संस्थापकों में से एक थे और 1926 से लोकप्रिय पत्रिका 'कल्याण' के सम्पादक रहे। सनातन ग्रन्थों को सरल दामों पर घर-घर पहुँचाने में उनका योगदान अतुलनीय माना जाता है। वे राधा-कृष्ण के अनन्य भक्त थे; परम्परा में बताया जाता है कि उन्होंने भारत रत्न का प्रस्ताव स्वीकार नहीं किया। 1971 में गोरखपुर में उनका देहावसान हुआ।", db: "শ্রীহনুমানপ্রসাদ পোদ্দার, 'ভাইজি' (১৮৯২–১৯৭১) রাজস্থানের রতনগড়ে জন্মান। কলকাতায় ব্যবসায়ী পরিবারে বড় হন; স্বাধীনতা আন্দোলনেও অংশ নেন এবং পরে সারা জীবন ভক্তি ও ধর্ম-প্রচারে দেন।\n\nতিনি গীতা প্রেস (গোরক্ষপুর)-এর প্রতিষ্ঠাতাদের একজন এবং ১৯২৬ থেকে জনপ্রিয় পত্রিকা 'কল্যাণ'-এর সম্পাদক ছিলেন। সনাতন গ্রন্থ সস্তায় ঘরে ঘরে পৌঁছে দিতে তাঁর অবদান অতুলনীয় মানা হয়। তিনি রাধা-কৃষ্ণের অনন্য ভক্ত; ঐতিহ্যে বলা হয় তিনি ভারতরত্নের প্রস্তাব গ্রহণ করেননি। ১৯৭১ সালে গোরক্ষপুরে তাঁর দেহান্ত হয়।" },
  { file: './rashikan/p058.jpg', hi: "श्री राधा बाबा जी", bn: "শ্রী রাধা বাবা জী", g: 'sant', nh: "गोरखपुर के प्रसिद्ध सन्त; भाईजी पोद्दार के निकट सहयोगी और हरिनाम-संकीर्तन के प्रचारक। बीसवीं शताब्दी।", nb: "গোরক্ষপুরের প্রসিদ্ধ সন্ত; ভাইজি পোদ্দারের ঘনিষ্ঠ সহযোগী ও হরিনাম-সংকীর্তনের প্রচারক। বিংশ শতাব্দী।" },
  { file: './rashikan/p040.jpg', hi: "श्री श्रीधर दास बाबा जी", bn: "শ্রী শ্রীধর দাস বাবা জী", g: 'sant', nh: "ब्रज के रसिक सन्त। इनका विस्तृत परिचय अभी संकलित नहीं हुआ है; आगे जोड़ा जाएगा।", nb: "ব্রজের রসিক সন্ত। এঁর বিস্তারিত পরিচয় এখনও সংকলিত হয়নি; পরে যোগ করা হবে।" },
  { file: './rashikan/p021.jpg', hi: "पूज्य पण्डित श्रीगयाप्रसादजी महाराज", bn: "পূজ্য পণ্ডিত শ্রীগয়াপ্রসাদজী মহারাজ", g: 'sant', nh: "बीसवीं शताब्दी के पूज्य पण्डित; ब्रज के गुरु-सन्तों में गिने जाते थे (1970 के दशक में ब्रज के प्रमुख सन्तों में इनका उल्लेख मिलता है)।", nb: "বিংশ শতাব্দীর পূজ্য পণ্ডিত; ব্রজের গুরু-সন্তদের মধ্যে গণ্য (১৯৭০-এর দশকে ব্রজের প্রধান সন্তদের মধ্যে এঁর উল্লেখ পাওয়া যায়)।" },
  { file: './rashikan/p020.jpg', hi: "श्री नारायण स्वामी जी", bn: "শ্রী নারায়ণ স্বামী জী", g: 'sant', nh: "ब्रज के भगवद्भक्त सन्त। इनका विस्तृत परिचय अभी संकलित नहीं हुआ है; आगे जोड़ा जाएगा।", nb: "ব্রজের ভগবদ্ভক্ত সন্ত। এঁর বিস্তারিত পরিচয় এখনও সংকলিত হয়নি; পরে যোগ করা হবে।" },
  { file: './rashikan/p023.jpg', hi: "बालभक्त ओमप्रकाश जी", bn: "বালভক্ত ওমপ্রকাশ জী", g: 'sant', nh: "एक बालभक्त। इनका विस्तृत परिचय अभी संकलित नहीं हुआ है; आगे जोड़ा जाएगा।", nb: "একজন বালভক্ত। এঁর বিস্তারিত পরিচয় এখনও সংকলিত হয়নি; পরে যোগ করা হবে।" },
  { file: './rashikan/p042.jpg', hi: "श्री हित स्वामिनी शरण जी", bn: "শ্রী হিত স্বামিনী শরণ জী", g: 'sant', nh: "राधावल्लभ परम्परा के आधुनिक रसिक सन्त। इनका विस्तृत परिचय अभी संकलित नहीं हुआ है; आगे जोड़ा जाएगा।", nb: "রাধাবল্লভ পরম্পরার আধুনিক রসিক সন্ত। এঁর বিস্তারিত পরিচয় এখনও সংকলিত হয়নি; পরে যোগ করা হবে।" },
  { file: './rashikan/p085.jpg', hi: "श्री बिल्वमंगल ठाकुर जी (लीलाशुक)", bn: "শ্রী বিল্বমঙ্গল ঠাকুর জী (লীলাশুক)", g: 'sant', nh: "(लगभग 9वीं शताब्दी) विष्णुस्वामी सम्प्रदाय के सन्त, दीक्षा-नाम 'लीलाशुक'; 'श्रीकृष्णकर्णामृतम्' के रचयिता। नेत्रहीन होकर वृन्दावन में गोपाल-रूप श्रीकृष्ण के सखा बने।", nb: "(আনুমানিক ৯ম শতাব্দী) বিষ্ণুস্বামী সম্প্রদায়ের সন্ত, দীক্ষানাম 'লীলাশুক'; 'শ্রীকৃষ্ণকর্ণামৃতম্'-এর রচয়িতা। অন্ধ হয়ে বৃন্দাবনে গোপালরূপী শ্রীকৃষ্ণের সখা হন।", dh: "श्री बिल्वमंगल ठाकुर का जन्म दक्षिण भारत के एक पवित्र ब्राह्मण परिवार में लगभग 9वीं शताब्दी में माना जाता है; जन्म-तिथि ज्ञात नहीं। उन्होंने विष्णुस्वामी सम्प्रदाय में सोमगिरि जी से दीक्षा ली, जिन्होंने उन्हें 'लीलाशुक' नाम दिया।\n\nकथा है कि पिछले जन्म में वे श्रीकृष्ण-भक्त संन्यासी थे और भागवत-उत्सव कराकर प्रसाद बाँटते थे। धन की कमी होने पर उन्होंने एक राजकुमारी की चिता से गहने लेने चाहे; राजकुमारी की वाणी से उन्हें खजाना मिला, पर दूसरी बार हार ले लेने पर उसने शाप दिया कि एक जन्म और लेकर अनैतिक जीवन जीना होगा। अगले जन्म में वे धनी और विषयासक्त हुए और राजकुमारी चिन्तामणि नाम की गणिका बनी।\n\nएक बार तूफ़ानी रात में वे नदी तैरकर और साँप को रस्सी समझकर पकड़ते हुए चिन्तामणि के घर पहुँचे। चिन्तामणि ने कहा — 'जितना प्रेम तुम मुझसे करते हो, उतना श्रीकृष्ण से करते तो परम शान्ति मिल जाती।' ये शब्द उनके हृदय में उतर गए और वे तुरन्त वृन्दावन की ओर चल पड़े। मार्ग में एक स्त्री पर आकर्षित होने पर उन्होंने उस गृहस्थ दम्पति की सेवा-भावना देखकर स्वयं को धिक्कारा, स्त्री से हेयरपिन माँगकर अपनी आँखें फोड़ लीं और बोले — 'ये आँखें मेरी शत्रु थीं।'\n\nनेत्रहीन अवस्था में वे रोते-पश्चाताप करते वृन्दावन पहुँचे। भूखे देखकर श्रीकृष्ण स्वयं गोपाल नामक ब्रजवासी बालक बनकर आए, रोज़ दूध देते और उनके श्लोक-गान सुनते। एक दिन बाँसुरी सुनकर बिल्वमंगल ने उन्हें पहचान लिया और पकड़ना चाहा, पर कृष्ण हाथ छुड़ाकर भाग गए। तब उन्होंने गाया —\nहस्तमुत्क्षिप्य यातोऽसि बलात्कृष्ण किमद्भुतम् ।\nहृदयाद्यदि निर्यासि पौरुषं गणयामि ते ॥\n(हे कृष्ण! हाथ छुड़ाकर भाग गए, इसमें क्या अद्भुत? मैं तुम्हारा बल तब मानूँगा जब मेरे हृदय से निकल जाओ।) — श्रीकृष्णकर्णामृतम् (3.97)\n\nकहा जाता है कि वे वृन्दावन के ब्रह्मकुण्ड पर एक वृक्ष के नीचे लगभग 700 वर्ष योग-शक्ति से रहे। उनकी प्रसिद्ध रचना 'श्रीकृष्णकर्णामृतम्' वृन्दावन-माधुरी लीला में श्रीराधारानी की सर्वोच्च स्थिति प्रकट करने वाले प्रारम्भिक प्रामाणिक ग्रन्थों में गिनी जाती है; इसके अतिरिक्त उन्होंने 'गोविन्द दामोदर स्तोत्र' (71 श्लोक) रचा। उनके लीला-प्रवेश का वर्ष अज्ञात है; समाधि वृन्दावन के गोपीनाथ बाज़ार में है।", db: "শ্রী বিল্বমঙ্গল ঠাকুর দক্ষিণ ভারতের এক পবিত্র ব্রাহ্মণ পরিবারে আনুমানিক ৯ম শতাব্দীতে জন্মেছিলেন বলে মনে করা হয়; জন্মতিথি জানা যায় না। তিনি বিষ্ণুস্বামী সম্প্রদায়ে সোমগিরির কাছে দীক্ষা নেন, যিনি তাঁকে 'লীলাশুক' নাম দেন।\n\nকথিত আছে, পূর্বজন্মে তিনি শ্রীকৃষ্ণভক্ত সন্ন্যাসী ছিলেন এবং ভাগবত-উৎসব করে প্রসাদ বিতরণ করতেন। অর্থের অভাব হলে তিনি এক রাজকন্যার চিতা থেকে গয়না নিতে চান; রাজকন্যার বাণীতে তিনি ধনভাণ্ডার পান, কিন্তু দ্বিতীয়বার হার নিলে সে অভিশাপ দেয় — আরও এক জন্ম নিয়ে অনৈতিক জীবন কাটাতে হবে। পরের জন্মে তিনি ধনী ও বিষয়াসক্ত হন এবং সেই রাজকন্যা চিন্তামণি নামে এক গণিকা হয়ে জন্মায়।\n\nএক ঝড়ের রাতে তিনি নদী সাঁতরে এবং সাপকে দড়ি ভেবে ধরে চিন্তামণির বাড়ি পৌঁছান। চিন্তামণি বলল — 'আমার প্রতি তোমার যতটা ভালবাসা, শ্রীকৃষ্ণের প্রতি ততটা থাকলে পরম শান্তি পেতে।' এই কথা তাঁর হৃদয় নাড়িয়ে দিল এবং তিনি তখনই বৃন্দাবনের পথে রওনা দেন। পথে এক নারীর প্রতি আকৃষ্ট হলে সেই গৃহস্থ দম্পতির সেবাভাব দেখে নিজেকে ধিক্কার দেন, নারীর কাছ থেকে চুলের কাঁটা চেয়ে নিজের চোখ বিদ্ধ করেন এবং বলেন — 'এই চোখ আমার শত্রু ছিল।'\n\nঅন্ধ অবস্থায় কাঁদতে কাঁদতে অনুতাপ করতে করতে তিনি বৃন্দাবনে পৌঁছান। তাঁকে ক্ষুধার্ত দেখে শ্রীকৃষ্ণ নিজেই গোপাল নামে এক ব্রজবাসী বালক হয়ে আসেন, রোজ দুধ দিতেন এবং তাঁর শ্লোক-গান শুনতেন। একদিন বাঁশির সুরে বিল্বমঙ্গল তাঁকে চিনতে পারেন এবং ধরতে চান, কিন্তু কৃষ্ণ হাত ছাড়িয়ে পালিয়ে যান। তখন তিনি গাইলেন —\nহস্তমুৎক্ষিপ্য যাতোঽসি বলাৎকৃষ্ণ কিমদ্ভুতম্ ।\nহৃদয়াদ্যদি নির্যাসি পৌরুষং গণয়ামি তে ॥\n(হে কৃষ্ণ! হাত ছাড়িয়ে পালিয়েছ, এতে আশ্চর্য কী? আমার হৃদয় থেকে পালাতে পারলে তবেই তোমার বল মানব।) — শ্রীকৃষ্ণকর্ণামৃতম্ (৩.৯৭)\n\nকথিত আছে তিনি বৃন্দাবনের ব্রহ্মকুণ্ডে এক গাছের তলায় প্রায় ৭০০ বছর যোগশক্তিতে অবস্থান করেন। তাঁর বিখ্যাত রচনা 'শ্রীকৃষ্ণকর্ণামৃতম্' বৃন্দাবনের মাধুর্য লীলায় শ্রীরাধারানির সর্বোচ্চ স্থান প্রকাশকারী প্রাচীন প্রামাণিক গ্রন্থগুলির অন্যতম; এছাড়া তিনি 'গোবিন্দ দামোদর স্তোত্র' (৭১ শ্লোক) রচনা করেন। তাঁর লীলাসংবরণের সাল অজানা; সমাধি বৃন্দাবনের গোপীনাথ বাজারে।" },

  { file: './rashikan/p007.jpg', hi: "पूज्य श्री हित गौरांगी शरण जी महाराज (पूज्य महाराज जी के गुरुदेव)", bn: "পূজ্য শ্রী হিত গৌরাঙ্গী শরণ জী মহারাজ (পূজ্য মহারাজ জীর গুরুদেব)", g: 'guru', nh: "राधावल्लभीय रसिक सन्त, वृन्दावन में सहचरी-भाव और नित्य-विहार रस के उपासक। श्रीहित प्रेमानन्द गोविन्द शरण जी महाराज के सद्गुरुदेव।", nb: "রাধাবল্লভীয় রসিক সন্ত, বৃন্দাবনে সহচরী-ভাব ও নিত্য-বিহার রসের উপাসক। শ্রীহিত প্রেমানন্দ গোবিন্দ শরণজি মহারাজের সদ্গুরুদেব।", dh: "श्रीहित गौरांगी शरण जी महाराज वृन्दावन के प्रसिद्ध राधावल्लभीय रसिक सन्त हैं, जिन्हें भक्त स्नेह से 'बड़े गुरु जी' कहते हैं। वे सहचरी-भाव (सखी-भाव) और नित्य-विहार रस के प्रमुख उपासक के रूप में जाने जाते हैं, और मधुकरी के नियम से जीवन चलाते थे।\n\nश्रीहित प्रेमानन्द गोविन्द शरण जी महाराज ने उन्हीं से 'निज मन्त्र' और सहचरी-भाव की दीक्षा पाई और लगभग दस वर्ष तक उनकी सेवा की। इस प्रकार वे वर्तमान रसिक-परम्परा की एक महत्त्वपूर्ण कड़ी हैं।", db: "শ্রীহিত গৌরাঙ্গী শরণজি মহারাজ বৃন্দাবনের প্রসিদ্ধ রাধাবল্লভীয় রসিক সন্ত, যাঁকে ভক্তরা স্নেহে 'বড় গুরুজি' বলেন। তিনি সহচরী-ভাব (সখী-ভাব) ও নিত্য-বিহার রসের প্রধান উপাসক হিসেবে পরিচিত এবং মাধুকরীর নিয়মে জীবন কাটাতেন।\n\nশ্রীহিত প্রেমানন্দ গোবিন্দ শরণজি মহারাজ তাঁর কাছেই 'নিজ মন্ত্র' ও সহচরী-ভাবের দীক্ষা পান এবং প্রায় দশ বছর তাঁর সেবা করেন। এভাবে তিনি বর্তমান রসিক-পরম্পরার একটি গুরুত্বপূর্ণ সূত্র।" },
  { file: './rashikan/p041.jpg', hi: "पूज्य श्री हित प्रेमानंद गोविंद शरण जी महाराज", bn: "পূজ্য শ্রী হিত প্রেমানন্দ গোবিন্দ শরণ জী মহারাজ", g: 'guru', nh: "कानपुर के अखरी ग्राम में जन्म (नाम: अनिरुद्ध कुमार पाण्डेय); 13 वर्ष की आयु में गृह-त्याग। वृन्दावन में गौरांगी शरण जी से सहचरी-भाव की दीक्षा लेकर मधुकरी-वृत्ति से भजन किया; श्री हित राधा केलि कुंज के माध्यम से सत्संग करते हैं।", nb: "কানপুরের অখরি গ্রামে জন্ম (নাম: অনিরুদ্ধ কুমার পান্ডে); ১৩ বছর বয়সে গৃহত্যাগ। বৃন্দাবনে গৌরাঙ্গী শরণজির কাছে সহচরী-ভাবের দীক্ষা নিয়ে মাধুকরী বৃত্তিতে ভজন করেন; শ্রী হিত রাধা কেলি কুঞ্জের মাধ্যমে সৎসঙ্গ করেন।", dh: "श्रीहित प्रेमानन्द गोविन्द शरण जी महाराज का जन्म कानपुर के निकट अखरी गाँव में एक धर्मनिष्ठ ब्राह्मण परिवार में हुआ (पूर्व नाम अनिरुद्ध कुमार पाण्डेय)। दादा के प्रभाव से बचपन से ही अध्यात्म की ओर झुकाव था और 13 वर्ष की आयु में उन्होंने घर छोड़ दिया।\n\nवे काशी में रहे और नैष्ठिक ब्रह्मचर्य में दीक्षित हुए; फिर वृन्दावन आए। यहाँ श्रीराधावल्लभ जी के दर्शन और वृन्दावन-परिक्रमा के बीच गोस्वामी हित मोहित मराल जी की प्रेरणा से उन्होंने श्रीहरिवंश नाम और राधावल्लभ सम्प्रदाय की दीक्षा ली। फिर गुरुदेव हित गौरांगी शरण जी से सहचरी-भाव और नित्य-विहार का 'निज मन्त्र' पाया और मधुकरी से जीवन चलाया।\n\nवे वृन्दावन के वराह घाट के निकट श्रीहित राधा केलि कुंज में रहकर सत्संग और एकान्तिक वार्तालाप करते हैं। उनके उपदेश का सार है — नाम-जप, सरल जीवन, सदाचार और श्रीराधा-कृष्ण के प्रति अनन्य प्रेम।", db: "শ্রীহিত প্রেমানন্দ গোবিন্দ শরণজি মহারাজের জন্ম কানপুরের কাছে অখরি গ্রামে এক ধর্মনিষ্ঠ ব্রাহ্মণ পরিবারে (পূর্বনাম অনিরুদ্ধ কুমার পান্ডে)। দাদুর প্রভাবে শৈশব থেকেই অধ্যাত্মের দিকে ঝোঁক ছিল এবং ১৩ বছর বয়সে তিনি গৃহত্যাগ করেন।\n\nতিনি কাশীতে ছিলেন এবং নৈষ্ঠিক ব্রহ্মচর্যে দীক্ষিত হন; তারপর বৃন্দাবনে আসেন। এখানে শ্রীরাধাবল্লভজির দর্শন ও বৃন্দাবন-পরিক্রমার মাঝে গোস্বামী হিত মোহিত মরাল জির প্রেরণায় তিনি শ্রীহরিবংশ নাম ও রাধাবল্লভ সম্প্রদায়ের দীক্ষা নেন। পরে গুরুদেব হিত গৌরাঙ্গী শরণজির কাছে সহচরী-ভাব ও নিত্য-বিহারের 'নিজ মন্ত্র' পান এবং মাধুকরীতে জীবন কাটান।\n\nতিনি বৃন্দাবনের বরাহ ঘাটের কাছে শ্রীহিত রাধা কেলি কুঞ্জে থেকে সৎসঙ্গ ও একান্তিক বার্তালাপ করেন। তাঁর উপদেশের সার — নাম-জপ, সহজ জীবন, সদাচার এবং শ্রীরাধা-কৃষ্ণের প্রতি অনন্য প্রেম।" },
];
