function ddHi() { return secLang('sv') === 'hi'; }
function ddT(o) { return o ? (ddHi() ? (o.hi || o.bn || '') : (o.bn || o.hi || '')) : ''; }
function ddL(hi, bn) { return ddHi() ? hi : bn; }
// In the Android app (Capacitor) the deities folder is NOT bundled: photos / list.txt / audio are
// read live from the deployed site, so new photos need no APK rebuild. On the web they stay relative.
function ddNative() { try { return typeof _isNativeApp === 'function' && _isNativeApp(); } catch (_e) { return false; } }
function ddBase() { return ddNative() ? RJAP_PWA_URL.replace(/\/$/, '') + '/deities/' : './deities/'; }
function ddPath(slug, file) { return ddBase() + slug + '/' + encodeURIComponent(file).replace(/%2F/g, '/'); }
function ddBust(url) { return ddNative() ? url + '?r=' + Math.floor(Date.now() / 60000) : url; }   // fresh answer at most once a minute
function ddFetchOpts(o) { if (!ddNative()) return o; const c = Object.assign({}, o); delete c.cache; return c; }
// Fallback existence check that needs no CORS permission: try to load it as an <img>/<audio>.
function ddProbeEl(url, kind) {
  return new Promise((ok) => {
    if (navigator.onLine === false) { ok(null); return; }
    const el = kind === 'audio' ? new Audio() : new Image();
    let t = null;
    const done = (v) => { clearTimeout(t); el.onload = el.onerror = el.onloadedmetadata = null; ok(v); };
    el.onerror = () => done(false);
    if (kind === 'audio') { el.preload = 'metadata'; el.onloadedmetadata = () => done(true); } else { el.onload = () => done(true); }
    t = setTimeout(() => done(null), 15000);
    el.src = ddBust(url);
  });
}

// ── Discovery (what photos / audio does this deity folder have?) ──
const DD_EXTS = ['jpg', 'jpeg', 'png', 'webp', 'JPG', 'JPEG', 'PNG', 'WEBP'];
const DD_MAX_PHOTOS = 40;
const DD_INFO_KEY = 'dd_info_v1';
function ddInfoAll() {
  if (!window._ddInfo) {
    try { window._ddInfo = JSON.parse(localStorage.getItem(DD_INFO_KEY) || '{}') || {}; } catch (_e) { window._ddInfo = {}; }
  }
  return window._ddInfo;
}
function ddInfoSave() { try { localStorage.setItem(DD_INFO_KEY, JSON.stringify(window._ddInfo || {})); } catch (_e) {} }
function ddMan(slug) { const i = ddInfoAll()[slug]; return { photos: (i && i.p) || [], audio: (i && i.a) || null }; }

// true = file exists, false = not there, null = could not tell (offline / network error)
async function ddExists(url, kind) {
  const typeOk = (r) => {
    const ct = (r.headers.get('content-type') || '').toLowerCase();
    return kind === 'audio' ? (ct.indexOf('audio') === 0 || ct.indexOf('octet-stream') >= 0) : ct.indexOf('image') === 0;
  };
  try {
    const r = await fetch(ddBust(url), ddFetchOpts({ method: 'HEAD', cache: 'no-cache' }));
    if (r.status === 404) return false;
    if (r.ok) return typeOk(r);
  } catch (_e) { return ddNative() ? ddProbeEl(url, kind) : null; }
  try {   // host refused HEAD → GET, but drop the body as soon as the headers arrive
    const ac = new AbortController();
    const r = await fetch(ddBust(url), ddFetchOpts({ cache: 'no-cache', signal: ac.signal }));
    const ok = r.ok && typeOk(r);
    ac.abort();
    return ok;
  } catch (_e) { return ddNative() ? ddProbeEl(url, kind) : null; }
}

async function ddDiscover(slug, full) {
  const all = ddInfoAll();
  const prev = all[slug] || { p: [], a: null };
  let photos = null, netFail = false;

  // 1) optional list.txt — any file names, one per line
  try {
    const r = await fetch(ddBust(ddPath(slug, 'list.txt')), ddFetchOpts({ cache: 'no-cache' }));
    if (r.ok && (r.headers.get('content-type') || '').toLowerCase().indexOf('text/html') < 0) {
      const names = (await r.text()).split(/\r?\n/).map((x) => x.trim())
        .filter((x) => x && x[0] !== '#' && !/[\\/]/.test(x)).slice(0, DD_MAX_PHOTOS);
      if (names.length) photos = names;
    }
  } catch (_e) { if (!ddNative() || navigator.onLine === false) netFail = true; }   // app: a failed list.txt while online just means "no list.txt"

  // 2) otherwise 1.jpg, 2.jpg, 3.jpg ... until the first number that is missing
  if (!photos && !netFail) {
    photos = [];
    const m0 = prev.p[0] ? /\.([A-Za-z0-9]+)$/.exec(prev.p[0]) : null;
    let pref = m0 ? m0[1] : null;
    for (let n = 1; n <= DD_MAX_PHOTOS; n += 1) {
      const order = pref ? [pref].concat(DD_EXTS.filter((e) => e !== pref)) : DD_EXTS.slice();
      let hit = null, unknown = false;
      const first = await ddExists(ddPath(slug, n + '.' + order[0]), 'image');
      if (first === null) unknown = true;
      else if (first) hit = order[0];
      else {
        const rest = await Promise.all(order.slice(1).map((e) => ddExists(ddPath(slug, n + '.' + e), 'image')));
        const i = rest.indexOf(true);
        if (i >= 0) hit = order[i + 1];
        else if (rest.indexOf(null) >= 0) unknown = true;
      }
      if (unknown) { netFail = true; break; }
      if (!hit) break;
      photos.push(n + '.' + hit);
      pref = hit;
    }
  }
  if (netFail) return { changed: false, photos: prev.p, audio: prev.a };   // offline: keep what we knew

  // 3) audio.mp3 (only checked when a deity page is opened)
  let audio = prev.a || null;
  if (full) {
    const ax = await ddExists(ddPath(slug, 'audio.mp3'), 'audio');
    if (ax !== null) audio = ax ? 'audio.mp3' : null;
  }
  const changed = JSON.stringify(prev.p) !== JSON.stringify(photos) || (prev.a || null) !== audio;
  all[slug] = { p: photos, a: audio };
  if (changed) ddInfoSave();
  return { changed: changed, photos: photos, audio: audio };
}

// small work-queue so the list never fires dozens of probes at once
window._ddQ = window._ddQ || [];
window._ddRun = window._ddRun || 0;
window._ddSeen = window._ddSeen || {};
function ddQueue(slug, full, cb) { window._ddQ.push([slug, full, cb]); ddPump(); }
function ddPump() {
  while (window._ddRun < 2 && window._ddQ.length) {
    const job = window._ddQ.shift();
    window._ddRun += 1;
    ddDiscover(job[0], job[1]).then((r) => { try { job[2](r); } catch (_e) {} }).catch(() => {})
      .then(() => { window._ddRun -= 1; ddPump(); });
  }
}

// ── List thumbnails: made once on this phone from the first photo, then kept ──
window._ddMemTh = window._ddMemTh || {};
window._ddTFail = window._ddTFail || {};
function ddThumbGet(slug, name) {
  const mm = window._ddMemTh[slug];
  if (mm && mm.n === name) return mm.d;
  try {
    const o = JSON.parse(localStorage.getItem('dd_th_v1_' + slug) || 'null');
    return o && o.n === name ? o.d : '';
  } catch (_e) { return ''; }
}
function ddThumbMake(slug, name, img) {
  try {
    if (ddThumbGet(slug, name) || !img.naturalWidth) return;
    const w = 320, h = Math.round(w * img.naturalHeight / img.naturalWidth);
    const cv = document.createElement('canvas');
    cv.width = w; cv.height = h;
    cv.getContext('2d').drawImage(img, 0, 0, w, h);
    localStorage.setItem('dd_th_v1_' + slug, JSON.stringify({ n: name, d: cv.toDataURL('image/jpeg', 0.72) }));
  } catch (_e) {}
}

// Builds a small (400px) preview of a deity's first photo without opening the deity page.
// Photos are fetched ONE AT A TIME and decoded at reduced size, so big originals don't hurt the phone.
async function ddBuildThumb(slug, name) {
  const r = await fetch(ddPath(slug, name));
  if (!r.ok) return false;
  const blob = await r.blob();
  let src = null, w = 0, h = 0, url = null;
  if (window.createImageBitmap) {
    try { src = await createImageBitmap(blob, { resizeWidth: 400, resizeQuality: 'medium' }); w = src.width; h = src.height; } catch (_e) { src = null; }
  }
  if (!src) {   // older WebView: normal decode, then scale down
    url = URL.createObjectURL(blob);
    src = await new Promise((ok, no) => { const im = new Image(); im.onload = () => ok(im); im.onerror = no; im.src = url; });
    w = src.naturalWidth; h = src.naturalHeight;
  }
  const tw = Math.min(400, w), th = Math.max(1, Math.round(tw * h / w));
  const cv = document.createElement('canvas');
  cv.width = tw; cv.height = th;
  cv.getContext('2d').drawImage(src, 0, 0, tw, th);
  if (url) URL.revokeObjectURL(url);
  try { if (src.close) src.close(); } catch (_e) {}
  const dataUrl = cv.toDataURL('image/jpeg', 0.75);
  window._ddMemTh[slug] = { n: name, d: dataUrl };   // always usable this session, even if storage is full
  try { localStorage.setItem('dd_th_v1_' + slug, JSON.stringify({ n: name, d: dataUrl })); } catch (_e) {}
  return true;
}
window._ddTQ = window._ddTQ || [];
window._ddTBusy = window._ddTBusy || false;
window._ddTTried = window._ddTTried || {};
window._ddCards = window._ddCards || {};
function ddThumbEnqueue(slug) {
  if (window._ddTTried[slug]) return;
  try { if (navigator.connection && navigator.connection.saveData) return; } catch (_e) {}
  window._ddTTried[slug] = 1;
  window._ddTQ.push(slug);
  ddThumbPump();
}
async function ddThumbPump() {
  if (window._ddTBusy) return;
  window._ddTBusy = true;
  while (window._ddTQ.length) {
    const slug = window._ddTQ.shift();
    const ph = ddMan(slug).photos;
    try { if (ph.length && !ddThumbGet(slug, ph[0])) await ddBuildThumb(slug, ph[0]); } catch (_e) {}
    if (ph.length && !ddThumbGet(slug, ph[0])) window._ddTFail[slug] = 1;   // preview could not be made → card shows the photo itself
    const card = window._ddCards[slug];
    const d = DD_DEITIES.find((x) => x.s === slug);
    if (card && d && card.isConnected) card.innerHTML = ddCardHtml(d);
  }
  window._ddTBusy = false;
}

function ddBadge(d) {
  if (d.st === 'vrn') return { cls: 'vrn', text: ddL('वृन्दावन में विराजमान', 'বৃন্দাবনে বিরাজমান') };
  const to = ddT(d.to);
  if (d.pr) return { cls: 'moved', text: ddL('स्वरूप ' + to + ' में · प्रतिभू वृन्दावन में', 'স্বরূপ ' + to + '-এ · প্রতিভূ বৃন্দাবনে') };
  return { cls: 'moved', text: ddL('ब्रज से पधारे → ' + to, 'ব্রজ থেকে গিয়েছেন → ' + to) };
}

function ddOpenExternal(url) {
  try {
    const B = window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.Browser;
    if (B && B.open) { B.open({ url: url }); return; }
  } catch (_e) {}
  window.open(url, '_blank');
}

// ── Audio: audio.mp3 from the deity folder (plays on opening; ▶/⏸ button as backup) ──
let _dda = null;
function ddAudioStop() {
  const a = _dda;
  _dda = null;
  if (!a) return;
  try { clearInterval(a.watch); } catch (_e) {}
  try { a.el.pause(); a.el.removeAttribute('src'); a.el.load(); } catch (_e) {}
}
function ddAudioAttach(bar, slug, url) {
  const ui = { bar: bar, btn: bar.querySelector('.dd-a-play') };
  if (_dda && _dda.slug === slug && _dda.url === url) {          // page re-drawn: keep playing, just re-bind
    _dda.ui = ui; ui.btn.onclick = _dda.toggle; _dda.paint(); return;
  }
  ddAudioStop();
  const el = new Audio(url);
  el.loop = true;
  el.preload = 'auto';
  const a = { slug: slug, url: url, el: el, ui: ui, watch: null };
  a.paint = () => { const b = a.ui.btn; b.textContent = '🎵'; b.style.cssText = 'width:30px;height:30px;min-width:0;padding:0;border-radius:50%;font-size:15px;line-height:1;display:inline-flex;align-items:center;justify-content:center;cursor:pointer;border:1px solid rgba(255,215,0,0.35);background:rgba(255,215,0,0.10);opacity:' + (el.paused ? '0.45' : '1') + ';'; };
  a.toggle = () => { if (el.paused) el.play().catch(() => {}); else el.pause(); };
  el.addEventListener('play', a.paint);
  el.addEventListener('pause', a.paint);
  a.watch = setInterval(() => {                                   // stop when the page is left
    if (!a.ui.bar.isConnected || a.ui.bar.offsetParent === null) ddAudioStop();
  }, 1000);
  _dda = a;
  ui.btn.onclick = a.toggle;
  a.paint();
  el.play().catch(() => a.paint());                               // phone may block autoplay → user taps ▶
}

// ── Full-screen HD viewer (pinch / double-tap to zoom, drag to pan) ──
function ddOpenHD(src) {
  const ov = document.createElement('div');
  ov.className = 'dd-hd';
  ov.innerHTML = '<img alt="" draggable="false"><div class="dd-hd-load">…</div><button class="dd-hd-x" aria-label="close">✕</button>';
  const im = ov.querySelector('img');
  const ld = ov.querySelector('.dd-hd-load');
  im.addEventListener('load', () => { ld.style.display = 'none'; });
  im.addEventListener('error', () => { ld.textContent = ddL('फ़ोटो नहीं खुल पाई', 'ছবি খোলা যায়নি'); });
  im.src = src;
  let sc = 1, tx = 0, ty = 0, lastD = 0, sx = 0, sy = 0, stx = 0, sty = 0, lastTap = 0;
  const apply = () => { im.style.transform = 'translate(' + tx + 'px,' + ty + 'px) scale(' + sc + ')'; };
  const dist = (t) => Math.hypot(t[0].clientX - t[1].clientX, t[0].clientY - t[1].clientY);
  ov.addEventListener('touchstart', (e) => {
    if (e.touches.length === 2) { lastD = dist(e.touches); }
    else if (e.touches.length === 1) {
      sx = e.touches[0].clientX; sy = e.touches[0].clientY; stx = tx; sty = ty;
      const now = Date.now();
      if (now - lastTap < 300) { if (sc > 1) { sc = 1; tx = ty = 0; } else { sc = 2.5; } apply(); }
      lastTap = now;
    }
  }, { passive: true });
  ov.addEventListener('touchmove', (e) => {
    if (e.touches.length === 2) {
      const d = dist(e.touches);
      if (lastD) sc = Math.min(6, Math.max(1, sc * d / lastD));
      lastD = d;
      if (sc === 1) { tx = ty = 0; }
      apply(); e.preventDefault();
    } else if (e.touches.length === 1 && sc > 1) {
      tx = stx + (e.touches[0].clientX - sx); ty = sty + (e.touches[0].clientY - sy);
      apply(); e.preventDefault();
    }
  }, { passive: false });
  ov.addEventListener('touchend', (e) => { if (e.touches.length < 2) lastD = 0; if (sc === 1) { tx = ty = 0; apply(); } }, { passive: true });
  ov.addEventListener('wheel', (e) => {
    sc = Math.min(6, Math.max(1, sc * (e.deltaY < 0 ? 1.15 : 0.87)));
    if (sc === 1) { tx = ty = 0; }
    apply(); e.preventDefault();
  }, { passive: false });
  ov.querySelector('.dd-hd-x').addEventListener('click', () => ov.remove());
  document.body.appendChild(ov);
}

// ── Screen: list of deities, grouped by sampradaya ──
function ddCardHtml(d) {
  const ph = ddMan(d.s).photos;
  const th = ph.length ? ddThumbGet(d.s, ph[0]) : '';
  const b = ddBadge(d);
  return '<div class="dd-thumb">' +
      (th ? '<img alt="" draggable="false" src="' + th + '">'
        : (ph.length && window._ddTFail[d.s] ? '<img alt="" draggable="false" loading="lazy" src="' + ddPath(d.s, ph[0]) + '">' : '<span class="dd-ph">🪷</span>')) +
      (ph.length ? '<span class="dd-count">📷 ' + ph.length + '</span>' : '') +
    '</div>' +
    '<div class="dd-cname">' + escHtml(ddT(d.n)) + '</div>' +
    '<div class="dd-cbadge ' + b.cls + '">' + escHtml(b.text) + '</div>';
}

function renderDeityDarshan(list) {
  if (window._ddSel) { renderDeityPage(list, window._ddSel); return; }
  ddAudioStop();

  const title = ddL('दिव्य दर्शन — वृन्दावन के श्रीविग्रह', 'দিব্য দর্শন — বৃন্দাবনের শ্রীবিগ্রহ');
  const back = document.createElement('div');
  back.className = 'st-back-row';
  back.innerHTML = '<button class="st-back-btn">← ' + escHtml(ddL('फ़ोल्डर सूची', 'ফোল্ডার তালিকা')) + '</button>' +
    '<span class="st-back-title">' + escHtml(title) + '</span>';
  back.querySelector('.st-back-btn').addEventListener('click', () => { window._stActiveFolder = null; renderSt(); });
  list.appendChild(back);

  const filt = window._ddFilter || 'all';
  const cnt = { vrn: 0, moved: 0, all: DD_DEITIES.length };
  DD_DEITIES.forEach((d) => { cnt[d.st] += 1; });
  const chips = document.createElement('div');
  chips.className = 'dd-chips';
  [['vrn', ddL('वृन्दावन में', 'বৃন্দাবনে')], ['moved', ddL('ब्रज से पधारे', 'ব্রজ থেকে গিয়েছেন')], ['all', ddL('सभी', 'সব')]].forEach((ch) => {
    const b = document.createElement('button');
    b.className = 'dd-chip' + (filt === ch[0] ? ' on' : '');
    b.textContent = ch[1] + ' (' + cnt[ch[0]] + ')';
    b.addEventListener('click', () => { window._ddFilter = ch[0]; renderSt(); });
    chips.appendChild(b);
  });
  list.appendChild(chips);

  // Cards look for their photos only when they scroll into view.
  const needThumb = (d) => { const ph = ddMan(d.s).photos; return ph.length > 0 && !ddThumbGet(d.s, ph[0]); };
  const probe = (card, d) => {
    if (needThumb(d)) ddThumbEnqueue(d.s);                 // photos already known → make the preview now
    if (window._ddSeen[d.s]) return;
    window._ddSeen[d.s] = 1;
    ddQueue(d.s, false, (r) => {
      if (r && r.changed && card.isConnected) card.innerHTML = ddCardHtml(d);
      if (needThumb(d)) ddThumbEnqueue(d.s);               // photos just discovered → preview
    });
  };
  const io = ('IntersectionObserver' in window)
    ? new IntersectionObserver((entries) => {
        entries.forEach((en) => { if (en.isIntersecting) { io.unobserve(en.target); probe(en.target, en.target._dd); } });
      }, { rootMargin: '250px' })
    : null;

  let shown = 0;
  DD_SAMP.forEach((sp) => {
    const items = DD_DEITIES.filter((d) => d.k === sp.k && (filt === 'all' || d.st === filt));
    if (!items.length) return;
    shown += items.length;
    const h = document.createElement('div');
    h.className = 'dd-samp';
    h.textContent = ddT(sp.t);
    list.appendChild(h);
    const grid = document.createElement('div');
    grid.className = 'dd-grid';
    items.forEach((d) => {
      const card = document.createElement('div');
      card.className = 'dd-card';
      card._dd = d;
      window._ddCards[d.s] = card;
      card.innerHTML = ddCardHtml(d);
      card.addEventListener('click', () => { window._ddSel = d.s; window._ddIdx = 0; renderSt(); try { window.scrollTo(0, 0); } catch (_e) {} });
      grid.appendChild(card);
      if (io) io.observe(card); else probe(card, d);
    });
    list.appendChild(grid);
  });
  if (!shown) {
    const e = document.createElement('div');
    e.className = 'st-folder-empty';
    e.textContent = ddL('जल्द ही आ रहा है 🙏', 'শীঘ্রই আসছে 🙏');
    list.appendChild(e);
  }
}

// ── Screen: one deity ──
function renderDeityPage(list, slug) {
  const d = DD_DEITIES.find((x) => x.s === slug);
  if (!d) { window._ddSel = null; renderSt(); return; }
  const sp = DD_SAMP.find((x) => x.k === d.k);

  const back = document.createElement('div');
  back.className = 'st-back-row';
  back.innerHTML = '<button class="st-back-btn">← ' + escHtml(ddL('दिव्य दर्शन', 'দিব্য দর্শন')) + '</button>' +
    '<span class="st-back-title">' + escHtml(ddT(d.n)) + '</span>';
  back.querySelector('.st-back-btn').addEventListener('click', () => { ddAudioStop(); window._ddSel = null; renderSt(); });
  list.appendChild(back);

  const wrap = document.createElement('div');
  wrap.className = 'dd-page';
  const man = ddMan(slug);
  const photos = man.photos;
  const b = ddBadge(d);

  let html = '<div class="dd-stage">';
  if (photos.length) {
    html += '<img class="dd-img" alt="" draggable="false" decoding="async">' +
      '<span class="dd-hdhint">HD ⤢</span>';
  } else {
    html += '<div class="dd-noimg"><span class="dd-ph big">🪷</span><div>' + escHtml(ddL('श्रीविग्रह का चित्र जल्द जुड़ेगा', 'শ্রীবিগ্রহের ছবি শীঘ্রই যুক্ত হবে')) + '</div></div>';
  }
  html += '</div><div class="dd-dots"></div>' +
    '<div class="dd-namebar">' +
      (photos.length > 1 ? '<button class="dd-nav dd-prev" aria-label="prev">‹</button>' : '<span class="dd-nav-sp"></span>') +
      '<div class="dd-name">' + escHtml(ddT(d.n)) + '</div>' +
      (photos.length > 1 ? '<button class="dd-nav dd-next" aria-label="next">›</button>' : '<span class="dd-nav-sp"></span>') +
    '</div>' +
    '<div class="dd-cbadge ' + b.cls + ' dd-pbadge">' + escHtml(b.text) + '</div>' +
    '<div class="dd-audio-slot"></div>';

  const block = (label, text, cls) => (text
    ? '<div class="dd-block ' + (cls || '') + '"><div class="dd-label">' + escHtml(label) + '</div><div class="dd-text">' + escHtml(text).replace(/\n/g, '<br>') + '</div></div>'
    : '');
  html += block(ddL('प्रकटकर्ता आचार्य', 'প্রকটকর্তা আচার্য'), ddT(d.ac));
  html += (sp ? block(ddL('सम्प्रदाय एवं सेवा-विधि', 'সম্প্রদায় ও সেবা-বিধি'), ddT(sp.t) + (d.vd ? '\n' + ddT(d.vd) : '')) : '');
  html += d.kt
    ? '<details class="dd-block dd-kt" open><summary class="dd-label">' + escHtml(ddL('आविर्भाव कथा', 'আবির্ভাব কথা')) + '</summary><div class="dd-text">' +
      escHtml(ddT(d.kt)).replace(/\n/g, '<br>') + '</div><div class="dd-note">' + escHtml(ddL('परम्परा के अनुसार', 'ঐতিহ্য অনুসারে')) + '</div></details>'
    : block(ddL('आविर्भाव कथा', 'আবির্ভাব কথা'), ddL('कथा शीघ्र जोड़ी जाएगी 🙏', 'কথা শীঘ্রই যোগ করা হবে 🙏'), 'dd-soon');
  html += block(ddL('विशेष — क्यों प्रसिद्ध', 'বিশেষ — কেন প্রসিদ্ধ'), ddT(d.fm));
  if (d.sth || d.q) {
    html += '<div class="dd-block"><div class="dd-label">' + escHtml(ddL('स्थान', 'স্থান')) + '</div>' +
      (d.sth ? '<div class="dd-text">' + escHtml(ddT(d.sth)) + '</div>' : '') +
      '<button class="dd-maps">📍 ' + escHtml(ddL('मानचित्र में खोलें', 'ম্যাপে খুলুন')) + '</button>' +
      '<div class="dd-note">' + escHtml(ddL('दर्शन-समय बदलते रहते हैं — जाने से पहले मन्दिर से पूछ लें।', 'দর্শনের সময় বদলায় — যাওয়ার আগে মন্দিরে জেনে নিন।')) + '</div></div>';
  }
  if (d.src) html += '<div class="dd-src">' + escHtml(ddL('स्रोत: ', 'সূত্র: ') + d.src) + '</div>';
  wrap.innerHTML = html;
  list.appendChild(wrap);

  // photos
  if (photos.length) {
    const img = wrap.querySelector('.dd-img');
    const dots = wrap.querySelector('.dd-dots');
    let idx = (window._ddIdx >= 0 && window._ddIdx < photos.length) ? window._ddIdx : 0;
    const paint = () => {
      img.src = ddPath(slug, photos[idx]);
      dots.innerHTML = photos.length > 1 ? photos.map((_, i) => '<i class="' + (i === idx ? 'on' : '') + '"></i>').join('') : '';
      window._ddIdx = idx;
      if (photos.length > 1) { const pre = new Image(); pre.src = ddPath(slug, photos[(idx + 1) % photos.length]); }
    };
    const go = (dl) => { idx = (idx + dl + photos.length) % photos.length; paint(); };
    paint();
    img.addEventListener('load', () => { if (idx === 0) ddThumbMake(slug, photos[0], img); });
    const pv = wrap.querySelector('.dd-prev'), nxb = wrap.querySelector('.dd-next');
    if (pv) pv.addEventListener('click', (e) => { e.stopPropagation(); go(-1); });
    if (nxb) nxb.addEventListener('click', (e) => { e.stopPropagation(); go(1); });
    const stage = wrap.querySelector('.dd-stage');
    let tX = null, tY = null, moved = false;
    stage.addEventListener('touchstart', (e) => { tX = e.changedTouches[0].clientX; tY = e.changedTouches[0].clientY; moved = false; }, { passive: true });
    stage.addEventListener('touchend', (e) => {
      if (tX == null) return;
      const dx = e.changedTouches[0].clientX - tX, dy = e.changedTouches[0].clientY - tY;
      tX = null;
      if (Math.abs(dx) > 40 && Math.abs(dx) > Math.abs(dy) * 1.3) { moved = true; go(dx < 0 ? 1 : -1); }
    }, { passive: true });
    img.addEventListener('click', () => { if (moved) { moved = false; return; } ddOpenHD(ddPath(slug, photos[idx])); });
    img.addEventListener('error', () => { img.style.display = 'none'; });
  }

  // bhajan (only when the folder has audio.mp3)
  if (man.audio) {
    const bar = document.createElement('div');
    bar.className = 'dd-audio';
    bar.innerHTML = '<button class="dd-a-play" aria-label="' + escHtml(ddL('दिव्य भजन', 'দিব্য ভজন')) + '">🎵</button>';
    bar.style.cssText = 'display:inline-flex;width:auto;min-width:0;padding:0;margin:6px 0;background:none;border:none;box-shadow:none;';
    wrap.querySelector('.dd-audio-slot').appendChild(bar);
    ddAudioAttach(bar, slug, ddPath(slug, man.audio));
  } else { ddAudioStop(); }

  const mp = wrap.querySelector('.dd-maps');
  if (mp) mp.addEventListener('click', () => ddOpenExternal('https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(d.q || ddT(d.n) + ' Vrindavan')));

  // look for new photos / audio in the folder; redraw only if something changed
  ddQueue(slug, true, (r) => {
    if (r && r.changed && window._ddSel === slug && list.isConnected) renderSt();
  });
}

function renderRashikJan(list) {
  const hi = secLang('sv') === 'hi';
  const rvTitle = hi ? 'राधावल्लभ सम्प्रदाय' : 'রাধা বল্লভ সম্প্রদায়';
  const title = hi ? 'रसिक, वैष्णव एवं अन्य भक्त तथा संतजन दर्शन एवं परिचय' : 'রসিক, বৈষ্ণব ও অন্যান্য ভক্ত এবং সন্তজন দর্শন ও পরিচিতি';

  const back = document.createElement('div');
  back.className = 'st-back-row';
  back.innerHTML =
    '<button class="st-back-btn">← ' + escHtml(rvTitle) + '</button>' +
    '<span class="st-back-title">' + escHtml(title) + '</span>';
  back.querySelector('.st-back-btn').addEventListener('click', () => {
    window._stActiveFolder = 'rv';
    _rjClose();
    renderSt();
    try { list.scrollIntoView({ block: 'start' }); } catch (_e) {}
  });
  list.appendChild(back);

  const wrap = document.createElement('div');
  wrap.className = 'rj-wrap';
  wrap.innerHTML =
    '<div class="rj-stage">' +
      '<img class="rj-img" alt="" draggable="false">' +
      '<button class="rj-arrow rj-prev" aria-label="prev">‹</button>' +
      '<button class="rj-arrow rj-next" aria-label="next">›</button>' +
    '</div>' +
    '<div class="rj-group"></div>' +
    '<div class="rj-caption"></div>' +
    '<div class="rj-note"></div>' +
    '<button class="rj-more" style="display:none"></button>' +
    '<div class="rj-count"></div>';
  list.appendChild(wrap);

  const n = RASHIKJAN_ITEMS.length;
  let idx = (window._rjIdx >= 0 && window._rjIdx < n) ? window._rjIdx : 0;
  const img = wrap.querySelector('.rj-img');
  const cap = wrap.querySelector('.rj-caption');
  const grp = wrap.querySelector('.rj-group');
  const note = wrap.querySelector('.rj-note');
  const more = wrap.querySelector('.rj-more');
  const cnt = wrap.querySelector('.rj-count');

  const paint = () => {
    const it = RASHIKJAN_ITEMS[idx];
    img.src = it.file;
    cap.textContent = hi ? it.hi : it.bn;
    const gg = RJ_GROUPS[it.g];
    grp.textContent = gg ? (hi ? gg.hi : gg.bn) : '';
    note.textContent = hi ? (it.nh || '') : (it.nb || '');
    note.scrollTop = 0;
    const dtl = hi ? it.dh : it.db;
    more.style.display = dtl ? '' : 'none';
    more.textContent = (hi ? '📖 विस्तार से पढ़ें' : '📖 বিস্তারিত পড়ুন');
    cnt.textContent = (idx + 1) + ' / ' + n;
    window._rjIdx = idx;
  };
  paint();

  const go = (delta, manual) => {
    idx = (idx + delta + n) % n;
    paint();
    if (manual) _rjArmAutoplay(wrap, go);
  };
  wrap.querySelector('.rj-prev').addEventListener('click', () => go(-1, true));
  wrap.querySelector('.rj-next').addEventListener('click', () => go(1, true));

  // Swipe left/right on the image itself.
  let touchX = null, touchY = null;
  const stage = wrap.querySelector('.rj-stage');
  stage.addEventListener('touchstart', (e) => {
    const t = e.changedTouches[0];
    touchX = t.clientX; touchY = t.clientY;
  }, { passive: true });
  stage.addEventListener('touchend', (e) => {
    if (touchX == null) return;
    const t = e.changedTouches[0];
    const dx = t.clientX - touchX, dy = t.clientY - touchY;
    touchX = null;
    if (Math.abs(dx) > 40 && Math.abs(dx) > Math.abs(dy) * 1.3) go(dx < 0 ? 1 : -1, true);
  }, { passive: true });

  more.addEventListener('click', () => {
    const it = RASHIKJAN_ITEMS[idx];
    _rjOpenSheet(hi ? it.hi : it.bn, grp.textContent, hi ? it.dh : it.db, hi, () => _rjArmAutoplay(wrap, go));
  });

  wrap._rjGo = go;
  _rjArmAutoplay(wrap, go, true);

  // Stop the carousel (autoplay + listeners) once it's no longer on screen.
  const watchT = setInterval(() => {
    if (!wrap.isConnected) { clearInterval(watchT); _rjClose(); }
  }, 1000);
}

// Time each portrait stays on screen (ms) — long enough to read the note.
const RJ_AUTOPLAY_MS = 14000;
function _rjArmAutoplay(wrap, go, immediate) {
  clearInterval(window._rjTimer);
  clearTimeout(window._rjPauseT);
  const start = () => {
    window._rjTimer = setInterval(() => { if (!window._rjSheetOpen) go(1, false); }, RJ_AUTOPLAY_MS);
  };
  if (immediate) start();
  else {
    // Manual move: pause autoplay briefly, then resume.
    window._rjPauseT = setTimeout(start, 4000);
  }
}
function _rjClose() {
  clearInterval(window._rjTimer);
  clearTimeout(window._rjPauseT);
  window._rjTimer = null;
  const sh = document.querySelector('.rj-sheet');
  if (sh) sh.remove();
  window._rjSheetOpen = false;
}

// Full biography sheet ("विस्तार से पढ़ें"). The carousel waits while it is open.
function _rjOpenSheet(name, group, text, hi, onClose) {
  const old = document.querySelector('.rj-sheet');
  if (old) old.remove();
  window._rjSheetOpen = true;
  const sh = document.createElement('div');
  sh.className = 'rj-sheet';
  const paras = String(text || '').split(/\n\n+/).map((p) => '<p>' + escHtml(p).replace(/\n/g, '<br>') + '</p>').join('');
  sh.innerHTML =
    '<div class="rj-sheet-card">' +
      '<button class="rj-sheet-x" aria-label="close">✕</button>' +
      (group ? '<div class="rj-sheet-grp">' + escHtml(group) + '</div>' : '') +
      '<div class="rj-sheet-name">' + escHtml(name) + '</div>' +
      '<div class="rj-sheet-body">' + paras + '</div>' +
      '<div class="rj-sheet-foot">' + escHtml(hi ? 'जानकारी परम्परा और उपलब्ध स्रोतों के आधार पर संकलित है।' : 'তথ্য পরম্পরা ও উপলব্ধ সূত্র অনুসারে সংকলিত।') + '</div>' +
    '</div>';
  const close = () => {
    sh.remove();
    window._rjSheetOpen = false;
    try { if (onClose) onClose(); } catch (_e) {}
  };
  sh.addEventListener('click', (e) => { if (e.target === sh) close(); });
  sh.querySelector('.rj-sheet-x').addEventListener('click', close);
  document.body.appendChild(sh);
}

// ─────────────────────────────────────────────────────────
// SEVA INLINE AUDIO PLAYERS — every pad (verse) that has a YouTube link gets
// its own permanent player right below the verse: play/pause, prev/next pad,
// seek bar, time, pad counter and a 🎬 button to reveal the video. Audio-only by
// default: one hidden YouTube embedded player (same as Favourite Videos, driven
// through its postMessage API — no extra script) is shared by all the players
// of the section and is created on the first tap. Continues to the next pad
// automatically. Needs internet: with no connection a warning is shown.
// ─────────────────────────────────────────────────────────
let _sap = null;

function _sapFmt(sec) {
  sec = Math.max(0, Math.floor(sec || 0));
  return Math.floor(sec / 60) + ':' + String(sec % 60).padStart(2, '0');
}
function _sapHi() { return secLang('sv') === 'hi'; }
function _sapOnline() { return navigator.onLine !== false; }
function _sapOfflineText() {
  return _sapHi()
    ? 'ऑडियो चलाने के लिए कृपया इंटरनेट से जुड़ें 🙏'
    : 'অডিও চালাতে অনুগ্রহ করে ইন্টারনেটের সাথে সংযুক্ত হন 🙏';
}
function _sapFailText() {
  return _sapHi() ? 'यह ऑडियो नहीं चल पाया 🙏' : 'এই অডিও চালানো যায়নি 🙏';
}
function _sapWarn(i, text) {
  const msg = text || _sapOfflineText();
  const p = _sap && _sap.tracks[i];
  if (p) { p.ui.msg.textContent = msg; p.ui.msg.style.display = 'block'; }
  try { toast(msg); } catch (_e) {}
}
function _sapClearMsg(i) {
  const p = _sap && _sap.tracks[i];
  if (p) { p.ui.msg.textContent = ''; p.ui.msg.style.display = 'none'; }
}

function _sapCmd(func, args) {
  try {
    if (!_sap || !_sap.frame || !_sap.frame.contentWindow) return;
    _sap.frame.contentWindow.postMessage(
      JSON.stringify({ event: 'command', func: func, args: args || [] }), '*');
  } catch (_e) {}
}

// Paint the live state (icon, time, seek) onto the active pad's player.
function _sapSync() {
  if (!_sap || _sap.idx < 0) return;
  const p = _sap.tracks[_sap.idx];
  if (!p) return;
  const u = p.ui;
  const playing = _sap.state === 1 || _sap.state === 3;
  u.play.textContent = playing ? '⏸' : '▶';
  u.el.classList.add('sap-active');
  u.seek.disabled = false;
  u.cur.textContent = _sapFmt(_sap.time);
  u.tot.textContent = _sapFmt(_sap.dur);
  if (!_sap.scrubbing) u.seek.value = _sap.dur > 0 ? Math.round((_sap.time / _sap.dur) * 1000) : 0;
}

// Put a pad's player back to its idle look (when another pad takes over).
function _sapResetUi(i) {
  const p = _sap && _sap.tracks[i];
  if (!p) return;
  const u = p.ui;
  u.play.textContent = '▶';
  u.el.classList.remove('sap-active');
  u.cur.textContent = '0:00';
  u.tot.textContent = '0:00';
  u.seek.value = 0;
  u.seek.disabled = true;
}

function _sapEnsureFrame() {
  if (!_sap || _sap.frame) return;
  const vwrap = document.createElement('div');
  vwrap.id = 'sevaVideoWrap';
  const frame = document.createElement('iframe');
  frame.setAttribute('allow', 'autoplay; encrypted-media; picture-in-picture');
  frame.setAttribute('allowfullscreen', '');
  vwrap.appendChild(frame);
  document.body.appendChild(vwrap);
  _sap.frame = frame;
  _sap.vwrap = vwrap;
  window.addEventListener('message', _sap.onMsg);
  // Handshake: after each load, ask the player to start sending state/time.
  frame.addEventListener('load', () => {
    try {
      if (frame.src === 'about:blank') return;
      frame.contentWindow.postMessage(JSON.stringify({ event: 'listening', id: 1, channel: 'widget' }), '*');
      ['onStateChange', 'onError'].forEach((n) =>
        frame.contentWindow.postMessage(JSON.stringify({ event: 'command', func: 'addEventListener', args: [n] }), '*'));
    } catch (_e) {}
  });
}

// Start pad i from the beginning (audio-only; the video stays hidden).
function _sapPlay(i, scroll) {
  if (!_sap || !_sap.tracks[i]) return;
  if (!_sapOnline()) { _sapWarn(i); return; }
  _sapEnsureFrame();
  clearTimeout(_sap.loadT);
  if (_sap.idx >= 0 && _sap.idx !== i) _sapResetUi(_sap.idx);
  _sapClearMsg(i);
  _sap.idx = i;
  _sap.played = false;   // becomes true once THIS pad really plays (guards auto-advance)
  _sap.time = 0;
  _sap.dur = 0;
  _sap.state = 3;   // shows ⏸ straight away; real state events overwrite it
  _sap.frame.src = 'https://www.youtube.com/embed/' + _sap.tracks[i].id +
    '?autoplay=1&playsinline=1&enablejsapi=1&rel=0&origin=' + encodeURIComponent(location.origin);
  _sap.loadT = setTimeout(() => {
    // Nothing started within 15 s → say why instead of hanging on ⏸.
    if (_sap && _sap.idx === i && _sap.state !== 1 && _sap.time === 0) {
      _sap.state = -1;
      _sapSync();
      _sapWarn(i, _sapOnline() ? _sapFailText() : _sapOfflineText());
    }
  }, 15000);
  _sapSync();
  if (scroll) {
    try { _sap.tracks[i].ui.el.scrollIntoView({ behavior: 'smooth', block: 'center' }); } catch (_e) {}
  }
}

function _sapToggle(i) {
  if (!_sap) return;
  if (_sap.idx !== i || _sap.state === 0 || _sap.state === -1) { _sapPlay(i); return; }
  if (_sap.state === 1 || _sap.state === 3) { _sapCmd('pauseVideo'); _sap.state = 2; }
  else { _sapCmd('playVideo'); _sap.state = 1; }
  _sapSync();
}

function _sapOnMessage(ev) {
  if (!_sap || !_sap.frame || ev.source !== _sap.frame.contentWindow) return;
  let d = ev.data;
  if (typeof d === 'string') { try { d = JSON.parse(d); } catch (_e) { return; } }
  if (!d || typeof d !== 'object') return;
  const last = _sap.tracks.length - 1;
  const onState = (st) => {
    _sap.state = st;
    if (st === 1) { _sap.played = true; clearTimeout(_sap.loadT); _sapClearMsg(_sap.idx); }
    // YouTube reports "ended" twice (onStateChange + infoDelivery) and stale events
    // from the previous pad can still arrive after switching. Advance only once,
    // and only if the current pad actually played — otherwise pads get skipped.
    if (st === 0) {
      if (!_sap.played) return true;   // duplicate / stale ended event → ignore
      _sap.played = false;
      if (_sap.idx < last) { _sapPlay(_sap.idx + 1, true); return true; }
    }
    return false;
  };
  if (d.event === 'onStateChange' && typeof d.info === 'number') {
    if (onState(d.info)) return;
  } else if (d.event === 'infoDelivery' && d.info) {
    if (typeof d.info.playerState === 'number' && onState(d.info.playerState)) return;
    if (typeof d.info.currentTime === 'number') _sap.time = d.info.currentTime;
    if (typeof d.info.duration === 'number' && d.info.duration > 0) _sap.dur = d.info.duration;
  } else if (d.event === 'onError') {
    clearTimeout(_sap.loadT);
    _sap.state = -1;
    _sapSync();
    _sapWarn(_sap.idx, _sapOnline() ? _sapFailText() : _sapOfflineText());
    return;
  }
  _sapSync();
}

function closeSevaAudioPlayer() {
  if (!_sap) return;
  const s = _sap;
  _sap = null;
  try { clearInterval(s.watchT); clearTimeout(s.loadT); } catch (_e) {}
  try { window.removeEventListener('message', s.onMsg); } catch (_e) {}
  try { window.removeEventListener('offline', s.onOffline); window.removeEventListener('online', s.onOnline); } catch (_e) {}
  try { if (s.frame) s.frame.src = 'about:blank'; } catch (_e) {}
  try { if (s.vwrap) s.vwrap.remove(); } catch (_e) {}
}

// Called each time a Seva section is drawn: swaps every .video-link block for a
// permanent inline player. The previous section's audio is stopped.
function initSevaInlinePlayers(body) {
  closeSevaAudioPlayer();
  const hi = _sapHi();
  const found = [];
  Array.from(body.querySelectorAll('.video-link')).forEach((blk) => {
    const a = blk.querySelector('a[href]');
    const id = a && favvidDetectPlatform(a.href) === 'youtube' ? favvidYoutubeId(a.href) : '';
    if (!id) { blk.remove(); return; }
    found.push({
      blk: blk, id: id,
      title: (a.textContent || '').replace(/^\s*▶\s*(YouTube:)?\s*/i, '').trim(),
    });
  });
  if (!found.length) return;

  const banner = document.createElement('div');
  banner.className = 'sap-offline-banner';
  banner.textContent = _sapOfflineText();
  body.insertBefore(banner, body.firstChild);
  body.classList.toggle('sap-offline', !_sapOnline());

  const n = found.length;
  const tracks = found.map((f, i) => {
    const el = document.createElement('div');
    el.className = 'sap-inline';
    el.innerHTML =
      '<div class="sap-top">' +
        '<button class="sap-btn" data-a="prev" aria-label="prev">⏮</button>' +
        '<button class="sap-btn sap-main" data-a="play" aria-label="play/pause">▶</button>' +
        '<button class="sap-btn" data-a="next" aria-label="next">⏭</button>' +
        '<div class="sap-label"></div>' +
        '<span class="sap-count"></span>' +
        '<button class="sap-btn" data-a="video" aria-label="video" title="' + (hi ? 'वीडियो दिखाएँ' : 'ভিডিও দেখান') + '">🎬</button>' +
      '</div>' +
      '<div class="sap-row">' +
        '<span class="sap-time" data-r="cur">0:00</span>' +
        '<input type="range" min="0" max="1000" value="0" data-r="seek" disabled>' +
        '<span class="sap-time" data-r="tot">0:00</span>' +
      '</div>' +
      '<div class="sap-msg"></div>';
    el.querySelector('.sap-label').textContent = f.title;
    el.querySelector('.sap-count').textContent = (i + 1) + '/' + n;
    const ui = {
      el: el,
      play: el.querySelector('[data-a=play]'),
      cur: el.querySelector('[data-r=cur]'),
      tot: el.querySelector('[data-r=tot]'),
      seek: el.querySelector('[data-r=seek]'),
      msg: el.querySelector('.sap-msg'),
    };
    el.querySelector('[data-a=prev]').style.opacity = i > 0 ? '1' : '0.35';
    el.querySelector('[data-a=next]').style.opacity = i < n - 1 ? '1' : '0.35';

    el.addEventListener('click', (e) => {
      const b = e.target && e.target.closest ? e.target.closest('[data-a]') : null;
      if (!b || !_sap) return;
      const a = b.getAttribute('data-a');
      if (a === 'play') {
        _sapToggle(i);
      } else if (a === 'prev') {
        if (_sap.idx === i && _sap.time > 4) { _sapCmd('seekTo', [0, true]); _sap.time = 0; _sapSync(); }
        else if (i > 0) _sapPlay(i - 1, true);
      } else if (a === 'next') {
        if (i < n - 1) _sapPlay(i + 1, true);
      } else if (a === 'video') {
        if (_sap.idx !== i) _sapPlay(i);
        if (_sap.vwrap) _sap.vwrap.classList.toggle('show');
      }
    });
    ui.seek.addEventListener('input', () => { if (_sap && _sap.idx === i) _sap.scrubbing = true; });
    ui.seek.addEventListener('change', () => {
      if (!_sap || _sap.idx !== i) return;
      if (_sap.dur > 0) {
        const t = (ui.seek.value / 1000) * _sap.dur;
        _sapCmd('seekTo', [t, true]);
        _sap.time = t;
      }
      _sap.scrubbing = false;
      _sapSync();
    });
    f.blk.replaceWith(el);
    return { id: f.id, title: f.title, ui: ui };
  });

  _sap = {
    tracks: tracks, idx: -1, state: -1, time: 0, dur: 0, scrubbing: false,
    root: body, frame: null, vwrap: null, loadT: null,
    onMsg: _sapOnMessage,
    onOffline: () => {
      body.classList.add('sap-offline');
      if (_sap && _sap.idx >= 0 && (_sap.state === 1 || _sap.state === 3)) _sapWarn(_sap.idx);
    },
    onOnline: () => {
      body.classList.remove('sap-offline');
      if (_sap) _sap.tracks.forEach((_t, k) => _sapClearMsg(k));
    },
  };
  window.addEventListener('offline', _sap.onOffline);
  window.addEventListener('online', _sap.onOnline);
  // Stop the audio once this section is no longer in the page (person moved
  // to another section / folder / language).
  _sap.watchT = setInterval(() => {
    if (_sap && !_sap.root.isConnected) closeSevaAudioPlayer();
  }, 1000);
}

